'use strict';

const MAX_NAME_LENGTH = 255;
const BLOCK_SIZE = 4096;
const MAX_BLOCKS_PER_INODE = 65535;
const MAX_DIR_ENTRIES = 256;
const MAX_SYMLINK_BYTES = 1024;
const MODE_LIMIT = 128;
const MIN_CHUNK_BYTES = 64;
const MAX_XATTR_KEY_BYTES = 16;
const MAX_XATTR_VALUE_BYTES = 32;

function truncateName(name) {
  const text = String(name == null ? '' : name);
  return text.length > MAX_NAME_LENGTH ? text.slice(0, MAX_NAME_LENGTH) : text;
}

function normalizePermissions(mode) {
  const bits = Number.isInteger(mode) ? mode : 0;
  if (bits < 0) return 0;
  return bits > MODE_LIMIT ? MODE_LIMIT : bits;
}

function blockLayout(sizeBytes) {
  const size = Number.isFinite(sizeBytes) && sizeBytes > 0 ? Math.floor(sizeBytes) : 0;
  let blocks = Math.ceil(size / BLOCK_SIZE);
  let truncated = false;
  if (blocks > MAX_BLOCKS_PER_INODE) {
    blocks = MAX_BLOCKS_PER_INODE;
    truncated = true;
  }
  const tailBytes = size - (blocks - 1) * BLOCK_SIZE;
  const chunks = Math.ceil(tailBytes / MIN_CHUNK_BYTES) * MIN_CHUNK_BYTES;
  const tailChunk = blocks === 0 ? 0 : Math.max(MIN_CHUNK_BYTES, chunks);
  return { blocks, blockSize: BLOCK_SIZE, tailChunk, truncated };
}

function limitEntries(entries) {
  const list = Array.isArray(entries) ? entries : [];
  const kept = list.slice(0, MAX_DIR_ENTRIES);
  return { names: kept.map(truncateName), dropped: list.length - kept.length };
}

function clampSymlink(target) {
  const bytes = Buffer.from(String(target), 'utf8');
  if (bytes.length <= MAX_SYMLINK_BYTES) return String(target);
  return bytes.slice(0, MAX_SYMLINK_BYTES).toString('utf8');
}

function packXattrs(attrs) {
  const source = attrs && typeof attrs === 'object' ? attrs : {};
  const packed = {};
  for (const rawKey of Object.keys(source)) {
    const key = rawKey.slice(0, MAX_XATTR_KEY_BYTES);
    packed[key] = String(source[rawKey]).slice(0, MAX_XATTR_VALUE_BYTES);
  }
  return packed;
}

function formatInode(fileData) {
