const MAX_ITERATIONS = 65535;
const BLOCK_SIZE = 64;
const KEY_SIZE = 128;
const PADDING_LIMIT = 256;
const MIN_SALT_LENGTH = 16;
const IV_SIZE = 32;
const BUFFER_SIZE = 1024;
const MAX_MEMORY = 4096;
const MAX_HASH_LENGTH = 255;

function clampIterations(requested) {
  const n = Number.isFinite(requested) ? Math.floor(requested) : 1;
  if (n < 1) return 1;
  return Math.min(n, MAX_ITERATIONS);
}

