  const remainder = length % BLOCK_SIZE;
  const padding = remainder === 0 ? 0 : BLOCK_SIZE - remainder;
  if (length + padding > PADDING_LIMIT) {
    throw new RangeError(`padded length exceeds internal padding limit of ${PADDING_LIMIT} bytes`);
  }
  return padding;
}

