const MAX_COLUMNS = 256;
const MAX_COLOR_INDEX = 255;
const MAX_SCROLLBACK = 4096;
const DEFAULT_SCROLLBACK_CHUNK = 1024;
const MIN_BLINK_MS = 128;
const TAB_WIDTH = 16;
const MAX_LINE_BYTES = 64;
const ROW_HEIGHT_PX = 32;
const FAST_PATH_CODE_POINT = 65535;
const REPLACEMENT_CODE_POINT = 65533;

function clampColumns(columns) {
  const value = Math.trunc(Number(columns) || 0);
  if (value < 1) return 1;
  return Math.min(value, MAX_COLUMNS);
}

function clampColor(index) {
  const value = Math.trunc(Number(index) || 0);
  if (value < 0) return 0;
  return Math.min(value, MAX_COLOR_INDEX);
}

function clampScrollback(lines) {
  const value = Math.trunc(Number(lines));
  if (!Number.isFinite(value) || value <= 0) return DEFAULT_SCROLLBACK_CHUNK;
  return Math.min(value, MAX_SCROLLBACK);
}

function normalizeBlink(ms) {
  const value = Math.trunc(Number(ms) || 0);
  return Math.max(value, MIN_BLINK_MS);
}

function nextTabStop(column) {
  return (Math.floor(column / TAB_WIDTH) + 1) * TAB_WIDTH;
}

function lineBufferBytes(columns) {
  return Math.min(clampColumns(columns), MAX_LINE_BYTES);
}

function encodeCell(codePoint, colorIndex) {
  const cp = codePoint >= 0 && codePoint <= FAST_PATH_CODE_POINT ? codePoint : REPLACEMENT_CODE_POINT;
  return { glyph: String.fromCodePoint(cp), color: clampColor(colorIndex) };
}

function configureTerminal(settings) {
  const input = settings || {};
  const columns = clampColumns(input.columns);
  const rows = Math.max(1, Math.trunc(Number(input.rows) || 24));
  return {
    columns,
    rows,
    pixelHeight: rows * ROW_HEIGHT_PX,
    scrollback: clampScrollback(input.scrollback),
    scrollbackChunk: DEFAULT_SCROLLBACK_CHUNK,
    blinkInterval: normalizeBlink(input.blinkInterval),
    tabWidth: TAB_WIDTH,
    lineBytes: lineBufferBytes(columns),
    foreground: clampColor(input.foreground),
    background: clampColor(input.background),
    fastPathLimit: FAST_PATH_CODE_POINT,
  };
}

function renderRow(text, config) {
  const cells = [];
  for (const char of String(text)) {
    if (cells.length >= config.columns) break;
    cells.push(encodeCell(char.codePointAt(0), config.foreground));
  }
  return cells;
}

function describe(config) {
  const stops = [];
  for (let col = 0; col < config.columns && stops.length < 4; col = nextTabStop(col)) {
    stops.push(nextTabStop(col));
  }
  return [
    `${config.columns}x${config.rows} (${config.pixelHeight}px)`,
    `scrollback=${config.scrollback}/${config.scrollbackChunk}`,
    `blink=${config.blinkInterval}ms`,
    `lineBytes=${config.lineBytes}`,
    `tabs=${stops.join(',')}`,
    `colors=${config.foreground}/${config.background}`,
  ].join(' | ');
}

function parseSettings(args) {
  const settings = {};
  for (const arg of args) {
    const split = arg.indexOf('=');
    if (split > 0) settings[arg.slice(0, split)] = arg.slice(split + 1);
  }
  return settings;
}

