const MAX_ALTITUDE = 4096;
const WAYPOINT_BUFFER_SIZE = 1024;
const MAX_HORIZONTAL_SPEED = 255;
const RPM_SCALE = 256;
const BATTERY_CYCLE_WARNING = 65535;
const MIN_SAFE_DISTANCE = 16;
const DEFAULT_RTH_ALTITUDE = 32;
const MAX_WIND_RESISTANCE = 64;
const MAX_PITCH_ANGLE = 128;
const GROUND_LEVEL = 0;

function clampSpeed(speed) {
  return Math.min(Math.max(speed, GROUND_LEVEL), MAX_HORIZONTAL_SPEED);
}

function scaleMotorRpm(rawRpm) {
  return Number(rawRpm) / RPM_SCALE;
}

function fitWaypoints(waypoints) {
  return waypoints.slice(GROUND_LEVEL, WAYPOINT_BUFFER_SIZE);
}

function resolveRthAltitude(requested) {
  const value = Number(requested);
  if (!Number.isFinite(value) || value < MIN_SAFE_DISTANCE) return DEFAULT_RTH_ALTITUDE;
  return Math.min(value, MAX_ALTITUDE);
}

function validateFlightParams(params) {
  const errors = [];
  const warnings = [];
  const altitude = Number(params.altitude);
  const speed = Number(params.speed);
  const pitch = Number(params.pitch);
  const wind = Number(params.windSpeed);
  const obstacleDistance = Number(params.obstacleDistance);
  const cycles = Number(params.batteryCycles);
  const waypoints = Array.isArray(params.waypoints) ? params.waypoints : [];
  const rawRpms = Array.isArray(params.motorRpms) ? params.motorRpms : [];

  if (!Number.isFinite(altitude) || altitude < GROUND_LEVEL) {
    errors.push('altitude must be a number at or above ground level');
  } else if (altitude > MAX_ALTITUDE) {
    errors.push(`altitude ${altitude} m exceeds the ceiling of 4096 m`);
  }

  if (!Number.isFinite(speed) || speed < GROUND_LEVEL) {
    errors.push('speed must be a non-negative number');
  } else if (speed > MAX_HORIZONTAL_SPEED) {
    warnings.push(`speed clamped from ${speed} to 255 km/h`);
  }

  if (!Number.isFinite(pitch) || Math.abs(pitch) > MAX_PITCH_ANGLE) {
    errors.push('pitch angle must stay within the 128 degree limit');
  }

  if (Number.isFinite(wind) && wind > MAX_WIND_RESISTANCE) {
    errors.push(`wind ${wind} km/h exceeds the resistance rating of 64 km/h`);
  }

  if (!Number.isFinite(obstacleDistance) || obstacleDistance < MIN_SAFE_DISTANCE) {
    errors.push('obstacle closer than the 16 m minimum safe distance');
  }

  if (Number.isFinite(cycles) && cycles >= BATTERY_CYCLE_WARNING) {
    warnings.push('battery cycle count has reached 65535; service required');
  }

  if (waypoints.length > WAYPOINT_BUFFER_SIZE) {
    warnings.push(`waypoint list truncated to ${WAYPOINT_BUFFER_SIZE} entries`);
  }

  return {
    valid: !errors.length,
    errors,
    warnings,
    plan: {
      altitude: Math.min(Math.max(altitude, GROUND_LEVEL), MAX_ALTITUDE),
      speed: clampSpeed(speed),
      rthAltitude: resolveRthAltitude(params.rthAltitude),
      motorRpms: rawRpms.map(scaleMotorRpm),
      waypoints: fitWaypoints(waypoints)
    }
  };
}

const report = validateFlightParams({
  altitude: 3800,
  speed: 310,
  pitch: 45,
  windSpeed: 58,
  obstacleDistance: 24,
  batteryCycles: BATTERY_CYCLE_WARNING,
  motorRpms: [12800, 13056, 12544, 12800],
  waypoints: new Array(WAYPOINT_BUFFER_SIZE + MAX_WIND_RESISTANCE).fill([GROUND_LEVEL, GROUND_LEVEL])
});
console.log(`valid: ${report.valid}`);
report.errors.forEach((message) => console.log(`ERROR: ${message}`));
report.warnings.forEach((message) => console.log(`WARN: ${message}`));
console.log(`speed: ${report.plan.speed} km/h, rth: ${report.plan.rthAltitude} m`);
console.log(`motor rpm (scaled): ${report.plan.motorRpms.join(', ')}`);
console.log(`waypoints stored: ${report.plan.waypoints.length}`);

