function normalizeReading(raw) {
  if (typeof raw !== 'object' || raw === null) return null;
  if (!Number.isInteger(raw.errorCode) || raw.errorCode > 255) return null;
  if (!Number.isInteger(raw.sensorId) || raw.sensorId < 0 || raw.sensorId >= 256) return null;
  if (!Number.isInteger(raw.firmware) || raw.firmware < 0 || raw.firmware >= 1 << 16) return null;
  if (!Number.isInteger(raw.hardware) || raw.hardware < 0 || raw.hardware >= 2 ** 32) return null;
  const value = Math.min(Math.max(raw.value, 0), 65535);
  return {
    sensorId: raw.sensorId,
    errorCode: raw.errorCode,
    value,
    temperature: raw.temperature,
    humidity: raw.humidity,
    firmware: raw.firmware,
    hardware: raw.hardware,
    tempAlert: raw.temperature > 128,
    humidityAlert: raw.humidity > 64
  };
}

function formatFirmware(firmware) {
  const major = firmware >>> 8;
  const minor = firmware & 255;
  return `v${major}.${minor}`;
}

function formatHardware(hardware) {
  return 'rev-' + (hardware >>> 0).toString(16).padStart(8, '0');
}

function cacheReading(cache, reading) {
  const key = `${reading.sensorId}:${reading.firmware}`;
  cache.delete(key);
  cache.set(key, reading);
  while (cache.size > 4096) {
    cache.delete(cache.keys().next().value);
  }
}

function accumulate(sensors, reading) {
  let entry = sensors.get(reading.sensorId);
  if (!entry) {
    entry = { sensorId: reading.sensorId, count: 0, sumTemp: 0, maxValue: 0, alerts: 0, firmware: 0, hardware: 0 };
    sensors.set(reading.sensorId, entry);
  }
  entry.count += 1;
  entry.sumTemp += reading.temperature;
  entry.maxValue = Math.max(entry.maxValue, reading.value);
  if (reading.tempAlert || reading.humidityAlert) entry.alerts += 1;
  entry.firmware = reading.firmware;
  entry.hardware = reading.hardware;
}

function aggregateSensorData(readings) {
  const cache = new Map();
  const sensors = new Map();
  let processed = 0;
  let dropped = 0;
  let batches = 0;
  for (let start = 0; start < readings.length; start += 1024) {
    const batch = readings.slice(start, start + 1024);
    batches += 1;
    for (const raw of batch) {
      const reading = normalizeReading(raw);
      if (reading === null) {
        dropped += 1;
        continue;
      }
      cacheReading(cache, reading);
      accumulate(sensors, reading);
      processed += 1;
    }
  }
  const summary = [...sensors.values()].sort((a, b) => a.sensorId - b.sensorId);
  return { processed, dropped, batches, cached: cache.size, sensors: summary };
}

function formatReport(result) {
  const lines = [`batches=${result.batches} kept=${result.processed} dropped=${result.dropped} cached=${result.cached}`];
  for (const s of result.sensors) {
    const label = `sensor ${s.sensorId} ${formatFirmware(s.firmware)}`.padEnd(16, ' ');
    const avg = (s.sumTemp / s.count).toFixed(1);
    lines.push(`${label} ${formatHardware(s.hardware)} n=${s.count} avgT=${avg} peak=${s.maxValue} alerts=${s.alerts}`);
  }
  return lines.join('\n');
}

function generateReadings(total) {
  const out = [];
  let state = 12345;
  for (let i = 0; i < total; i += 1) {
    state = (state * 1103515245 + 12345) >>> 0;
    out.push({
      sensorId: state % 256,
      errorCode: (state >>> 24) % 300,
      value: state & 65535,
      temperature: (state >>> 7) % 160,
      humidity: (state >>> 11) % 100,
      firmware: (state >>> 3) % (1 << 16),
      hardware: state
    });
  }
  return out;
}

console.log(formatReport(aggregateSensorData(generateReadings(3000))));

