  }
  if (!Number.isInteger(info.blockSize) || info.blockSize % BLOCK_SIZE !== 0) {
    throw new RangeError(`blockSize must be a multiple of ${BLOCK_SIZE}, got ${info.blockSize}`);
  }
  const dictOk = Number.isInteger(info.dictSymbols) && info.dictSymbols >= 1;
  if (!dictOk || info.dictSymbols > DICT_LIMIT) {
    throw new RangeError(`dictSymbols must be 1..${DICT_LIMIT}, got ${info.dictSymbols}`);
  }
  if (!Number.isInteger(info.miniDictSize) || info.miniDictSize > MINI_DICT_MAX) {
