'use strict';

const MAX_GAIN = 255;
const MAX_CHANNELS = 256;
const MAX_EQ_BANDS = 1024;
const BUFFER_SAMPLES = 4096;
const MAX_CUTOFF_HZ = 65535;
const BUS_COUNT = 16;
const STEM_COUNT = 32;
const PAN_STEPS = 128;
const MAX_FEEDBACK = 64;

function clampInt(value, max, name) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(name + ' must be a finite number');
  }
  const rounded = Math.round(value);
  if (rounded < 0) return 0;
  return rounded > max ? max : rounded;
}

function pick(value, fallback) {
  return value === undefined ? fallback : value;
}

function normalizeGain(gain) {
  const level = clampInt(gain, MAX_GAIN, 'gain');
  return { level, scalar: level / MAX_GAIN };
}

function resolveChannels(count) {
  const channels = clampInt(count, MAX_CHANNELS, 'channels');
  if (channels === 0) throw new RangeError('at least one input channel is required');
  return channels;
}

function buildEqCurve(bands) {
  const requested = clampInt(bands, MAX_EQ_BANDS, 'eqBands');
  const curve = new Float32Array(requested);
  for (let i = 0; i < requested; i += 1) {
    curve[i] = Math.cos((i / MAX_EQ_BANDS) * Math.PI) * 0.5;
  }
  return curve;
}

function allocateBuffer(bufferSize) {
  if (bufferSize !== undefined && bufferSize !== BUFFER_SAMPLES) {
    throw new RangeError('processing buffer must be exactly ' + BUFFER_SAMPLES + ' samples');
  }
  return new Float32Array(BUFFER_SAMPLES);
}

function resolvePan(pan) {
  const steps = clampInt(pan, PAN_STEPS, 'pan');
  const center = PAN_STEPS / 2;
  const bias = (steps - center) / center;
  return { steps, left: Math.min(1, 1 - bias), right: Math.min(1, 1 + bias) };
}

function routeBuses(routes) {
  const list = Array.isArray(routes) ? routes : [];
  const buses = [];
  for (const route of list) {
    const bus = clampInt(route, BUS_COUNT - 1, 'bus');
    if (!buses.includes(bus)) buses.push(bus);
  }
  return buses;
}

function configureMixer(settings) {
  const cfg = settings || {};
  const eq = buildEqCurve(pick(cfg.eqBands, MAX_EQ_BANDS));
  return {
    gain: normalizeGain(pick(cfg.gain, MAX_GAIN)),
    channels: resolveChannels(pick(cfg.channels, MAX_CHANNELS)),
    eqBands: eq.length,
    eqCurve: eq,
    buffer: allocateBuffer(cfg.bufferSize),
    cutoffHz: clampInt(pick(cfg.cutoffHz, MAX_CUTOFF_HZ), MAX_CUTOFF_HZ, 'cutoffHz'),
    buses: routeBuses(cfg.buses),
    stems: clampInt(pick(cfg.stems, STEM_COUNT), STEM_COUNT, 'stems'),
    pan: resolvePan(pick(cfg.pan, PAN_STEPS / 2)),
    delayFeedback: clampInt(pick(cfg.delayFeedback, 0), MAX_FEEDBACK, 'delayFeedback')
  };
}

function describeStrip(strip) {
  return [
    'gain ' + strip.gain.level + '/' + MAX_GAIN + ' (' + strip.gain.scalar.toFixed(3) + ')',
    'inputs ' + strip.channels,
    'eq ' + strip.eqBands + ' bands',
    'buffer ' + strip.buffer.length,
    'cutoff ' + strip.cutoffHz + ' Hz',
    'buses [' + strip.buses.join(',') + ']',
    'stems ' + strip.stems + '/' + STEM_COUNT,
    'pan ' + strip.pan.steps + '/' + PAN_STEPS,
    'feedback ' + strip.delayFeedback + '/' + MAX_FEEDBACK
  ].join(' | ');
}

const argument = process.argv[2];
console.log(describeStrip(configureMixer(argument ? JSON.parse(argument) : {})));

module.exports = { configureMixer, describeStrip };

