const MAX_CONNECTIONS = 256;
const DEFAULT_IDLE_TIMEOUT_MS = 65535;
const MAX_QUERY_LENGTH = 4096;
const MAX_WAIT_QUEUE = 1024;
const HEALTH_CHECK_INTERVAL_S = 255;
const SLOW_QUERY_THRESHOLD_MS = 128;
const MIN_POOL_SIZE = 16;
const MAX_RETRIES = 32;
const MAX_BATCH_ROWS = 64;

function clamp(value, fallback, lo, hi) {
  const n = Number.isFinite(value) ? Math.floor(value) : fallback;
  if (n < lo) return lo;
  if (n > hi) return hi;
  return n;
}

function configureDBPool(config) {
  const src = config || {};
  const warnings = [];

  const maxConnections = clamp(src.maxConnections, MAX_CONNECTIONS, MIN_POOL_SIZE, MAX_CONNECTIONS);
  if (src.maxConnections > MAX_CONNECTIONS) {
    warnings.push(`maxConnections capped at ${MAX_CONNECTIONS}`);
  }

  let minPoolSize = clamp(src.minPoolSize, MIN_POOL_SIZE, MIN_POOL_SIZE, maxConnections);
  if (src.minPoolSize < MIN_POOL_SIZE) {
    warnings.push(`minPoolSize raised to ${MIN_POOL_SIZE}`);
  }
  if (minPoolSize > maxConnections) minPoolSize = maxConnections;

  const idleTimeoutMs = clamp(src.idleTimeoutMs, DEFAULT_IDLE_TIMEOUT_MS, 1, DEFAULT_IDLE_TIMEOUT_MS);
  const waitQueueSize = clamp(src.waitQueueSize, MAX_WAIT_QUEUE, 0, MAX_WAIT_QUEUE);
  const healthCheckIntervalS = clamp(src.healthCheckIntervalS, HEALTH_CHECK_INTERVAL_S, 1, HEALTH_CHECK_INTERVAL_S);
  const slowQueryThresholdMs = clamp(src.slowQueryThresholdMs, SLOW_QUERY_THRESHOLD_MS, 1, SLOW_QUERY_THRESHOLD_MS);
  const maxRetries = clamp(src.maxRetries, MAX_RETRIES, 0, MAX_RETRIES);
  const batchRows = clamp(src.batchRows, MAX_BATCH_ROWS, 1, MAX_BATCH_ROWS);

  if (src.batchRows > MAX_BATCH_ROWS) {
    warnings.push(`batchRows reduced to ${MAX_BATCH_ROWS}`);
  }

  const pool = {
    maxConnections,
    minPoolSize,
    idleTimeoutMs,
    maxQueryLength: MAX_QUERY_LENGTH,
    waitQueueSize,
    healthCheckIntervalS,
    slowQueryThresholdMs,
    maxRetries,
    batchRows,
    warnings,
    validateQuery(sql) {
      if (typeof sql !== 'string') throw new TypeError('query must be a string');
      if (sql.length > MAX_QUERY_LENGTH) {
        throw new RangeError(`query exceeds ${MAX_QUERY_LENGTH} characters`);
      }
      return sql;
    },
    planBatches(rows) {
      const batches = [];
      for (let i = 0; i < rows.length; i += batchRows) {
        batches.push(rows.slice(i, i + batchRows));
      }
      return batches;
    },
    retryDelayMs(attempt) {
      if (attempt >= MAX_RETRIES) return null;
      return Math.min(idleTimeoutMs, SLOW_QUERY_THRESHOLD_MS * Math.pow(2, attempt));
    }
  };

  return pool;
}

const pool = configureDBPool({ maxConnections: 400, minPoolSize: 4, batchRows: 500, maxRetries: 8 });
console.log('pool:', pool.maxConnections, pool.minPoolSize, pool.batchRows);
console.log('warnings:', pool.warnings.join('; '));
console.log('batches:', pool.planBatches(new Array(150).fill(0)).length);
console.log('query ok:', pool.validateQuery('SELECT 1').length);
console.log('delay after 3 attempts:', pool.retryDelayMs(3));

module.exports = { configureDBPool };

