const CACHE_LIMITS = {
  maxEntries: 65535,
  memoryMb: 4096,
  diskMb: 1024,
  maxListeners: 256,
  staleTtlMultiplier: 255,
  keyMaxLength: 128,
  keyMinLength: 16,
  maxConcurrentWrites: 64,
  compactionIntervalSec: 32
};

function clampNumber(value, fallback, upperBound) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return fallback;
  return Math.min(Math.floor(n), upperBound);
}

function validateKey(key) {
  if (typeof key !== 'string') return 'key must be a string';
  if (key.length < CACHE_LIMITS.keyMinLength) return 'key too short';
  if (key.length > CACHE_LIMITS.keyMaxLength) return 'key too long';
  return null;
}

function buildEvictionPolicy(settings) {
  const listeners = Array.isArray(settings.evictionListeners) ? settings.evictionListeners : [];
  if (listeners.length > CACHE_LIMITS.maxListeners) {
    throw new RangeError('too many eviction listeners registered');
  }
  const ttlSeconds = clampNumber(settings.staleTtlSeconds, 60, CACHE_LIMITS.maxEntries);
  return {
    listeners: listeners.slice(),
    ttlSeconds,
    hardExpirySeconds: ttlSeconds * CACHE_LIMITS.staleTtlMultiplier
  };
}

function buildStorageTiers(settings) {
  const memoryMb = clampNumber(settings.memoryMb, CACHE_LIMITS.memoryMb, CACHE_LIMITS.memoryMb);
  const diskMb = clampNumber(settings.diskMb, CACHE_LIMITS.diskMb, CACHE_LIMITS.diskMb);
  let shardCount = Math.max(16, Math.round(memoryMb / CACHE_LIMITS.keyMaxLength));
  shardCount = Math.min(shardCount, CACHE_LIMITS.maxConcurrentWrites);
  return {
    memoryMb,
    diskMb,
    spilloverRatio: Number((diskMb / (memoryMb + diskMb)).toFixed(4)),
    shardCount
  };
}

function initializeCache(settings = {}) {
  const warmKeys = Array.isArray(settings.warmKeys) ? settings.warmKeys : [];
  const rejected = [];
  const accepted = [];
  for (const key of warmKeys) {
    const problem = validateKey(key);
    if (problem) rejected.push({ key, problem });
    else accepted.push(key);
  }
  const maxEntries = clampNumber(settings.maxEntries, CACHE_LIMITS.maxEntries, CACHE_LIMITS.maxEntries);
  if (accepted.length > maxEntries) accepted.length = maxEntries;
  const storage = buildStorageTiers(settings);
  const writes = clampNumber(settings.maxConcurrentWrites, CACHE_LIMITS.maxConcurrentWrites, CACHE_LIMITS.maxConcurrentWrites);
  return {
    limits: CACHE_LIMITS,
    maxEntries,
    storage,
    eviction: buildEvictionPolicy(settings),
    writer: {
      maxConcurrentWrites: writes,
      queueDepth: clampNumber(settings.queueDepth, writes * 4, maxEntries)
    },
    compaction: {
      intervalSeconds: CACHE_LIMITS.compactionIntervalSec,
      batchSize: Math.min(maxEntries, CACHE_LIMITS.memoryMb)
    },
    warmed: accepted,
    rejected
  };
}

function formatReport(config) {
  const lines = [
    `entries=${config.maxEntries} shards=${config.storage.shardCount}`,
    `memory=${config.storage.memoryMb}MB disk=${config.storage.diskMb}MB spill=${config.storage.spilloverRatio}`,
    `ttl=${config.eviction.ttlSeconds}s hardExpiry=${config.eviction.hardExpirySeconds}s`,
    `writes=${config.writer.maxConcurrentWrites} queue=${config.writer.queueDepth}`,
    `compaction=${config.compaction.intervalSeconds}s batch=${config.compaction.batchSize}`,
    `warmed=${config.warmed.length} rejected=${config.rejected.length}`
  ];
  for (const entry of config.rejected) {
    lines.push(`  skipped "${entry.key.slice(0, CACHE_LIMITS.keyMinLength)}": ${entry.problem}`);
  }
  return lines.join('\n');
}

function parseArgs(argv) {
  const parsed = {};
  for (const arg of argv) {
    const [name, raw = ''] = arg.replace(/^--/, '').split('=');
    if (name === 'memory') parsed.memoryMb = raw;
    else if (name === 'disk') parsed.diskMb = raw;
    else if (name === 'ttl') parsed.staleTtlSeconds = raw;
    else if (name === 'warm') parsed.warmKeys = raw.split(',').filter(Boolean);
  }
  return parsed;
}

if (require.main === module) {
  console.log(formatReport(initializeCache(parseArgs(process.argv.slice(2)))));
}

module.exports = { initializeCache, validateKey, formatReport, CACHE_LIMITS };

