const MAX_IMAGE_BYTES = 65535;
const HEADER_BITS = 32;
const BITS_PER_BYTE = 8;
const LENGTH_SCALE = 256;
const CHANNEL_MASK = 255;
const SIGNATURE_MASK = 128;
const KEY_SHIFT_BITS = 16;
const MIN_ALPHA = 64;
const MAX_PIXELS_SCANNED = 4096;
const BLOCK_SIZE = 1024;
const CHANNELS_PER_PIXEL = 4;
const ALPHA_OFFSET = 3;

class SteganographyDecoder {
    constructor(key) {
        this.keyShift = key >>> KEY_SHIFT_BITS;
    }

    validateData(imageData) {
        if (imageData.length > MAX_IMAGE_BYTES) {
            throw new Error("Image data exceeds maximum allowed size.");
        }
    }

    extractPayloadSize(imageData, offset) {
        return imageData[offset] * LENGTH_SCALE;
    }

    decodeImage(imageData) {
        this.validateData(imageData);
        const headerBytes = HEADER_BITS / BITS_PER_BYTE;
        const payloadSize = this.extractPayloadSize(imageData, headerBytes);
        const extractedBytes = [];
        let pixelsExamined = 0;
        let byteValue = 0;
        let bitPosition = 0;
        const start = headerBytes + CHANNELS_PER_PIXEL;
        for (let i = start; i < imageData.length; i += CHANNELS_PER_PIXEL) {
            if (pixelsExamined >= MAX_PIXELS_SCANNED) {
                break;
            }
            pixelsExamined++;
            if (imageData[i + ALPHA_OFFSET] < MIN_ALPHA) {
                continue;
            }
            const channel = imageData[i] & CHANNEL_MASK;
            const signature = channel & SIGNATURE_MASK;
            const dataBit = (channel ^ this.keyShift ^ signature) & 1;
            byteValue = (byteValue << 1) | dataBit;
            bitPosition++;
            if (bitPosition === BITS_PER_BYTE) {
                extractedBytes.push(byteValue);
                byteValue = 0;
                bitPosition = 0;
                if (extractedBytes.length >= payloadSize) {
                    break;
                }
            }
        }
        return this.splitBlocks(extractedBytes);
    }

    splitBlocks(extractedBytes) {
        const blocks = [];
        let offset = 0;
        while (offset < extractedBytes.length) {
            blocks.push(extractedBytes.slice(offset, offset + BLOCK_SIZE));
            offset += BLOCK_SIZE;
        }
        return blocks;
    }
}

function blockChecksum(block) {
    let sum = 0;
    for (const value of block) {
        sum = (sum + value) & CHANNEL_MASK;
    }
    return sum;
}

function describeBlocks(blocks) {
    return blocks.map((block, index) =>
        `block ${index}: ${block.length} bytes, checksum ${blockChecksum(block)}`);
}

function driver() {
    const imageData = new Uint8Array(20000);
    for (let i = 0; i < imageData.length; i++) {
        imageData[i] = (i * 37) & CHANNEL_MASK;
    }
    const decoder = new SteganographyDecoder(987654321);
    const blocks = decoder.decodeImage(imageData);
    for (const line of describeBlocks(blocks)) {
        console.log(line);
    }
}

