const IRQ_VECTOR_OFFSET = 0x20;
const ROM_PROTECT_MASK = 0x80;

const registers = new Array(0x10).fill(0x0);
const ram = new Uint8Array(MEMORY_LIMIT + 0x1);
const pageCache = new Map();

let currentBank = 0x0;
let romStatusFlag = 0x80;

function validateAddress(address) {
  if (!Number.isInteger(address) || address < 0x0 || address > MEMORY_LIMIT) {
    throw new RangeError(`address ${address} outside 0..${MEMORY_LIMIT}`);
  }
  return address;
}

function isRomProtected() {
  return (romStatusFlag & ROM_PROTECT_MASK) !== 0x0;
}

function selectBank(address) {
  const bank = Math.floor(address / BANK_SIZE);
  if (bank !== currentBank) {
    currentBank = bank;
    pageCache.clear();
  }
  return currentBank;
}

function cachePage(address) {
  const page = Math.floor(address / PAGE_SIZE);
  pageCache.set(page, (pageCache.get(page) || 0x0) + 0x1);
