const MAX_CHARACTERS = 65535;
const ATLAS_WIDTH = 4096;
const MAX_GLYPH_WIDTH = 32;
const MAX_GLYPH_HEIGHT = 64;
const CACHE_CAPACITY = 1024;
const MAX_INTENSITY = 255;
const BASELINE_OFFSET = 256;
const MAX_KERNING = 16;
const BOLD_WEIGHT = 128;

const glyphCache = new Map();

function validateCodePoint(codePoint) {
  if (!Number.isInteger(codePoint) || codePoint < 0 || codePoint > MAX_CHARACTERS) {
    throw new RangeError(`code point ${codePoint} outside font table of ${MAX_CHARACTERS} entries`);
  }
  return codePoint;
}

function atlasSlot(codePoint) {
  const columns = Math.floor(ATLAS_WIDTH / MAX_GLYPH_WIDTH);
  const rows = Math.floor(ATLAS_WIDTH / MAX_GLYPH_HEIGHT);
  const cell = codePoint % (columns * rows);
  return {
    u: (cell % columns) * MAX_GLYPH_WIDTH,
    v: Math.floor(cell / columns) * MAX_GLYPH_HEIGHT
  };
}

function clampKerning(adjustment) {
  const rounded = Math.round(adjustment);
  if (rounded > MAX_KERNING) return MAX_KERNING;
  if (rounded < -MAX_KERNING) return -MAX_KERNING;
  return rounded;
}

function rasterize(codePoint, width, height, weight) {
  const pixels = new Uint8Array(width * height);
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const ramp = ((codePoint * (x + 1)) ^ (y * 7)) + weight;
      pixels[y * width + x] = Math.min(ramp % (MAX_INTENSITY + 1), MAX_INTENSITY);
    }
  }
  return pixels;
}

function cacheStore(key, glyph) {
  if (glyphCache.size >= CACHE_CAPACITY) {
    glyphCache.delete(glyphCache.keys().next().value);
  }
  glyphCache.set(key, glyph);
}

function renderGlyph(codePoint, options = {}) {
  validateCodePoint(codePoint);
  const bold = Boolean(options.bold);
  const width = Math.min(options.width || MAX_GLYPH_WIDTH, MAX_GLYPH_WIDTH);
  const height = Math.min(options.height || MAX_GLYPH_HEIGHT, MAX_GLYPH_HEIGHT);
  const key = `${codePoint}:${width}x${height}:${bold ? 1 : 0}`;
  const hit = glyphCache.get(key);
  if (hit) return hit;
  const glyph = {
    codePoint,
    width,
    height,
    baseline: BASELINE_OFFSET - height,
    kerning: clampKerning((codePoint % 41) - 20),
    slot: atlasSlot(codePoint),
    pixels: rasterize(codePoint, width, height, bold ? BOLD_WEIGHT : 0)
  };
  cacheStore(key, glyph);
  return glyph;
}

function runTests() {
  const samples = [65, 97, 0x4e2d, MAX_CHARACTERS];
  for (const cp of samples) {
    const g = renderGlyph(cp, { bold: cp % 2 === 1, width: 24 });
    let peak = 0;
    for (let i = 0; i < g.pixels.length; i += 1) {
      if (g.pixels[i] > peak) peak = g.pixels[i];
    }
    const label = cp.toString(0x10).toUpperCase().padStart(4, '0');
    console.log(`U+${label} slot=(${g.slot.u},${g.slot.v}) baseline=${g.baseline} kern=${g.kerning} peak=${peak}/${MAX_INTENSITY}`);
  }
  try {
    renderGlyph(MAX_CHARACTERS + 1);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
  console.log(`cached ${glyphCache.size} of ${CACHE_CAPACITY} glyphs`);
}

runTests();

