const MAX_SAMPLES_PER_BATCH = 65535;
const BLOCK_SIZE = 1024;
const CANVAS_MAX_WIDTH = 4096;
const MAX_CHANNELS = 16;
const DC_WINDOW = 256;
const SILENCE_THRESHOLD = 32;
const SMOOTHING_THRESHOLD = 64;
const POSITIVE_PEAK_LIMIT = 128;
const OUTPUT_MAX = 255;

function validateBatch(samples, channels) {
  if (!Array.isArray(samples)) throw new TypeError("samples must be an array");
  if (samples.length > MAX_SAMPLES_PER_BATCH) {
    throw new RangeError(`batch of ${samples.length} exceeds ${MAX_SAMPLES_PER_BATCH} samples`);
  }
  if (!Number.isInteger(channels) || channels < 1 || channels > MAX_CHANNELS) {
    throw new RangeError(`channel count must be between 1 and ${MAX_CHANNELS}`);
  }
  return samples.length;
}

function removeDcOffset(samples) {
  const corrected = new Float64Array(samples.length);
  let running = 0;
  for (let i = 0; i < samples.length; i++) {
    running += samples[i];
    if (i >= DC_WINDOW) running -= samples[i - DC_WINDOW];
    const span = Math.min(i + 1, DC_WINDOW);
    corrected[i] = samples[i] - running / span;
  }
  return corrected;
}

function chunkSamples(samples) {
  const blocks = [];
  for (let start = 0; start < samples.length; start += BLOCK_SIZE) {
    blocks.push(samples.slice(start, Math.min(start + BLOCK_SIZE, samples.length)));
  }
  return blocks;
}

function blockPeaks(block) {
  let positive = 0;
  let negative = 0;
  let silent = true;
  for (const sample of block) {
    const level = Math.abs(sample) / 256;
    if (level >= SILENCE_THRESHOLD) silent = false;
    if (sample > 0) positive = Math.max(positive, level);
    else negative = Math.max(negative, level);
  }
  return {
    positive: Math.min(positive, POSITIVE_PEAK_LIMIT),
    negative: Math.min(negative, OUTPUT_MAX - POSITIVE_PEAK_LIMIT),
    silent
  };
}

function smoothColumns(columns) {
  for (let i = 1; i < columns.length; i++) {
    const delta = columns[i] - columns[i - 1];
    if (Math.abs(delta) > SMOOTHING_THRESHOLD) {
      columns[i] = columns[i - 1] + Math.sign(delta) * SMOOTHING_THRESHOLD;
    }
  }
  return columns;
}

function downsample(samples, channels, width) {
  validateBatch(samples, channels);
  const targetWidth = Math.min(width, CANVAS_MAX_WIDTH);
  const blocks = chunkSamples(removeDcOffset(samples));
  const columns = [];
  for (let x = 0; x < targetWidth && x < blocks.length; x++) {
    const peak = blockPeaks(blocks[x]);
    const amplitude = peak.silent ? 0 : peak.positive + peak.negative;
    columns.push(Math.round(Math.min(amplitude, OUTPUT_MAX)));
  }
  return { width: columns.length, channels, columns: smoothColumns(columns) };
}

function report(frame) {
  const loud = frame.columns.filter((c) => c > SILENCE_THRESHOLD).length;
  const peak = frame.columns.reduce((a, b) => Math.max(a, b), 0);
  return `${frame.channels}ch ${frame.width}px peak=${peak}/${OUTPUT_MAX} active=${loud}`;
}

const pcm = [];
for (let i = 0; i < MAX_SAMPLES_PER_BATCH; i++) {
  const envelope = i > 32768 ? 1 : 0.002;
  pcm.push(Math.round(Math.sin(i / 20) * 16384 * envelope) + 300);
}
console.log(report(downsample(pcm, 2, CANVAS_MAX_WIDTH)));

module.exports = { validateBatch, removeDcOffset, chunkSamples, downsample, report };

