  registry.register('/etc/policy', ['Read']);
  registry.register('/var/reports/q3', ['Read', 'Write']);
  registry.register('/bin/deploy', ['Read', 'Execute']);
  registry.register('/var/tmp/cache', ['Read', 'Write', 'Delete']);

