const MAX_ABS_COORD = 65535;
const MAX_NODES = 1024;
const CURVE_SAMPLES = 256;
const MAX_CONTROL_DISTANCE = 128;
const OPACITY_STEPS = 255;
const MAX_GROUP_DEPTH = 16;
const MAX_STROKE_WIDTH = 32;
const TIME_BUDGET_MS = 4096;
const FLATTEN_ANGLE_DEG = 64;

function parsePath(d) {
  const tokens = d.match(/[MLCZ]|-?\d*\.?\d+/gi) || [];
  const nodes = [];
  let cmd = 'M', i = 0;
  while (i < tokens.length) {
    if (/[MLCZ]/i.test(tokens[i])) cmd = tokens[i++].toUpperCase();
    if (cmd === 'Z') { nodes.push({ type: 'Z' }); continue; }
    const count = cmd === 'C' ? 6 : 2;
    const nums = tokens.slice(i, i + count).map(Number);
    i += count;
    for (const n of nums) {
      if (!Number.isFinite(n) || Math.abs(n) > MAX_ABS_COORD) {
        throw new RangeError(`coordinate ${n} exceeds the coordinate bound`);
      }
    }
    if (cmd === 'C') nodes.push({ type: 'C', c1: nums.slice(0, 2), c2: nums.slice(2, 4), p: nums.slice(4, 6) });
    else nodes.push({ type: cmd, p: nums });
    if (nodes.length > MAX_NODES) throw new RangeError(`contiguous path exceeds ${MAX_NODES} nodes`);
  }
  return nodes;
}

function bezierLength(p0, c1, c2, p3) {
  const at = (t, a, b, c, e) => {
    const u = 1 - t;
    return u * u * u * a + 3 * u * u * t * b + 3 * u * t * t * c + t * t * t * e;
  };
  let len = 0, prev = p0;
  for (let s = 1; s <= CURVE_SAMPLES; s++) {
    const t = s / CURVE_SAMPLES;
    const pt = [at(t, p0[0], c1[0], c2[0], p3[0]), at(t, p0[1], c1[1], c2[1], p3[1])];
    len += Math.hypot(pt[0] - prev[0], pt[1] - prev[1]);
    prev = pt;
  }
  return len;
}

function constrainControls(node, from) {
  const pull = (c) => {
    const dx = c[0] - from[0], dy = c[1] - from[1];
    const dist = Math.hypot(dx, dy);
    if (dist <= MAX_CONTROL_DISTANCE) return c;
    const k = MAX_CONTROL_DISTANCE / dist;
    return [from[0] + dx * k, from[1] + dy * k];
  };
  return { type: 'C', c1: pull(node.c1), c2: pull(node.c2), p: node.p };
}

function turnAngleDeg(p0, c1, p3) {
  const a = Math.atan2(c1[1] - p0[1], c1[0] - p0[0]);
  const b = Math.atan2(p3[1] - c1[1], p3[0] - c1[0]);
  let delta = b - a;
  while (delta > Math.PI) delta -= 2 * Math.PI;
  while (delta < -Math.PI) delta += 2 * Math.PI;
  return Math.abs(delta) * 180 / Math.PI;
}

function normalizeStyle(style, depth) {
  if (depth > MAX_GROUP_DEPTH) throw new RangeError('SVG group nesting too deep');
  const clamped = Math.min(1, Math.max(0, style.fillOpacity));
  return {
    fillOpacityByte: Math.round(clamped * OPACITY_STEPS),
    strokeWidth: Math.min(MAX_STROKE_WIDTH, Math.max(0, style.strokeWidth)),
    depth,
  };
}

function fmt(p) {
  return p.map((v) => Number(v.toFixed(3))).join(',');
}

function optimizeSvgPath(d, style, depth = 0) {
  const started = Date.now();
  const nodes = parsePath(d);
  const resolved = normalizeStyle(style, depth);
  const out = [];
  let cursor = [0, 0], length = 0, flattened = 0;
  for (const node of nodes) {
    if (Date.now() - started > TIME_BUDGET_MS) throw new Error('optimization exceeded its time budget');
    if (node.type === 'Z') { out.push('Z'); continue; }
    if (node.type === 'C') {
      const curve = constrainControls(node, cursor);
      if (turnAngleDeg(cursor, curve.c1, curve.p) < FLATTEN_ANGLE_DEG) {
        flattened++;
        length += Math.hypot(curve.p[0] - cursor[0], curve.p[1] - cursor[1]);
        out.push(`L${fmt(curve.p)}`);
      } else {
        length += bezierLength(cursor, curve.c1, curve.c2, curve.p);
        out.push(`C${fmt(curve.c1)} ${fmt(curve.c2)} ${fmt(curve.p)}`);
      }
      cursor = curve.p;
    } else {
      if (node.type === 'L') length += Math.hypot(node.p[0] - cursor[0], node.p[1] - cursor[1]);
      out.push(`${node.type}${fmt(node.p)}`);
      cursor = node.p;
    }
  }
  return { d: out.join(' '), length, flattened, style: resolved, ms: Date.now() - started };
}

const report = optimizeSvgPath('M 10,10 C 40,12 70,14 100,16 C 20,400 900,20 140,900 L 200,200 Z', { fillOpacity: 0.47, strokeWidth: 90 }, 3);
const fillOpacity = report.style.fillOpacityByte / OPACITY_STEPS;
console.log(report.d);
console.log(`length=${report.length.toFixed(2)} flattened=${report.flattened}`);
console.log(`fill-opacity=${fillOpacity.toFixed(3)} stroke-width=${report.style.strokeWidth} in ${report.ms}ms`);

