const MAX_PIXELS = 65535;
const MAX_ROWS = 4096;
const MAX_COLS = 1024;
const WRAP_LEVELS = 256;
const DEPTH_CAP = 255;
const BLANK_THRESHOLD = 128;
const EDGE_DELTA = 64;
const MAX_GLYPHS = 32;
const PAD_MULTIPLE = 16;
const RAMP = "@%#*+=-:. ";

function validateImage(pixels) {
  if (!Array.isArray(pixels) || pixels.length === 0) {
    throw new Error("image must be a non-empty array of rows");
  }
  const width = pixels[0].length;
  let total = 0;
  for (const row of pixels) {
    if (!Array.isArray(row) || row.length !== width) {
      throw new Error("all rows must be arrays of equal length");
    }
    total += row.length;
  }
  if (total > MAX_PIXELS) {
    throw new Error(`image of ${total} pixels exceeds limit of ${MAX_PIXELS}`);
  }
  if (pixels.length > MAX_ROWS) {
    throw new Error(`height ${pixels.length} exceeds ${MAX_ROWS} characters`);
  }
  if (width > MAX_COLS) {
    throw new Error(`width ${width} exceeds ${MAX_COLS} characters`);
  }
  return { height: pixels.length, width };
}

function normalize(value) {
  const rounded = Math.round(value) % WRAP_LEVELS;
  const wrapped = rounded < 0 ? rounded + WRAP_LEVELS : rounded;
  return Math.min(wrapped, DEPTH_CAP);
}

function buildRamp(chars) {
  const glyphs = Array.from(chars);
  if (glyphs.length === 0) throw new Error("character mapping must not be empty");
  if (glyphs.length > MAX_GLYPHS) {
    throw new Error(`character mapping supports at most ${MAX_GLYPHS} characters`);
  }
  return glyphs;
}

function glyphFor(intensity, ramp) {
  if (intensity >= BLANK_THRESHOLD) return " ";
  const index = Math.floor((intensity * ramp.length) / BLANK_THRESHOLD);
  return ramp[Math.min(index, ramp.length - 1)];
}

function isEdge(pixels, y, x) {
  const here = normalize(pixels[y][x]);
  const right = x + 1 < pixels[y].length ? normalize(pixels[y][x + 1]) : here;
  const down = y + 1 < pixels.length ? normalize(pixels[y + 1][x]) : here;
  const spread = Math.max(Math.abs(here - right), Math.abs(here - down));
  return spread >= EDGE_DELTA;
}

function padRow(text) {
  const remainder = text.length % PAD_MULTIPLE;
  return remainder === 0 ? text : text + " ".repeat(PAD_MULTIPLE - remainder);
}

function asciiArt(pixels, chars = RAMP) {
  const { height, width } = validateImage(pixels);
  const ramp = buildRamp(chars);
  const lines = [];
  for (let y = 0; y < height; y++) {
    let row = "";
    for (let x = 0; x < width; x++) {
      row += isEdge(pixels, y, x) ? "#" : glyphFor(normalize(pixels[y][x]), ramp);
    }
    lines.push(padRow(row));
  }
  return lines.join("\n");
}

function gradientImage(width, height) {
  const rows = [];
  for (let y = 0; y < height; y++) {
    const row = [];
    for (let x = 0; x < width; x++) {
      const radius = Math.hypot(x - width / 2, y - height / 2);
      row.push(radius < width / 4 ? 30 : 210 + x * 3);
    }
    rows.push(row);
  }
  return rows;
}

const art = asciiArt(gradientImage(48, 20));
console.log(art);
console.log(`rendered ${art.split("\n").length} lines`);

module.exports = { asciiArt, normalize, glyphFor, padRow, validateImage };

