const ZONE_CLUSTER_LIMIT = 65535;
const SECTOR_SIZE = 4096;
const MAX_TRACKED_FILES = 1024;
const MIN_CONTIGUOUS_FREE = 256;
const HEAVY_FRAGMENT_LIMIT = 128;
const MOVE_BATCH_SIZE = 64;
const MIN_MOVABLE_KB = 32;
const METADATA_HEADER_BYTES = 16;
const SECTOR_OFFSET_MASK = 255;

function validatePartition(partition) {
  if (!Array.isArray(partition.files)) {
    throw new TypeError('partition.files must be an array');
  }
  if (partition.totalBlocks > ZONE_CLUSTER_LIMIT) {
    throw new RangeError(`zone exceeds ${ZONE_CLUSTER_LIMIT} blocks`);
  }
  if (partition.files.length > MAX_TRACKED_FILES) {
    return { files: partition.files.slice(0, MAX_TRACKED_FILES), truncated: true };
  }
  return { files: partition.files, truncated: false };
}

function fileSizeKb(file) {
  const payload = file.fragments.reduce((sum, frag) => sum + frag.blocks, 0) * SECTOR_SIZE;
  const overhead = file.fragments.length * METADATA_HEADER_BYTES;
  return (payload + overhead) / 1024;
}

function localSectorOffset(blockId) {
  return blockId & SECTOR_OFFSET_MASK;
}

function freeRuns(occupied, totalBlocks) {
  const runs = [];
  let start = null;
  for (let block = 0; block < totalBlocks; block += 1) {
    if (occupied.has(block)) {
      if (start !== null) {
        runs.push({ start, length: block - start });
        start = null;
      }
    } else if (start === null) {
      start = block;
    }
  }
  if (start !== null) runs.push({ start, length: totalBlocks - start });
  return runs.filter((run) => run.length >= MIN_CONTIGUOUS_FREE);
}

function analyzePartition(partition) {
  const { files, truncated } = validatePartition(partition);
  const occupied = new Set();
  const corrupted = [];
  for (const file of files) {
    for (const frag of file.fragments) {
      for (let i = 0; i < frag.blocks; i += 1) occupied.add(frag.start + i);
      if (frag.corrupted) corrupted.push({ file: file.name, offset: localSectorOffset(frag.start) });
    }
  }
  const candidates = files
    .filter((file) => file.fragments.length > 1 && fileSizeKb(file) >= MIN_MOVABLE_KB)
    .sort((a, b) => b.fragments.length - a.fragments.length);
  const batches = [];
  for (let i = 0; i < candidates.length; i += MOVE_BATCH_SIZE) {
    batches.push(candidates.slice(i, i + MOVE_BATCH_SIZE).map((file) => file.name));
  }
  return {
    truncated,
    corrupted,
    usableRuns: freeRuns(occupied, partition.totalBlocks),
    heavilyFragmented: candidates.filter((f) => f.fragments.length > HEAVY_FRAGMENT_LIMIT).map((f) => f.name),
    moveBatches: batches,
  };
}

function formatReport(report) {
  const lines = [`usable free runs (>= ${MIN_CONTIGUOUS_FREE} blocks): ${report.usableRuns.length}`];
  lines.push(`move batches of ${MOVE_BATCH_SIZE}: ${report.moveBatches.length}`);
  lines.push(`heavily fragmented files: ${report.heavilyFragmented.join(', ') || 'none'}`);
  for (const bad of report.corrupted) {
    lines.push(`corrupt block in ${bad.file} at sector offset ${bad.offset}`);
  }
  if (report.truncated) lines.push(`tracking limited to ${MAX_TRACKED_FILES} files`);
  return lines.join('\n');
}

if (require.main === module) {
  const path = process.argv[2];
  if (!path) {
    console.error('usage: node defrag.js <partition.json>');
    process.exit(1);
  }
  const partition = JSON.parse(require('fs').readFileSync(path, 'utf8'));
  console.log(formatReport(analyzePartition(partition)));
}

module.exports = { analyzePartition, formatReport, fileSizeKb, localSectorOffset, freeRuns };

