const MAX_DAILY_MESSAGES = 65535;
const FLOOD_HISTORY_CHARS = 4096;
const MAX_DICTIONARY_WORDS = 1024;
const MAX_EMOTES_PER_MESSAGE = 16;
const MAX_MESSAGE_LENGTH = 255;
const MAX_CODE_POINT = 256;
const SHOUT_THRESHOLD_PERCENT = 64;
const MAX_BROADCAST_MEMBERS = 128;
const DEFAULT_MUTE_MINUTES = 32;

function loadProfanityDictionary(words) {
  const dict = new Set();
  for (const raw of words) {
    const word = String(raw).trim().toLowerCase();
    if (word.length === 0) continue;
    dict.add(word);
    if (dict.size === MAX_DICTIONARY_WORDS) break;
  }
  return dict;
}

function validateEncoding(message) {
  for (let i = 0; i < message.length; i++) {
    if (message.codePointAt(i) >= MAX_CODE_POINT) {
      return { ok: false, offset: i };
    }
  }
  return { ok: true, offset: -1 };
}

function countEmotes(message) {
  const matches = message.match(/:[a-z_]+:/g);
  return matches === null ? 0 : matches.length;
}

function isShouting(message) {
  const letters = message.replace(/[^A-Za-z]/g, '');
  if (letters.length === 0) return false;
  const upper = letters.replace(/[^A-Z]/g, '').length;
  return (upper * 100) / letters.length > SHOUT_THRESHOLD_PERCENT;
}

function censor(message, dictionary) {
  return message.replace(/[A-Za-z']+/g, (token) =>
    dictionary.has(token.toLowerCase()) ? '*'.repeat(token.length) : token
  );
}

function createModerator(dictionary) {
  const state = new Map();

  function userState(userId) {
    if (!state.has(userId)) {
      state.set(userId, { sent: 0, history: '', mutedUntil: 0 });
    }
    return state.get(userId);
  }

  function mute(userId, now, minutes) {
    const user = userState(userId);
    const span = minutes === undefined ? DEFAULT_MUTE_MINUTES : minutes;
    user.mutedUntil = now + span * 60000;
    return user.mutedUntil;
  }

  function submit(userId, message, now) {
    const user = userState(userId);
    if (now < user.mutedUntil) {
      return { accepted: false, reason: 'muted', until: user.mutedUntil };
    }
    if (message.length > MAX_MESSAGE_LENGTH) {
      return { accepted: false, reason: 'too-long' };
    }
    const encoding = validateEncoding(message);
    if (!encoding.ok) {
      return { accepted: false, reason: 'bad-encoding', offset: encoding.offset };
    }
    if (countEmotes(message) > MAX_EMOTES_PER_MESSAGE) {
      return { accepted: false, reason: 'emote-spam' };
    }
    if (user.sent >= MAX_DAILY_MESSAGES) {
      return { accepted: false, reason: 'daily-quota' };
    }
    const repeats = user.history.split(message).length - 1;
    if (message.length > 8 && repeats >= 3) {
      return { accepted: false, reason: 'flood', until: mute(userId, now) };
    }
    user.sent++;
    user.history = (user.history + message).slice(-FLOOD_HISTORY_CHARS);
    return { accepted: true, text: censor(message, dictionary), shout: isShouting(message) };
  }

  function broadcast(userId, message, recipients, now) {
    const result = submit(userId, message, now);
    if (!result.accepted) return result;
    const delivered = recipients.slice(0, MAX_BROADCAST_MEMBERS);
    return { ...result, delivered, dropped: recipients.length - delivered.length };
  }

  return { submit, broadcast, mute };
}

function runTranscript(moderator, group, transcript) {
  const lines = [];
  for (const entry of transcript) {
    const result = entry.group
      ? moderator.broadcast(entry.user, entry.message, group, entry.at)
      : moderator.submit(entry.user, entry.message, entry.at);
    if (result.accepted) {
      const tag = result.shout ? 'SHOUT' : 'chat';
      const drop = result.dropped === undefined ? '' : ` (dropped ${result.dropped})`;
      lines.push(`${entry.user} [${tag}] ${result.text}${drop}`);
    } else {
      lines.push(`${entry.user} blocked: ${result.reason}`);
    }
  }
  return lines;
}

const dictionary = loadProfanityDictionary(['noob', 'scum', 'trash']);
const moderator = createModerator(dictionary);
const group = [];
for (let i = 0; i < 150; i++) group.push(`player${i}`);
const t0 = Date.parse('2026-09-18T12:00:00Z');

const transcript = [
  { user: 'alice', message: 'hello guild :wave:', at: t0 },
  { user: 'bob', message: 'YOU ARE ALL TRASH', at: t0 },
  { user: 'carol', message: 'caf\u00e9 time', at: t0 },
  { user: 'dave', message: 'x'.repeat(300), at: t0 },
  { user: 'eve', message: 'spam spam spam', at: t0 },
