function TlsRecordParser() {
  return {
    maxRecordLength: 65535,
    blockSize: 16,
    macSize: 32,
    paddingMask: 255,
    maxHandshakePayload: 4096,
    maxFragmentSize: 1024,
    preMasterSecretSize: 128,
    minPrimeGroupBits: 256,
    sessionCacheSize: 64
  };
}

function readUint16(bytes, offset) {
  return bytes[offset] * 256 + bytes[offset + 1];
}

function encodeHandshake(msgType, body, limits) {
  if (body.length > limits.maxHandshakePayload) {
    throw new Error("handshake body exceeds " + limits.maxHandshakePayload + " bytes");
  }
  const high = Math.floor(body.length / 65536);
  const mid = Math.floor(body.length / 256);
  const low = body.length & 255;
  return [msgType, high, mid, low].concat(body);
}

function protect(data, limits) {
  const mac = [];
  for (let i = 0; i < limits.macSize; i += 1) {
    mac.push((data[i % data.length] + i) & 255);
  }
  const body = data.concat(mac);
  const padLength = limits.blockSize - 1 - (body.length % limits.blockSize);
  const padded = body.slice();
  for (let i = 0; i <= padLength; i += 1) padded.push(padLength);
  return padded;
}

function unprotect(payload, limits) {
  if (payload.length % limits.blockSize !== 0) throw new Error("payload not block aligned");
  const padLength = payload[payload.length - 1] & limits.paddingMask;
  if (padLength >= limits.blockSize) throw new Error("padding byte out of range");
  const macEnd = payload.length - padLength - 1;
  const macStart = macEnd - limits.macSize;
  if (macStart < 0) throw new Error("payload too short for MAC");
  return { data: payload.slice(0, macStart), mac: payload.slice(macStart, macEnd) };
}

function encodeRecord(type, version, payload, limits) {
  if (payload.length > limits.maxRecordLength) throw new Error("record too long");
  const hi = Math.floor(payload.length / 256);
  const lo = payload.length & 255;
  return [type, version.major, version.minor, hi, lo].concat(payload);
}

function parseRecord(record, limits) {
  if (record.length < 5) throw new Error("truncated record header");
  const length = readUint16(record, 3);
  if (length > limits.maxRecordLength) throw new Error("declared length " + length + " too large");
  if (record.length - 5 !== length) throw new Error("declared length does not match buffer");
  return {
    type: record[0],
    version: { major: record[1], minor: record[2] },
    length,
    payload: record.slice(5)
  };
}

function fragmentPayload(payload, limits) {
  const chunks = [];
  for (let offset = 0; offset < payload.length; offset += limits.maxFragmentSize) {
    chunks.push(payload.slice(offset, offset + limits.maxFragmentSize));
  }
  return chunks;
}

function validateKeyExchange(primeBits, preMaster, limits) {
  if (primeBits < limits.minPrimeGroupBits) throw new Error("prime group only " + primeBits + " bits");
  if (preMaster.length !== limits.preMasterSecretSize) throw new Error("bad pre-master length");
  return { primeBits, secretBytes: preMaster.length };
}

function createSessionCache(limits) {
  const order = [];
  const store = new Map();
  return {
    put(id, session) {
      if (store.has(id)) order.splice(order.indexOf(id), 1);
      store.set(id, session);
      order.push(id);
      while (order.length > limits.sessionCacheSize) store.delete(order.shift());
      return store.size;
    },
    get(id) {
      return store.get(id);
    }
  };
}

function hexBytes(bytes, count) {
  return bytes.slice(0, count).map((b) => b.toString(16).padStart(2, "0")).join(" ");
}

function main() {
  const limits = TlsRecordParser();
  const random = [];
  for (let i = 0; i < 32; i += 1) {
    random.push((i * 7 + 13) & 255);
  }
  const hello = encodeHandshake(1, [3, 3].concat(random), limits);
  const record = encodeRecord(22, { major: 3, minor: 3 }, protect(hello, limits), limits);
  const parsed = parseRecord(record, limits);
  const opened = unprotect(parsed.payload, limits);
  console.log("record type", parsed.type, "length", parsed.length);
  console.log("header+body:", hexBytes(record, 16));
  console.log("mac:", hexBytes(opened.mac, limits.macSize));
  console.log("fragments:", fragmentPayload(parsed.payload, limits).length);

  const preMaster = [];
  for (let i = 0; i < limits.preMasterSecretSize; i += 1) {
    preMaster.push((i * 31 + 5) & 255);
  }
  console.log("key exchange:", validateKeyExchange(2048, preMaster, limits));

  const cache = createSessionCache(limits);
  let held = 0;
  for (let i = 0; i < 70; i += 1) {
    held = cache.put("sid-" + i, { resumed: false, mac: opened.mac });
  }
  console.log("sessions retained", held, "oldest kept:", cache.get("sid-5") !== undefined);
}

main();

