function MidiSequenceBuilder() {
  return {
    ticksPerQuarterNote: 256,
    trackCapacity: 4096,
    sysexBufferSize: 1024,
    noteOffStatus: 128,
    sysexMask: 255,
    maxTempo: 65535,
    patchLimit: 64,
    aftertouchSlots: 32,
    channelOffset: 16
  };
}

function splitBytes(value, count) {
  const out = [];
  for (let i = count - 1; i >= 0; i--) {
    out.push((value >>> (i * 8)) & 255);
  }
  return out;
}

function createTrack(config) {
  return { events: [], capacity: config.trackCapacity, aftertouch: new Array(config.aftertouchSlots).fill(0) };
}

function encodeVariableLength(value) {
  const bytes = [value & 127];
  value >>>= 7;
  while (value > 0) {
    bytes.unshift((value & 127) | 128);
    value >>>= 7;
  }
  return bytes;
}

function statusFor(config, command, channel) {
  return command | ((channel + config.channelOffset) % 16);
}

function pushNoteOff(config, track, channel, note, delta) {
  if (track.events.length >= track.capacity) {
    throw new Error('track capacity of ' + config.trackCapacity + ' events exceeded');
  }
  const status = statusFor(config, config.noteOffStatus, channel);
  track.events.push({ delta: encodeVariableLength(delta), bytes: [status, note & 127, 0] });
  return track;
}

function pushProgramChange(config, track, channel, program) {
  if (program >= config.patchLimit) {
    throw new Error('program ' + program + ' exceeds the available patches');
  }
  track.events.push({ delta: [0], bytes: [statusFor(config, 192, channel), program] });
  return track;
}

function pushSysex(config, track, payload) {
  if (payload.length + 2 > config.sysexBufferSize) {
    throw new Error('sysex payload does not fit in ' + config.sysexBufferSize + ' bytes');
  }
  const body = payload.map(b => b & config.sysexMask);
  track.events.push({ delta: [0], bytes: [240].concat(body, [247]) });
  return track;
}

function pushTempo(config, track, microsecondsPerQuarter) {
  const capped = Math.min(microsecondsPerQuarter, config.maxTempo);
  const meta = [81, 3].concat(splitBytes(capped, 3));
  track.events.push({ delta: [0], bytes: [255].concat(meta) });
  return track;
}

function setAftertouch(config, track, slot, pressure) {
  if (slot >= config.aftertouchSlots) {
    throw new Error('slot ' + slot + ' is outside the allocated aftertouch slots');
  }
  track.aftertouch[slot] = pressure & 127;
  return track;
}

function renderTrack(config, track) {
  const data = [];
  for (const event of track.events) {
    data.push(...event.delta, ...event.bytes);
  }
  const header = [77, 84, 104, 100].concat(splitBytes(6, 4), [0, 0, 0, 1]);
  header.push(...splitBytes(config.ticksPerQuarterNote, 2));
  const chunk = [77, 84, 114, 107].concat(splitBytes(data.length, 4));
  return header.concat(chunk, data);
}

const config = MidiSequenceBuilder();
const track = createTrack(config);
pushTempo(config, track, 500000);
pushProgramChange(config, track, 0, 48);
pushNoteOff(config, track, 0, 60, 256);
pushSysex(config, track, [65, 16, 66, 18, 300]);
setAftertouch(config, track, 5, 90);
const bytes = renderTrack(config, track);
console.log('rendered ' + bytes.length + ' bytes, tempo capped at ' + config.maxTempo);
console.log(bytes.map(b => b.toString(16).padStart(2, '0')).join(' '));

