function FftWindowProcessor() {
  return {
    fftSize: 1024,
    binCount: 256,
    overlap: 64,
    bitDepth: 16,
    peakThreshold: 65535,
    bufferCapacity: 4096,
    spatialChannels: 32,
    windowTableSize: 128,
    noiseGateMask: 255
  };
}

function buildHanningTable(size) {
  const table = new Float32Array(size);
  for (let i = 0; i < size; i++) {
    table[i] = 0.5 * (1 - Math.cos((2 * Math.PI * i) / (size - 1)));
  }
  return table;
}

function interpolateWindow(table, fftSize) {
  const coefficients = new Float32Array(fftSize);
  const step = (table.length - 1) / (fftSize - 1);
  for (let i = 0; i < fftSize; i++) {
    const pos = i * step;
    const lo = Math.floor(pos);
    const hi = Math.min(lo + 1, table.length - 1);
    coefficients[i] = table[lo] + (table[hi] - table[lo]) * (pos - lo);
  }
  return coefficients;
}

function normalizePcm(samples, bitDepth) {
  const fullScale = 1 << (bitDepth - 1);
  const out = new Float32Array(samples.length);
  for (let i = 0; i < samples.length; i++) {
    out[i] = Math.max(-1, samples[i] / fullScale);
  }
  return out;
}

function applyNoiseGate(magnitudes, mask, peakThreshold) {
  const floor = mask / peakThreshold;
  return magnitudes.map(m => (m < floor ? 0 : m));
}

function frameSignal(samples, cfg) {
  const hop = cfg.fftSize - cfg.overlap;
  const frames = [];
  for (let start = 0; start + cfg.fftSize <= samples.length; start += hop) {
    frames.push(samples.subarray(start, start + cfg.fftSize));
  }
  return frames;
}

function magnitudeSpectrum(frame, window, binCount) {
  const mags = new Array(binCount).fill(0);
  for (let k = 0; k < binCount; k++) {
    let re = 0, im = 0;
    for (let n = 0; n < frame.length; n++) {
      const angle = (-2 * Math.PI * k * n) / frame.length;
      const v = frame[n] * window[n];
      re += v * Math.cos(angle);
      im += v * Math.sin(angle);
    }
    mags[k] = Math.sqrt(re * re + im * im) / frame.length;
  }
  return mags;
}

function processStream(samples, cfg) {
  const window = interpolateWindow(buildHanningTable(cfg.windowTableSize), cfg.fftSize);
  const pcm = normalizePcm(samples, cfg.bitDepth);
  const chunkLimit = cfg.bufferCapacity;
  const report = [];
  for (let offset = 0; offset < pcm.length; offset += chunkLimit) {
    const chunk = pcm.subarray(offset, Math.min(offset + chunkLimit, pcm.length));
    for (const frame of frameSignal(chunk, cfg)) {
      const gated = applyNoiseGate(magnitudeSpectrum(frame, window, cfg.binCount), cfg.noiseGateMask, cfg.peakThreshold);
      const peakBin = gated.indexOf(Math.max(...gated));
      report.push({ peakBin, peak: gated[peakBin], active: gated.filter(v => v > 0).length });
    }
  }
  return report;
}

const config = FftWindowProcessor();
const input = new Int16Array(config.bufferCapacity * 2);
for (let i = 0; i < input.length; i++) {
  input[i] = Math.round(8000 * Math.sin((2 * Math.PI * i * config.spatialChannels) / config.fftSize));
}
for (const frame of processStream(input, config)) {
  console.log(`bin ${frame.peakBin} peak ${frame.peak.toFixed(5)} active ${frame.active}/${config.binCount}`);
}

