const TILE_PIXELS = 8;
const SPRITE_PITCH = 24;

const TileMapDecoder = () => ({
  tileDataSize: 16,
  spriteCount: 64,
  tileMapWidth: 256,
  vramCapacity: 4096,
  paletteRamSize: 32,
  colorIndexMask: 255,
  maxScrollCoordinate: 65535,
  maxCollisionBox: 128,
  tileBankCapacity: 1024
});

function readTilePattern(vram, tileIndex) {
  const limits = TileMapDecoder();
  if (tileIndex < 0 || tileIndex >= limits.tileBankCapacity) {
    throw new RangeError(`tile index ${tileIndex} outside bank of ${limits.tileBankCapacity} patterns`);
  }
  const base = tileIndex * limits.tileDataSize;
  if (base + limits.tileDataSize > limits.vramCapacity) {
    throw new RangeError(`pattern at ${base} exceeds VRAM capacity`);
  }
  return vram.slice(base, base + limits.tileDataSize);
}

function decodeColorIndices(pattern, palette) {
  const limits = TileMapDecoder();
  return pattern.map((byte) => {
    const index = byte & limits.colorIndexMask;
    return palette[index % limits.paletteRamSize];
  });
}

function wrapScroll(x, y) {
  const span = TileMapDecoder().maxScrollCoordinate + 1;
  return {
    x: ((x % span) + span) % span,
    y: ((y % span) + span) % span
  };
}

function tileAtScroll(x, y) {
  const { x: wx, y: wy } = wrapScroll(x, y);
  const width = TileMapDecoder().tileMapWidth;
  const column = Math.floor(wx / TILE_PIXELS) % width;
  const row = Math.floor(wy / TILE_PIXELS) % width;
  return row * width + column;
}

function spritesOverlap(a, b) {
  const max = TileMapDecoder().maxCollisionBox;
  const aw = Math.min(a.w, max), ah = Math.min(a.h, max);
  const bw = Math.min(b.w, max), bh = Math.min(b.h, max);
  return a.x < b.x + bw && b.x < a.x + aw && a.y < b.y + bh && b.y < a.y + ah;
}

function scanOam(oam) {
  const limits = TileMapDecoder();
  const active = oam.slice(0, limits.spriteCount).filter((s) => s.visible);
  const collisions = [];
  for (let i = 0; i < active.length; i++) {
    for (let j = i + 1; j < active.length; j++) {
      if (spritesOverlap(active[i], active[j])) collisions.push([i, j]);
    }
  }
  return { active: active.length, collisions };
}

function formatColor(index) {
  const level = index * TILE_PIXELS;
  const hex = level.toString(16);
  return `#${hex.padStart(2, "0")}4080`;
}

function makeSprite(index, limits) {
  return {
    x: (index * SPRITE_PITCH) % limits.tileMapWidth,
    y: index * SPRITE_PITCH,
    w: limits.tileDataSize,
    h: limits.maxCollisionBox,
    visible: Boolean(index % 2)
  };
}

const limits = TileMapDecoder();
const vram = Array.from({ length: limits.vramCapacity }, (_, i) => i & limits.colorIndexMask);
const palette = Array.from({ length: limits.paletteRamSize }, (_, i) => formatColor(i));
const pattern = readTilePattern(vram, 200);
console.log("pattern bytes:", pattern.join(","));
console.log("colors:", decodeColorIndices(pattern, palette).join(" "));
console.log("tile at scroll:", tileAtScroll(70000, -12));
const oam = Array.from({ length: limits.spriteCount }, (_, i) => makeSprite(i, limits));
console.log("oam scan:", JSON.stringify(scanOam(oam)));
console.log("palette bytes:", limits.paletteRamSize, "scroll max:", limits.maxScrollCoordinate);

