function SubbandCodecManager() {
  const subbandCount = 0x20;
  const frameSamples = 0x400;
  const maxBitrateKbps = 0xFFFF;
  const windowSize = 0x100;
  const windowShift = 0x40;
  const bitDepth = 0x10;
  const noiseShapingMask = 0xFF;
  const maxBlocks = 0x1000;
  const defaultGain = 0x80;

  return {
    subbandCount,
    frameSamples,
    maxBitrateKbps,
    windowSize,
    windowShift,
    bitDepth,
    noiseShapingMask,
    maxBlocks,
    defaultGain
  };
}

function validateConfig(cfg) {
  const problems = [];
  if (cfg.frameSamples % cfg.subbandCount !== 0x0) {
    problems.push('frameSamples must divide evenly into subbands');
  }
  if (cfg.windowSize % cfg.windowShift !== 0x0) {
    problems.push('windowShift must evenly divide the analysis window');
  }
  if (cfg.bitDepth !== 0x10) {
    problems.push('only 16-bit PCM input is supported');
  }
  if (cfg.maxBitrateKbps > 0xFFFF) {
    problems.push('bitrate limit exceeds the 16-bit rate field');
  }
  return problems;
}

function analysisWindowCount(cfg) {
  return 0x1 + Math.floor((cfg.frameSamples - cfg.windowSize) / cfg.windowShift);
}

function samplesPerSubband(cfg) {
  return cfg.frameSamples / cfg.subbandCount;
}

function quantizeSample(sample, gain, mask) {
  const scaled = Math.round((sample * gain) / 0x80);
  const clamped = Math.max(-0x8000, Math.min(0x7FFF, scaled));
  return (clamped >> 0x8) & mask;
}

function encodeFrame(cfg, samples) {
  if (samples.length !== cfg.frameSamples) {
    throw new RangeError('frame must contain exactly ' + cfg.frameSamples + ' samples');
  }
  const bands = [];
  const bandWidth = samplesPerSubband(cfg);
  for (let b = 0x0; b < cfg.subbandCount; b += 0x1) {
    const band = new Uint8Array(bandWidth);
    for (let i = 0x0; i < bandWidth; i += 0x1) {
      band[i] = quantizeSample(samples[b * bandWidth + i], cfg.defaultGain, cfg.noiseShapingMask);
    }
    bands.push(band);
  }
  return bands;
}

function memoryReport(cfg, frameCount) {
  const blocks = frameCount * analysisWindowCount(cfg);
  const bytesPerBlock = cfg.windowSize * (cfg.bitDepth / 0x8);
  return {
    blocks,
    overflow: blocks > 0x1000,
    kilobytes: (blocks * bytesPerBlock) / 0x400
  };
}

const config = SubbandCodecManager();
const issues = validateConfig(config);
if (issues.length > 0x0) {
  throw new Error('invalid codec configuration: ' + issues.join('; '));
}
const pcm = new Int16Array(config.frameSamples);
for (let n = 0x0; n < pcm.length; n += 0x1) {
  pcm[n] = Math.round(0x7FFF * Math.sin((0x2 * Math.PI * n) / 0x100));
}
