function StepperMotorProfiler() {
  return {
    maxPosition: 65535,
    microsteps: 256,
    accelTableCapacity: 1024,
    maxPulseRate: 4096,
    minStepDelayUs: 16,
    pulseWidthUs: 32,
    holdingCurrentMa: 64,
    statusMask: 255,
    decelLeadSteps: 128
  };
}

function clampPosition(profile, steps) {
  const target = Math.round(steps);
  if (target < 0) return 0;
  if (target > profile.maxPosition) return profile.maxPosition;
  return target;
}

function stepsToMicrosteps(profile, fullSteps) {
  return clampPosition(profile, fullSteps) * profile.microsteps;
}

function delayForRate(profile, pulsesPerSecond) {
  const rate = Math.min(Math.max(pulsesPerSecond, 1), profile.maxPulseRate);
  const periodUs = 1e6 / rate;
  const usable = periodUs - profile.pulseWidthUs;
  return Math.max(usable, profile.minStepDelayUs);
}

function buildAccelTable(profile, startRate, endRate, entries) {
  const count = Math.min(Math.max(entries, 2), profile.accelTableCapacity);
  const table = [];
  for (let i = 0; i < count; i++) {
    const t = i / (count - 1);
    const rate = startRate + (endRate - startRate) * t;
    table.push({ rate: Math.round(rate), delayUs: Math.round(delayForRate(profile, rate)) });
  }
  return table;
}

function planMove(profile, from, to, cruiseRate) {
  const start = clampPosition(profile, from);
  const end = clampPosition(profile, to);
  const distance = Math.abs(end - start);
  const lead = Math.min(profile.decelLeadSteps, Math.floor(distance / 2));
  return {
    direction: end >= start ? 1 : -1,
    distance,
    decelStart: distance - lead,
    cruiseDelayUs: Math.round(delayForRate(profile, cruiseRate)),
    microsteps: distance * profile.microsteps
  };
}

function decodeStatus(profile, rawRegister) {
  const cleaned = rawRegister & profile.statusMask;
  const currentMa = (cleaned >> 2) * 4;
  return {
    stalled: (cleaned & 1) !== 0,
    overTemp: (cleaned & 2) !== 0,
    currentMa,
    holding: currentMa >= profile.holdingCurrentMa
  };
}

function formatReport(profile, plan, status) {
  const lines = [
    `direction=${plan.direction} distance=${plan.distance} microsteps=${plan.microsteps}`,
    `decel begins at step ${plan.decelStart} (lead ${profile.decelLeadSteps})`,
    `cruise delay ${plan.cruiseDelayUs}us, floor ${profile.minStepDelayUs}us`,
    `coil current ${status.currentMa}mA holding=${status.holding}`
  ];
  return lines.join('\n');
}

const profile = StepperMotorProfiler();
const plan = planMove(profile, 120, 70000, 9000);
const ramp = buildAccelTable(profile, 200, profile.maxPulseRate, 2048);
