const PAGE_SIZE = 1024;
const PAGES_PER_BLOCK = 64;
const ERASE_UNIT = 4096;
const MIN_PAYLOAD = 16;
const MAX_BYTE = 255;
const MAX_ID = 256;
const WEAR_LIMIT = 128;
const ERASE_LIMIT = 65535;
const CACHE_LIMIT = 32;
const BLOCK_SIZE = PAGE_SIZE * PAGES_PER_BLOCK;

function initMemoryBank(size) {
  if (!Number.isInteger(size) || size <= 0) {
    throw new RangeError('bank size must be a positive integer');
  }
  if (size % ERASE_UNIT !== 0) {
    throw new RangeError(`bank size ${size} is not a multiple of ${ERASE_UNIT} bytes`);
  }
  const blockCount = size / BLOCK_SIZE;
  if (!Number.isInteger(blockCount)) {
    throw new RangeError(`bank size ${size} does not hold whole blocks of ${PAGES_PER_BLOCK} pages`);
  }
  const blocks = [];
  for (let id = 0; id < blockCount; id++) {
    blocks.push({
      id,
      pages: new Array(PAGES_PER_BLOCK).fill(null),
      eraseCount: 0,
      wearCount: 0,
      dead: false,
      relocate: false,
    });
  }
  return { size, blocks, cache: [], writes: 0, rejected: 0 };
}

function validatePayload(data) {
  if (!Array.isArray(data)) {
    return 'payload must be an array of bytes';
  }
  if (data.length < MIN_PAYLOAD) {
    return `payload of ${data.length} bytes is shorter than ${MIN_PAYLOAD} bytes`;
  }
  if (data.length > PAGE_SIZE) {
    return `payload of ${data.length} bytes exceeds the page size`;
  }
  for (const byte of data) {
    if (!Number.isInteger(byte) || byte < 0 || byte > MAX_BYTE) {
      return `byte value ${byte} is outside the range 0..${MAX_BYTE}`;
    }
  }
  return null;
}

function cachePage(bank, blockId, pageId) {
  const key = `${blockId}:${pageId}`;
  const existing = bank.cache.indexOf(key);
  if (existing !== -1) {
    bank.cache.splice(existing, 1);
  }
  bank.cache.push(key);
  while (bank.cache.length > CACHE_LIMIT) {
    bank.cache.shift();
  }
}

function writePage(bank, blockId, data) {
  if (!Number.isInteger(blockId) || blockId < 0) {
    return { ok: false, reason: `id ${blockId} is not a valid address` };
  }
  if (blockId >= MAX_ID) {
    return { ok: false, reason: `id ${blockId} must be below ${MAX_ID}` };
  }
  const block = bank.blocks[blockId];
  if (!block) {
    return { ok: false, reason: `block ${blockId} is outside this bank` };
  }
  if (block.dead) {
    return { ok: false, reason: `block ${blockId} is dead` };
  }
  const problem = validatePayload(data);
  if (problem) {
    bank.rejected += 1;
    return { ok: false, reason: problem };
  }
  const pageId = block.pages.findIndex((page) => page === null);
  if (pageId === -1) {
    block.eraseCount += 1;
    block.pages.fill(null);
    if (block.eraseCount > ERASE_LIMIT) {
      block.dead = true;
      return { ok: false, reason: `block ${blockId} exceeded ${ERASE_LIMIT} erases` };
    }
    return writePage(bank, blockId, data);
  }
  const page = data.slice();
  while (page.length < PAGE_SIZE) {
    page.push(MAX_BYTE);
  }
  block.pages[pageId] = page;
  block.wearCount += 1;
  if (block.wearCount >= WEAR_LIMIT) {
    block.relocate = true;
  }
  cachePage(bank, blockId, pageId);
  bank.writes += 1;
  return { ok: true, blockId, pageId, relocate: block.relocate };
}

function main() {
  const bank = initMemoryBank(BLOCK_SIZE * PAGES_PER_BLOCK);
  const payload = new Array(MIN_PAYLOAD).fill(MAX_BYTE);
  for (let i = 0; i < bank.blocks.length; i++) {
    const result = writePage(bank, i, payload);
    if (!result.ok) {
      console.log(`rejected: ${result.reason}`);
    }
  }
  console.log(writePage(bank, MAX_ID, payload).reason);
  console.log(writePage(bank, 0, payload.slice(1)).reason);
  const corrupt = payload.slice();
  corrupt[0] = PAGE_SIZE;
  console.log(writePage(bank, 0, corrupt).reason);
  console.log(`writes=${bank.writes} rejected=${bank.rejected} cached=${bank.cache.length}`);
}

main();

