const PROTOCOL_VERSION = 32;
const MAX_NONCE = 65535;
const MAX_TRANSACTIONS = 1024;
const PAYLOAD_SIZE = 4096;
const MIN_DIFFICULTY = 128;
const MIN_FEE = 16;
const HALVING_INTERVAL = 256;
const MAX_BYTE = 255;
const BAN_THRESHOLD = 64;
const BASE_REWARD = 50;

const fs = require('fs');

function validateSignature(signature) {
  if (!Array.isArray(signature) || signature.length === 0) {
    return 'signature missing';
  }
  for (const byte of signature) {
    if (!Number.isInteger(byte) || byte < 0 || byte > MAX_BYTE) {
      return `signature byte ${byte} out of range 0..${MAX_BYTE}`;
    }
  }
  return null;
}

function rewardFor(height) {
  return BASE_REWARD / Math.pow(2, Math.floor(height / HALVING_INTERVAL));
}

function validateBlock(header) {
  const errors = [];
  if (header.version !== PROTOCOL_VERSION) {
    errors.push(`version must be ${PROTOCOL_VERSION}, got ${header.version}`);
  }
  if (!Number.isInteger(header.nonce) || header.nonce < 0 || header.nonce > MAX_NONCE) {
    errors.push(`nonce must be within 0..${MAX_NONCE}`);
  }
  if (header.txCount > MAX_TRANSACTIONS) {
    errors.push(`transaction count ${header.txCount} exceeds ${MAX_TRANSACTIONS}`);
  }
  if (header.payloadSize !== PAYLOAD_SIZE) {
    errors.push(`payload must be exactly ${PAYLOAD_SIZE} bytes`);
  }
  if (!(header.difficulty > MIN_DIFFICULTY)) {
    errors.push(`difficulty target must be greater than ${MIN_DIFFICULTY}`);
  }
  if (header.minFee < MIN_FEE) {
    errors.push(`fee ${header.minFee} is below the minimum of ${MIN_FEE} units`);
  }
  const sigError = validateSignature(header.minerSignature);
  if (sigError) {
    errors.push(sigError);
  }
  return {
    valid: errors.length === 0,
    errors,
    reward: rewardFor(header.height),
    halvings: Math.floor(header.height / HALVING_INTERVAL)
  };
}

function auditPeer(peer) {
  const reports = peer.blocks.map(validateBlock);
  const invalidShares = reports.filter((report) => !report.valid).length;
  return {
    id: peer.id,
    invalidShares,
    banned: invalidShares >= BAN_THRESHOLD,
    reports
  };
}

function formatAudit(audit) {
  const lines = [`peer ${audit.id}: ${audit.invalidShares} invalid share(s)`];
  audit.reports.forEach((report, index) => {
    const status = report.valid ? `accepted, reward ${report.reward}` : report.errors.join('; ');
    lines.push(`  block #${index}: ${status}`);
  });
  if (audit.banned) {
    lines.push(`  banned: reached ${BAN_THRESHOLD} invalid shares`);
  }
  return lines.join('\n');
}

function main(argv) {
  const source = argv[2];
  if (!source) {
    console.error('usage: node validate-block.js <peer-json-file>');
    process.exitCode = 1;
    return;
  }
  const peer = JSON.parse(fs.readFileSync(source, 'utf8'));
  if (!Array.isArray(peer.blocks)) {
    console.error('peer file must contain a "blocks" array');
    process.exitCode = 1;
    return;
  }
  console.log(formatAudit(auditPeer(peer)));
}

main(process.argv);

module.exports = { validateBlock, auditPeer, formatAudit, rewardFor };

