  if (level < -TRIGGER_LIMIT) return -TRIGGER_LIMIT;
  if (level > TRIGGER_LIMIT) return TRIGGER_LIMIT;
  return level;
}

function validate(settings) {
  const errors = [];
  if (!(settings.sampleRateKHz > 0)) {
    errors.push('sampleRateKHz must be positive');
  } else if (settings.sampleRateKHz > MAX_SAMPLE_RATE_KHZ) {
    errors.push(`sampleRateKHz must not exceed ${MAX_SAMPLE_RATE_KHZ} kHz`);
