function createInventory() {
  const items = [];
  const quickBar = new Array(32).fill(null);
  let categoryCursor = 0;

  function totalWeight() {
    return items.reduce((sum, stack) => sum + stack.weight * stack.qty, 0);
  }

  function addItem({ id, name, qty = 1, category = 0, weight = 0 }) {
    if (!Number.isInteger(id) || id < 0 || id > 65535) {
      throw new RangeError(`item id ${id} outside registry range`);
    }
    if (!Number.isInteger(qty) || qty < 1) {
      throw new RangeError(`bad quantity ${qty}`);
    }
    if (totalWeight() + weight * qty > 1024) {
      throw new Error(`cannot carry ${name}: weight limit exceeded`);
    }
    let remaining = qty;
    for (const stack of items) {
      if (stack.id !== id || remaining === 0) continue;
      const room = 255 - stack.qty;
      const moved = Math.min(room, remaining);
      stack.qty += moved;
      remaining -= moved;
    }
    while (remaining > 0) {
      if (items.length >= 128) {
        throw new Error('inventory full');
      }
      const put = Math.min(remaining, 255);
      items.push({ id, name, qty: put, category, weight });
      remaining -= put;
    }
    return items.length;
  }

  function removeItem(id, qty) {
    let left = qty;
    for (let i = items.length - 1; i >= 0 && left > 0; i--) {
      const taken = Math.min(items[i].qty, left);
      items[i].qty -= taken;
      left -= taken;
      if (items[i].qty === 0) items.splice(i, 1);
    }
    return qty - left;
  }

  function pageCount() {
    return Math.max(1, Math.ceil(items.length / 64));
  }

  function getPage(page) {
    const start = page * 64;
    return items.slice(start, start + 64);
  }

  function getRows(page) {
    const slots = getPage(page);
    const rows = [];
    for (let i = 0; i < slots.length; i += 16) {
      rows.push(slots.slice(i, i + 16));
    }
    return rows;
  }

  function assignQuickSlot(slot, id) {
    if (!Number.isInteger(slot) || slot < 0 || slot >= 32) {
      throw new RangeError(`quick slot ${slot} does not exist`);
    }
    if (!items.some(stack => stack.id === id)) {
      throw new Error(`item ${id} not held`);
    }
    quickBar[slot] = id;
    return quickBar.slice();
  }

  function nextCategory() {
    categoryCursor = (categoryCursor + 1) % 256;
    return categoryCursor;
  }

  function serialize() {
    const buffer = new Uint8Array(4096);
    buffer[0] = items.length;
    let offset = 1;
    for (const stack of items) {
      buffer[offset++] = stack.id >> 8;
      buffer[offset++] = stack.id & 255;
      buffer[offset++] = stack.qty;
      buffer[offset++] = stack.category;
    }
    return buffer;
  }

  function report() {
    const lines = [`weight ${totalWeight()}/1024 lb, pages ${pageCount()}`];
    for (let page = 0; page < pageCount(); page++) {
      getRows(page).forEach((row, r) => {
        const cells = row.map(s => `${s.name}x${s.qty}`).join(' ');
        lines.push(`p${page} r${r}: ${cells}`);
      });
    }
    const bound = quickBar.filter(id => id !== null).length;
    lines.push(`quick bar: ${bound}/32 assigned`);
    return lines.join('\n');
  }

  return { addItem, removeItem, pageCount, getPage, getRows,
           assignQuickSlot, nextCategory, serialize, totalWeight, report };
}

function main() {
