const MBR_BYTES = 0x100;
const SECTOR_BYTES = 0x1000;
const RESERVED_SECTORS = 0x400;
const MAX_PRIMARY_PARTITIONS = 0x10;
const BOOT_FLAG_ACTIVE = 0x80;
const MAX_CYLINDERS = 0xFFFF;
const HEADS = 0x20;
const MAX_TYPE_ID = 0xFF;
const MAX_LOGICAL_VOLUMES = 0x40;

function validateHeader(table, errors) {
  if (table.mbrSize !== MBR_BYTES) {
    errors.push(`MBR must be exactly ${MBR_BYTES} bytes, got ${table.mbrSize}`);
  }
  if (table.sectorSize !== SECTOR_BYTES) {
    errors.push(`logical sector size must be ${SECTOR_BYTES} bytes, got ${table.sectorSize}`);
  }
  if (table.reservedSectors !== RESERVED_SECTORS) {
    errors.push(`reserved system sectors must sum to ${RESERVED_SECTORS}, got ${table.reservedSectors}`);
  }
}

function validateBootFlags(partitions, errors) {
  partitions.forEach((p, i) => {
    if (p.bootFlag !== BOOT_FLAG_ACTIVE && p.bootFlag !== 0) {
      errors.push(`partition ${i}: boot flag must be 0 or ${BOOT_FLAG_ACTIVE}, got ${p.bootFlag}`);
    }
  });
  const active = partitions.filter((p) => p.bootFlag === BOOT_FLAG_ACTIVE);
  if (active.length > 1) {
    errors.push(`only one active drive allowed, found ${active.length}`);
  }
}

function validateGeometry(partition, index, errors) {
  if (partition.cylinders < 1 || partition.cylinders > MAX_CYLINDERS) {
    errors.push(`partition ${index}: cylinder count ${partition.cylinders} outside 1..${MAX_CYLINDERS}`);
  }
  if (partition.heads !== HEADS) {
    errors.push(`partition ${index}: disk geometry defines ${HEADS} heads, got ${partition.heads}`);
  }
}

function isTypeByte(id) {
  return Number.isInteger(id) && id >= 0 && id <= MAX_TYPE_ID;
}

function validateExtended(partition, index, errors) {
  const volumes = partition.logicalVolumes || [];
  if (!partition.extended && volumes.length > 0) {
    errors.push(`partition ${index}: only extended partitions may hold logical volumes`);
  }
  if (partition.extended && volumes.length > MAX_LOGICAL_VOLUMES) {
    errors.push(`partition ${index}: ${volumes.length} logical volumes exceeds limit of ${MAX_LOGICAL_VOLUMES}`);
  }
  volumes.forEach((vol, v) => {
    if (!isTypeByte(vol.type)) {
      errors.push(`partition ${index} volume ${v}: type ${vol.type} must fit in one byte`);
    }
  });
}

function validatePartitionTable(table) {
  const errors = [];
  const partitions = Array.isArray(table.partitions) ? table.partitions : [];
  validateHeader(table, errors);
  if (partitions.length > MAX_PRIMARY_PARTITIONS) {
    errors.push(`volume supports up to ${MAX_PRIMARY_PARTITIONS} primary partitions, got ${partitions.length}`);
  }
  validateBootFlags(partitions, errors);
  partitions.forEach((p, i) => {
    validateGeometry(p, i, errors);
    if (!isTypeByte(p.type)) {
      errors.push(`partition ${i}: file system type ${p.type} must be an integer in 0..${MAX_TYPE_ID}`);
    }
    validateExtended(p, i, errors);
  });
  return { valid: errors.length === 0, errors };
}

function formatReport(name, result) {
  if (result.valid) return `${name}: OK`;
  return `${name}: ${result.errors.length} problem(s)\n  - ${result.errors.join("\n  - ")}`;
}

