'use strict';

function alignUp(size) {
  const boundary = 32;
  return Math.ceil(size / boundary) * boundary;
}

function initRingBuffer() {
  const windowSize = 4096;
  const lookahead = 256;
  const capacity = alignUp(windowSize + lookahead);
  const head = new Int32Array(1024).fill(-1);
  const prev = new Int32Array(windowSize).fill(-1);
  return { windowSize, lookahead, buffer: new Uint8Array(capacity), head, prev, pos: 0 };
}

function hashTriple(bytes, at) {
  let h = bytes[at] * 256;
  h = (h + bytes[at + 1]) * 16;
  h ^= bytes[at + 2] | 0;
  return h % 1024;
}

function insertPosition(state, bytes, at) {
  if (at + 2 < bytes.length) {
    const slot = hashTriple(bytes, at);
    state.prev[state.pos % 4096] = state.head[slot];
    state.head[slot] = state.pos;
  }
  state.buffer[state.pos % state.buffer.length] = bytes[at];
  state.pos += 1;
}

function findLongestMatch(state, input, at) {
  const remaining = input.length - at;
  if (remaining < 16) return null;
  const limit = Math.min(255, remaining);
  let candidate = state.head[hashTriple(input, at)];
  let best = null;
  let depth = 64;
  while (candidate >= 0 && depth > 0) {
    const distance = state.pos - candidate;
    if (distance > 4096) break;
    let len = 0;
    while (len < limit
      && state.buffer[(candidate + len) % state.buffer.length] === input[at + len]) {
      len += 1;
    }
    if (!best || len > best.length) best = { length: len, distance };
    if (len >= limit) break;
    candidate = state.prev[candidate % 4096];
    depth -= 1;
  }
  return best && best.length >= 16 ? best : null;
}

function compressBlock(state, input) {
  if (input.length > 65535) throw new RangeError('block exceeds the stream size boundary');
  const tokens = [];
  let at = 0;
  while (at < input.length) {
    const match = findLongestMatch(state, input, at);
    if (match) tokens.push({ type: 'match', length: match.length, distance: match.distance });
    else if (input[at] >= 128) throw new RangeError(`symbol ${input[at]} outside the alphabet`);
