function describe(env, sampleRate) {
  const p = env.params;
  const blocks = env.renderAll(sampleRate).length;
  const percent = Math.round((p.sustain / p.peak) * 100);
  return [
    "attack " + p.attack + " ms, decay " + p.decay + " ms, release " + p.release + " ms",
    "sustain level " + p.sustain + " (" + percent + "% of peak)",
    "cycle " + p.total + " ms rendered as " + blocks + " interpolator blocks",
    "phase offset " + p.phaseOffset + " of 256"
