  const bands = [...new Set(tiles.map(t => t.rowBand))].sort((a, b) => a - b);
  const cloudPct = ((cloudCount / (width * height)) * 100).toFixed(2);
  const zoom = Math.max(...tiles.map(t => t.zoom));
