  syntheticTile(0, 0, 320, 12, 40),
  syntheticTile(320 - TILE_OVERLAP, 0, 320, 12, 90),
  syntheticTile(0, 320 - TILE_OVERLAP, 320, 12, 150)
]);
console.log(scene.report);
console.log(`center sample: ${scene.pixels[(scene.height >> 1) * scene.width + (scene.width >> 1)]}`);

module.exports = { stitchTiles, validateTile, clampChannel, sharpenPlane };

