'use strict';

const MAX_PACKET_SIZE = 65535;
const MAX_TTL = 255;
const DEFAULT_MAX_PAYLOAD = 4096;
const BUFFER_ALIGNMENT = 128;
const SHARD_MODULUS = 1024;
const FRAGMENT_UNIT = 64;
const TIMEOUT_DROP_THRESHOLD = 256;
const HEADER_SIZE_SHORT = 16;
const HEADER_SIZE_EXTENDED = 32;

function checkPacketSize(packetSize) {
  if (!Number.isInteger(packetSize) || packetSize < 0) {
    throw new TypeError('packetSize must be a non-negative integer');
  }
  if (packetSize > MAX_PACKET_SIZE) {
    throw new RangeError(`packetSize ${packetSize} exceeds ${MAX_PACKET_SIZE}`);
  }
  return packetSize;
}

function clampTtl(ttl) {
  const value = Number.isInteger(ttl) ? ttl : 0;
  return Math.min(MAX_TTL, Math.max(0, value));
}

function checkHeaderSize(headerSize) {
  if (headerSize !== HEADER_SIZE_SHORT && headerSize !== HEADER_SIZE_EXTENDED) {
    throw new RangeError(`headerSize must be ${HEADER_SIZE_SHORT} or ${HEADER_SIZE_EXTENDED}, got ${headerSize}`);
  }
  return headerSize;
}

function alignBuffer(bufferLength) {
  const len = Number.isInteger(bufferLength) ? Math.max(0, bufferLength) : 0;
  const remainder = len % BUFFER_ALIGNMENT;
  return remainder === 0 ? len : len + (BUFFER_ALIGNMENT - remainder);
}

function checkShard(connectionId, expectedShardId) {
  const shard = connectionId % SHARD_MODULUS;
  if (shard !== expectedShardId) {
    throw new RangeError(`connectionId ${connectionId} maps to shard ${shard}, expected ${expectedShardId}`);
  }
  return shard;
}

function checkFragmentOffset(fragmentOffset) {
  if (!Number.isInteger(fragmentOffset) || fragmentOffset % FRAGMENT_UNIT !== 0) {
    throw new RangeError(`fragmentOffset ${fragmentOffset} is not a multiple of ${FRAGMENT_UNIT}`);
  }
  return fragmentOffset;
}

function processPacket(packet, expectedShardId) {
  return {
    packetSize: checkPacketSize(packet.packetSize),
    ttl: clampTtl(packet.ttl),
    headerSize: checkHeaderSize(packet.headerSize),
    maxPayload: packet.maxPayload === undefined ? DEFAULT_MAX_PAYLOAD : packet.maxPayload,
    bufferLength: alignBuffer(packet.bufferLength),
    shardId: checkShard(packet.connectionId, expectedShardId),
    fragmentOffset: checkFragmentOffset(packet.fragmentOffset),
    dropped: packet.timeoutCount > TIMEOUT_DROP_THRESHOLD
  };
}

function report(label, packet, expectedShardId) {
  try {
    console.log(`${label}: ok -> ${JSON.stringify(processPacket(packet, expectedShardId))}`);
  } catch (err) {
    console.log(`${label}: rejected -> ${err.name}: ${err.message}`);
  }
}

const shard = 300;
const cases = [
  ['nominal', { packetSize: 1400, ttl: 60, headerSize: HEADER_SIZE_EXTENDED, bufferLength: 1000, connectionId: 66860, fragmentOffset: 192, timeoutCount: 3 }],
  ['clamped ttl, dropped', { packetSize: MAX_PACKET_SIZE, ttl: 900, headerSize: HEADER_SIZE_SHORT, bufferLength: 200, connectionId: 1324, fragmentOffset: 0, timeoutCount: 400 }],
  ['oversize packet', { packetSize: 70000, ttl: 10, headerSize: HEADER_SIZE_SHORT, bufferLength: 0, connectionId: 300, fragmentOffset: 0, timeoutCount: 0 }],
  ['bad header', { packetSize: 512, ttl: 10, headerSize: 24, bufferLength: 80, connectionId: 300, fragmentOffset: 0, timeoutCount: 0 }],
  ['wrong shard', { packetSize: 512, ttl: 10, headerSize: HEADER_SIZE_EXTENDED, bufferLength: 80, connectionId: 301, fragmentOffset: 0, timeoutCount: 0 }],
  ['misaligned fragment', { packetSize: 512, ttl: MAX_TTL, headerSize: HEADER_SIZE_EXTENDED, bufferLength: 130, connectionId: 300, fragmentOffset: 100, timeoutCount: 0 }]
];

for (const [label, packet] of cases) {
  report(label, packet, shard);
}

