'use strict';

const LIMITS = {
  headingDepth: 16,
  listNesting: 32,
  blockquoteNesting: 64,
  textNode: 4096,
  linkUrl: 256,
  inlineCode: 128,
  paragraph: 1024,
  metaAttribute: 255,
  totalNodes: 65535,
};

function countNodes(node) {
  let total = 1;
  for (const child of node.children || []) total += countNodes(child);
  return total;
}

function clamp(value, limit, label, report) {
  if (typeof value !== 'string' || value.length <= limit) return value;
  report.push(`${label}: truncated ${value.length} -> ${limit}`);
  return value.slice(0, limit);
}

function sanitizeMetadata(meta, report) {
  const out = {};
  for (const [key, raw] of Object.entries(meta)) {
    const name = clamp(String(key), LIMITS.metaAttribute, 'meta key', report);
    out[name] = clamp(String(raw), LIMITS.metaAttribute, `meta[${name}]`, report);
  }
  return out;
}

function textLength(node) {
  if (typeof node.value === 'string') return node.value.length;
  return (node.children || []).reduce((sum, child) => sum + textLength(child), 0);
}

function clampParagraph(node, report) {
  let used = 0;
  const kept = [];
  for (const child of node.children || []) {
    const len = textLength(child);
    if (used + len <= LIMITS.paragraph) {
      kept.push(child);
      used += len;
    } else if (typeof child.value === 'string') {
      child.value = child.value.slice(0, LIMITS.paragraph - used);
      kept.push(child);
      report.push(`paragraph trimmed to ${LIMITS.paragraph} characters`);
      break;
    } else break;
  }
  node.children = kept;
}

function walk(node, depth, report) {
  if (node.type === 'list') {
    if (depth.list >= LIMITS.listNesting) {
      report.push(`dropped list nested deeper than ${LIMITS.listNesting} levels`);
      return null;
    }
    depth = { ...depth, list: depth.list + 1 };
  }
  if (node.type === 'blockquote') {
    if (depth.quote >= LIMITS.blockquoteNesting) {
      report.push(`dropped blockquote nested deeper than ${LIMITS.blockquoteNesting} levels`);
      return null;
    }
    depth = { ...depth, quote: depth.quote + 1 };
  }
  if (node.type === 'heading' && node.depth > LIMITS.headingDepth) {
    report.push(`heading depth ${node.depth} clamped`);
    node.depth = LIMITS.headingDepth;
  }
  if (node.type === 'text') node.value = clamp(node.value, LIMITS.textNode, 'text node', report);
  if (node.type === 'inlineCode') node.value = clamp(node.value, LIMITS.inlineCode, 'inline code', report);
  if (node.type === 'link') node.url = clamp(node.url, LIMITS.linkUrl, 'link url', report);
  if (node.children) {
    node.children = node.children.map((c) => walk(c, depth, report)).filter((c) => c !== null);
