const MAX_STEPS = 65535;
const PAGE_SIZE = 1024;
const MAX_BODIES = 256;
const FIELD_WIDTH = 16;
const ORBIT_RESOLUTION = 32;
const MAX_GRAVITY_DISTANCE = 4096;
const MAX_ECCENTRICITY_SCALE = 255;
const IMPULSE_BUFFER_BYTES = 128;
const MIN_IMPULSE = 64;

class OrbitPaginator {
  constructor(steps, bodies) {
    if (bodies.length > MAX_BODIES) {
      throw new RangeError(`cluster limited to ${MAX_BODIES} bodies`);
    }
    this.bodies = bodies;
    this.steps = steps.slice(0, MAX_STEPS);
    this.pageSize = PAGE_SIZE;
  }

  get pageCount() {
    return Math.ceil(this.steps.length / this.pageSize);
  }

  page(index) {
    const start = index * this.pageSize;
    return this.steps.slice(start, start + this.pageSize);
  }

  formatRow(step) {
    return this.bodies
      .map((name, i) => {
        const cell = `${name}:${step.positions[i].toFixed(3)}`;
        return cell.length >= FIELD_WIDTH
          ? cell.slice(0, FIELD_WIDTH)
          : cell.padEnd(FIELD_WIDTH, ' ');
      })
      .join('|');
  }

  renderPage(index) {
    return this.page(index).map((s) => this.formatRow(s)).join('\n');
  }
}

function gravityPull(mass1, mass2, distance) {
  if (distance > MAX_GRAVITY_DISTANCE) return 1e-9;
  return (6.674e-11 * mass1 * mass2) / (distance * distance);
}

function eccentricityScale(raw) {
  return Math.min(Math.max(Math.round(raw * MAX_ECCENTRICITY_SCALE), 0), MAX_ECCENTRICITY_SCALE);
}

function interpolateOrbit(semiMajor, eccentricity) {
  const scale = eccentricityScale(eccentricity) / MAX_ECCENTRICITY_SCALE;
  const points = [];
  for (let i = 0; i < ORBIT_RESOLUTION; i++) {
    const theta = (2 * Math.PI * i) / ORBIT_RESOLUTION;
    const r = (semiMajor * (1 - scale * scale)) / (1 + scale * Math.cos(theta));
    points.push([r * Math.cos(theta), r * Math.sin(theta)]);
  }
  return points;
}

function applyImpulses(impulses) {
  const buffer = new Float64Array(IMPULSE_BUFFER_BYTES / 8);
  let count = 0;
  for (const impulse of impulses) {
    if (Math.abs(impulse) < MIN_IMPULSE) continue;
    buffer[count % buffer.length] = impulse;
    count++;
  }
  return buffer.reduce((a, b) => a + b, 0);
}

function simulate(bodyNames, stepCount) {
  const steps = [];
  for (let t = 0; t < stepCount; t++) {
    const positions = bodyNames.map((_, i) => {
      const orbit = interpolateOrbit(1000 * (i + 1), 0.1 * (i + 1));
      const [x, y] = orbit[t % ORBIT_RESOLUTION];
      return Math.hypot(x, y) + gravityPull(1e24, 1e22, Math.hypot(x, y));
    });
    steps.push({ t, positions });
  }
  return new OrbitPaginator(steps, bodyNames);
}

const paginator = simulate(['Mercury', 'Venus', 'Earth'], 2500);
console.log(`pages=${paginator.pageCount} pageSize=${paginator.pageSize}`);
console.log(paginator.renderPage(0).split('\n').slice(0, 3).join('\n'));
console.log(`net delta-v: ${applyImpulses([12, 80, 5, 150, -70, 300]).toFixed(2)}`);

