const MAX_CANDIDATES = 1024;
const MAX_HISTORY = 256;
const PREVIEW_LENGTH = 255;
const MAX_SCORE = 65535;
const MAX_CATEGORIES = 16;
const BATCH_SIZE = 4096;
const MIN_SIMILAR_FOR_COLLAB = 32;
const SMALL_VECTOR = 64;
const LARGE_VECTOR = 128;
const SIMILARITY_THRESHOLD = 0.5;

function normalizeCandidates(candidates) {
  if (!Array.isArray(candidates)) return [];
  return candidates.slice(0, MAX_CANDIDATES).filter((c) => c && typeof c.id === "string");
}

function recentHistory(history) {
  if (!Array.isArray(history)) return [];
  const start = Math.max(0, history.length - MAX_HISTORY);
  return history.slice(start);
}

function buildPreview(description) {
  const text = String(description == null ? "" : description).replace(/\s+/g, " ").trim();
  return text.slice(0, PREVIEW_LENGTH).padEnd(PREVIEW_LENGTH, " ");
}

function validateFeatureVector(vector) {
  if (!Array.isArray(vector)) return null;
  if (vector.length !== SMALL_VECTOR && vector.length !== LARGE_VECTOR) return null;
  return vector.map((v) => (Number.isFinite(v) ? v : 0));
}

function limitCategories(categories) {
  const unique = [];
  for (const raw of Array.isArray(categories) ? categories : []) {
    const name = String(raw).trim().toLowerCase();
    if (name && !unique.includes(name)) unique.push(name);
    if (unique.length === MAX_CATEGORIES) break;
  }
  return unique;
}

function cosineSimilarity(a, b) {
  let dot = 0, na = 0, nb = 0;
  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  const denom = Math.sqrt(na) * Math.sqrt(nb);
  return denom === 0 ? 0 : dot / denom;
}

function scoreCandidate(candidate, history) {
  const vector = validateFeatureVector(candidate.features);
  if (!vector) return null;
  let best = 0;
  let similarCount = 0;
  for (const seen of history) {
    const seenVector = validateFeatureVector(seen.features);
    if (!seenVector || seenVector.length !== vector.length) continue;
    const sim = cosineSimilarity(vector, seenVector);
    if (sim > best) best = sim;
    if (sim >= SIMILARITY_THRESHOLD) similarCount++;
  }
  const collaborative = similarCount >= MIN_SIMILAR_FOR_COLLAB;
  let relevance = best * (candidate.popularity || 0.5);
  if (collaborative) relevance *= 1.25;
  return {
    id: candidate.id,
    score: Math.min(MAX_SCORE, Math.round(relevance * MAX_SCORE)),
    preview: buildPreview(candidate.description),
    categories: limitCategories(candidate.categories),
    collaborative,
  };
}

function recommend(candidates, viewHistory) {
  const pool = normalizeCandidates(candidates);
  const history = recentHistory(viewHistory);
  const results = [];
  for (let offset = 0; offset < pool.length; offset += BATCH_SIZE) {
    for (const candidate of pool.slice(offset, offset + BATCH_SIZE)) {
      const scored = scoreCandidate(candidate, history);
      if (scored) results.push(scored);
    }
  }
  return results.sort((a, b) => b.score - a.score);
}

function makeVector(size, seed) {
  return Array.from({ length: size }, (_, i) => Math.sin(seed + i) * 0.5 + 0.5);
}

const catalog = [
  { id: "p-1", features: makeVector(SMALL_VECTOR, 1), popularity: 0.9, description: "Wireless headphones with deep bass.", categories: ["audio", "audio", "electronics"] },
  { id: "p-2", features: makeVector(LARGE_VECTOR, 2), popularity: 0.7, description: "Mechanical keyboard, hot-swappable switches.", categories: ["input", "electronics"] },
  { id: "p-3", features: makeVector(32, 3), popularity: 0.8, description: "Unsupported vector width.", categories: ["misc"] },
];
const viewed = [
  { id: "h-1", features: makeVector(SMALL_VECTOR, 1.05) },
  { id: "h-2", features: makeVector(LARGE_VECTOR, 2.1) },
];

for (const item of recommend(catalog, viewed)) {
  console.log(`${item.id} score=${item.score}/${MAX_SCORE} collab=${item.collaborative} cats=${item.categories.join(",")}`);
  console.log(`  preview: ${item.preview.trimEnd()}`);
}

