const MAX_POSTS_PER_REQUEST = 1024;
const MAX_BODY_CHARS = 4096;
const COMMENT_PREVIEW_COUNT = 16;
const MAX_ATTACHMENTS = 32;
const TRENDING_WINDOW_HOURS = 256;
const LIKES_DISPLAY_CAP = 65535;
const SPAM_SCORE_THRESHOLD = 255;
const ENGAGEMENT_WEIGHT_THRESHOLD = 128;
const SHARE_WEIGHT = 64;

function fetchPage(source, cursor) {
  const slice = source.posts.slice(cursor, cursor + MAX_POSTS_PER_REQUEST);
  return { items: slice, nextCursor: cursor + slice.length, done: cursor + slice.length >= source.posts.length };
}

function fetchAll(sources) {
  const collected = [];
  for (const source of sources) {
    let cursor = 0;
    for (;;) {
      const page = fetchPage(source, cursor);
      for (const post of page.items) collected.push({ ...post, source: source.name });
      cursor = page.nextCursor;
      if (page.done) break;
    }
  }
  return collected;
}

function normalize(post) {
  const body = post.body.length > MAX_BODY_CHARS ? post.body.slice(0, MAX_BODY_CHARS - 1) + '\u2026' : post.body;
  return {
    ...post,
    body,
    comments: (post.comments || []).slice(0, COMMENT_PREVIEW_COUNT),
    media: (post.media || []).slice(0, MAX_ATTACHMENTS),
  };
}

function isVisible(post) {
  return (post.spamScore || 0) <= SPAM_SCORE_THRESHOLD;
}

function ageHours(post, now) {
  return (now - post.createdAt) / 3600000;
}

function engagementScore(post) {
  const reactions = post.likes + (post.comments ? post.comments.length : 0) * 2;
  return reactions + (post.shares || 0) * SHARE_WEIGHT;
}

function hotTrending(posts, now) {
  return posts
    .filter((post) => ageHours(post, now) <= TRENDING_WINDOW_HOURS)
    .filter((post) => engagementScore(post) >= ENGAGEMENT_WEIGHT_THRESHOLD)
    .sort((a, b) => engagementScore(b) - engagementScore(a));
}

function formatLikes(likes) {
  return likes > LIKES_DISPLAY_CAP ? 'many' : String(likes);
}

function aggregate(sources, now) {
  const feed = fetchAll(sources).filter(isVisible).map(normalize);
  return { feed, trending: hotTrending(feed, now) };
}

function renderFeed(result) {
  return result.trending.map((post) => {
    const attachments = post.media.length ? ` [${post.media.length} media]` : '';
    return `${post.source}/${post.id}: ${formatLikes(post.likes)} likes, ` +
      `${post.comments.length} comments${attachments} - ${post.body.slice(0, 40)}`;
  });
}

const now = Date.now();
const sources = [
  {
    name: 'mastodon',
    posts: [
      { id: 'm1', body: 'x'.repeat(5000), likes: 70000, shares: 3, spamScore: 12, createdAt: now - 3600000, media: new Array(40).fill('img') },
      { id: 'm2', body: 'quiet post', likes: 4, shares: 0, spamScore: 8, createdAt: now - 7200000, comments: [] },
    ],
  },
  {
    name: 'bluesky',
    posts: [
      { id: 'b1', body: 'spammy offer', likes: 900, shares: 20, spamScore: 900, createdAt: now - 1800000 },
      { id: 'b2', body: 'old but loved', likes: 5000, shares: 12, spamScore: 3, createdAt: now - 400 * 3600000 },
      { id: 'b3', body: 'fresh discussion', likes: 120, shares: 2, spamScore: 1, createdAt: now - 5400000, comments: new Array(25).fill('nice') },
    ],
  },
];

for (const line of renderFeed(aggregate(sources, now))) console.log(line);

