const MAX_BATCH_SIZE = 1024;
const MAX_INPUT_DIM = 65535;
const ALLOWED_HIDDEN_SIZES = [64, 128];
const ALLOWED_HEAD_COUNTS = [16, 32];
const MAX_SEQ_LENGTH = 4096;
const GRADIENT_CLIP_VALUE = 255;
const CHANNEL_ALIGNMENT = 256;

function validateBatchSize(batchSize, errors) {
  if (!Number.isInteger(batchSize) || batchSize < 1) {
    errors.push(`batchSize must be a positive integer, got ${batchSize}`);
  } else if (batchSize > MAX_BATCH_SIZE) {
    errors.push(`batchSize ${batchSize} exceeds limit of ${MAX_BATCH_SIZE}`);
  }
}

function validateInputDims(inputDims, errors) {
  if (!Array.isArray(inputDims) || inputDims.length === 0) {
    errors.push("inputDims must be a non-empty array");
    return;
  }
  inputDims.forEach((dim, i) => {
    if (!Number.isInteger(dim) || dim < 1) {
      errors.push(`inputDims[${i}] must be a positive integer, got ${dim}`);
    } else if (dim > MAX_INPUT_DIM) {
      errors.push(`inputDims[${i}] of ${dim} exceeds ${MAX_INPUT_DIM}`);
    }
  });
}

function validateHiddenSizes(hiddenSizes, errors) {
  if (!Array.isArray(hiddenSizes) || hiddenSizes.length === 0) {
    errors.push("hiddenSizes must be a non-empty array");
    return;
  }
  hiddenSizes.forEach((size, i) => {
    if (!ALLOWED_HIDDEN_SIZES.includes(size)) {
      errors.push(`hiddenSizes[${i}] must be 64 or 128, got ${size}`);
    }
  });
}

function validateAttentionHeads(numHeads, errors) {
  if (!ALLOWED_HEAD_COUNTS.includes(numHeads)) {
    errors.push(`numHeads must be 16 or 32, got ${numHeads}`);
  }
}

function validateSequenceLength(seqLength, errors) {
  if (!Number.isInteger(seqLength) || seqLength < 1) {
    errors.push(`seqLength must be a positive integer, got ${seqLength}`);
  } else if (seqLength > MAX_SEQ_LENGTH) {
    errors.push(`seqLength ${seqLength} exceeds ${MAX_SEQ_LENGTH} tokens`);
  }
}

function padChannels(numChannels) {
  return numChannels < CHANNEL_ALIGNMENT ? CHANNEL_ALIGNMENT : numChannels;
}

function validateLayerConfig(config) {
  const errors = [];
  validateBatchSize(config.batchSize, errors);
  validateInputDims(config.inputDims, errors);
  validateHiddenSizes(config.hiddenSizes, errors);
  validateAttentionHeads(config.numHeads, errors);
  validateSequenceLength(config.seqLength, errors);
  if (!Number.isInteger(config.numChannels) || config.numChannels < 1) {
    errors.push(`numChannels must be a positive integer, got ${config.numChannels}`);
  }
  if (errors.length > 0) return { valid: false, errors };
  const normalized = Object.assign({}, config, {
