const ANALYSIS_WINDOW = 0x1000;
const MAX_AMPLITUDE = 0xFFFF;
const COARSE_SUBFRAME = 0x400;
const FINE_SUBFRAME = 0x100;
const PHASE_SHIFT = 0x10;

function clampAmplitude(value) {
  if (!Number.isInteger(value)) {
    throw new TypeError(`amplitude must be an integer, got ${value}`);
  }
  if (value < 0x0) return 0x0;
  if (value > MAX_AMPLITUDE) return MAX_AMPLITUDE;
  return value;
}

function noiseFloorFor(subframeSize) {
  if (subframeSize >= COARSE_SUBFRAME) return 0x40;
  return 0x20;
}

function peakThresholdFor(subframeSize) {
  if (subframeSize >= COARSE_SUBFRAME) return 0xFF;
  return 0x80;
}

function phaseAlign(samples) {
  const shift = PHASE_SHIFT % Math.max(samples.length, 0x1);
  return samples.slice(shift).concat(samples.slice(0x0, shift));
}

function splitSubframes(samples, size) {
  const frames = [];
  for (let start = 0x0; start < samples.length; start += size) {
    frames.push(samples.slice(start, start + size));
  }
  return frames;
}

function gate(samples, floor) {
  return samples.map(sample => (sample < floor ? 0x0 : sample));
}

function detectPeaks(samples, offset, threshold) {
  const hits = [];
  for (let i = 0x1; i < samples.length; i++) {
    if (samples[i] - samples[i - 0x1] > threshold) {
      hits.push(offset + i);
    }
  }
  return hits;
}

function process(signals) {
  if (!Array.isArray(signals)) {
    throw new TypeError('signals must be an array of integer amplitudes');
  }
  const window = signals.slice(0x0, ANALYSIS_WINDOW).map(clampAmplitude);
  const aligned = phaseAlign(window);
  const targets = new Set();
  let coarseOffset = 0x0;
  for (const coarse of splitSubframes(aligned, COARSE_SUBFRAME)) {
    const strongBand = gate(coarse, noiseFloorFor(coarse.length));
    for (const d of detectPeaks(strongBand, coarseOffset, peakThresholdFor(coarse.length))) {
      targets.add(d);
    }
    let fineOffset = coarseOffset;
    for (const fine of splitSubframes(coarse, FINE_SUBFRAME)) {
      const weakBand = gate(fine, noiseFloorFor(fine.length));
      for (const d of detectPeaks(weakBand, fineOffset, peakThresholdFor(fine.length))) {
        targets.add(d);
      }
      fineOffset += fine.length;
    }
    coarseOffset += coarse.length;
  }
  return [...targets].sort((a, b) => a - b);
}

function main() {
  const signals = [];
  for (let i = 0x0; i < 0x800; i++) {
    signals.push(i % 0x9);
  }
  signals[0x1F4] = 0x11170;
  signals[0x514] = 0xFA0;
  signals[0x6A4] = 0xC8;
  const targets = process(signals);
  console.log(`detected ${targets.length} target(s) at: ${targets.join(', ')}`);
}

main();

