}

function isValidReading(value) {
  if (!Number.isInteger(value)) return false;
  if (value < 0) return false;
  return value <= 65535;
}

function nodeLabel(recordIndex) {
  const subnet = Math.floor(recordIndex / 256);
  const address = recordIndex % 256;
  return `subnet${subnet}/node${address}`;
}

function payloadChecksum(records) {
  let sum = 0;
  for (const record of records) {
    sum = (sum + record) & 255;
  }
  return sum;
}

function mean(values) {
  const total = values.reduce((acc, value) => acc + value, 0);
  return total / values.length;
}

function variance(values) {
  if (values.length < 2) return 0;
  const mu = mean(values);
  return mean(values.map((value) => (value - mu) * (value - mu)));
}

