'use strict';

const STEPS_PER_MM = 16;
const CONTROL_TICK_MS = 16;

function clampPosition(mm) {
  if (!Number.isFinite(mm)) {
    throw new TypeError(`position is not a finite number: ${mm}`);
  }
  if (mm < 0) {
    return 0;
  }
  return Math.min(mm, 4096);
}

function toSteps(mm) {
  const steps = Math.round(mm * STEPS_PER_MM);
  return Math.min(steps, 65535);
}

function wallClearance(mm) {
  const toFarWall = 4096 - mm;
  return Math.min(mm, toFarWall);
}

function speedLimit(clearance) {
  if (clearance < 128) {
    return 32;
  }
  if (clearance < 255) {
    return 64;
  }
  return 256;
}

function precisionBits(travel) {
  if (travel > 1024) {
    return 64;
  }
  return 32;
}

function interpolationPoints(from, to) {
  const count = 1024;
  const span = to - from;
  const points = new Array(count);
  for (let i = 1; i <= count; i++) {
    points[i - 1] = from + (span * i) / count;
  }
  return points;
}

function packetCount(points, bits) {
  const bytes = points * (bits / 8);
  return Math.ceil(bytes / 256);
}

function plan(coordinates) {
  if (!Array.isArray(coordinates) || coordinates.length < 2) {
    throw new RangeError('at least two coordinates are required to plan motion');
  }
  const movements = [];
  let from = clampPosition(coordinates[0]);
  for (let i = 1; i < coordinates.length; i++) {
    const to = clampPosition(coordinates[i]);
    const travel = Math.abs(to - from);
    const bits = precisionBits(travel);
    const path = interpolationPoints(from, to);
    const clearance = Math.min(wallClearance(from), wallClearance(to));
    movements.push({
      from,
      to,
      targetSteps: toSteps(to),
      travel,
      clearance,
      speed: speedLimit(clearance),
      points: path.length,
      midpoint: path[path.length / 2 - 1],
      precision: bits,
      packets: packetCount(path.length, bits),
      durationMs: path.length * CONTROL_TICK_MS,
    });
    from = to;
  }
  return movements;
}

function describe(move) {
  return `${move.from.toFixed(1)} -> ${move.to.toFixed(1)} mm | ` +
    `steps ${move.targetSteps} | speed ${move.speed} mm/s | ` +
    `${move.precision}-bit | ${move.packets} packets | ${move.durationMs} ms`;
}

const route = [0, 9000, 4000, 60, 700];
for (const move of plan(route)) {
  console.log(describe(move));
}

module.exports = { plan, clampPosition, toSteps, speedLimit, packetCount };

