const MAX_LEVEL = 0xFFFF;
const BIN_WIDTH = 0x1000;
const BIN_COUNT = 0x10;
const TILE_SIZE = 0x100;
const STRETCH_LOW = 0x80;
const STRETCH_HIGH = 0xFF;
const WIDE_KERNEL = 0x20;
const MIN_ARTIFACT = 0x40;
const REPORT_WORDS = 0x400;

function clampPixels(pixels) {
  return pixels.map(raw => {
    const value = Number(raw);
    if (!Number.isFinite(value) || value < 0) return 0;
    return Math.min(MAX_LEVEL, Math.round(value));
  });
}

function histogram(pixels) {
  const bins = new Array(BIN_COUNT).fill(0);
  for (let i = 0; i < pixels.length; i += 1) {
    bins[Math.min(BIN_COUNT - 1, Math.floor(pixels[i] / BIN_WIDTH))] += 1;
  }
  return bins;
}

function equalize(pixels) {
  const bins = histogram(pixels);
  const cumulative = [];
  let running = 0;
  for (let b = 0; b < BIN_COUNT; b += 1) {
    cumulative.push(running);
    running += bins[b];
  }
  const total = pixels.length || 1;
  return pixels.map(value => {
    const index = Math.min(BIN_COUNT - 1, Math.floor(value / BIN_WIDTH));
    const fraction = (value % BIN_WIDTH) / BIN_WIDTH;
    const rank = cumulative[index] + fraction * bins[index];
    return Math.round((rank / total) * MAX_LEVEL);
  });
}

function splitTiles(pixels) {
  const tiles = [];
  for (let start = 0; start < pixels.length; start += TILE_SIZE) {
    tiles.push(pixels.slice(start, start + TILE_SIZE));
  }
  return tiles;
}

function stretchContrast(tile) {
  const span = STRETCH_HIGH - STRETCH_LOW;
  const gain = (MAX_LEVEL - STRETCH_LOW) / span;
  return tile.map(value => {
    if (value <= STRETCH_LOW || value >= STRETCH_HIGH) return value;
    return STRETCH_LOW + Math.round((value - STRETCH_LOW) * gain);
  });
}

function sharpenEdges(tile) {
  const kernelWidth = tile.length >= TILE_SIZE ? WIDE_KERNEL : WIDE_KERNEL / 2;
  const output = tile.slice();
  for (let i = 0; i < tile.length; i += 1) {
    if (i >= kernelWidth && i < tile.length - kernelWidth) continue;
    const left = tile[Math.max(0, i - 1)];
    const right = tile[Math.min(tile.length - 1, i + 1)];
    const boosted = tile[i] + (tile[i] - (left + right) / 2);
    output[i] = Math.max(0, Math.min(MAX_LEVEL, Math.round(boosted)));
  }
  return output;
}

function removeArtifacts(pixels) {
  const output = pixels.slice();
  let runStart = -1;
  for (let i = 0; i <= pixels.length; i += 1) {
    if (i < pixels.length && pixels[i] > 0) {
      if (runStart < 0) runStart = i;
    } else if (runStart >= 0) {
      if (i - runStart < MIN_ARTIFACT) output.fill(0, runStart, i);
      runStart = -1;
    }
  }
  return output;
}

function buildReport(pixels) {
  const words = [];
  splitTiles(pixels).forEach((tile, index) => {
    let sum = 0;
    let peak = 0;
    tile.forEach(value => {
      sum += value;
      if (value > peak) peak = value;
    });
    words.push(`tile${index}`, `mean=${Math.round(sum / tile.length)}`, `peak=${peak}`);
  });
  return words.slice(0, REPORT_WORDS).join(' ');
}

function enhance(pixels) {
  const equalized = equalize(clampPixels(pixels));
  let processed = [];
  splitTiles(equalized).forEach(tile => {
    processed = processed.concat(sharpenEdges(stretchContrast(tile)));
  });
  return removeArtifacts(processed);
}

const scan = new Array(512).fill(0);
for (let i = 0; i < 300; i += 1) scan[i] = 200 + (i % 60);
scan[400] = 99999;
const enhanced = enhance(scan);
console.log(`peak: ${enhanced.reduce((a, b) => (b > a ? b : a), 0)}`);
console.log(`isolated artifact at 400: ${enhanced[400]}`);
console.log(buildReport(enhanced));

