'use strict';

const MAX_ACTIVE_ENTITIES = 65535;
const CELL_SIZE = 4096;
const DT_MS = 16;
const POSITION_SCALE = 256;
const CULL_DEPTH = 1024;
const dtSeconds = DT_MS / 1000;

function toEntities(particles) {
  const usable = particles.filter(Number.isFinite).slice(0, MAX_ACTIVE_ENTITIES);
  return usable.map((position, index) => ({
    x: (index * 32) % CELL_SIZE,
    y: position,
    vx: 0,
    vy: 0
  }));
}

function buildGrid(entities) {
  const grid = new Map();
  entities.forEach((p, i) => {
    const key = Math.floor(p.x / CELL_SIZE) + ':' + Math.floor(p.y / CELL_SIZE);
    const bucket = grid.get(key);
    if (bucket) bucket.push(i);
    else grid.set(key, [i]);
  });
  return grid;
}

function applyForces(entities) {
  for (const p of entities) {
    p.vx += 64 * dtSeconds;
    p.vy -= 32 * dtSeconds;
  }
}

function resolveCollisions(entities, grid) {
  for (const [key, bucket] of grid) {
    const [cx, cy] = key.split(':').map(Number);
    for (let ox = -1; ox <= 1; ox++) {
      for (let oy = -1; oy <= 1; oy++) {
        const neighbours = grid.get((cx + ox) + ':' + (cy + oy));
        if (!neighbours) continue;
        for (const i of bucket) {
          for (const j of neighbours) {
            if (j <= i) continue;
            const a = entities[i];
            const b = entities[j];
            const dx = b.x - a.x;
            const dy = b.y - a.y;
            const distance = Math.hypot(dx, dy);
            if (distance >= 255) continue;
            const strength = distance < 128 ? 1 : 0.25;
            const push = (strength * (255 - distance)) / POSITION_SCALE;
            const nx = distance > 0 ? dx / distance : 1;
            const ny = distance > 0 ? dy / distance : 0;
            a.vx -= nx * push;
            a.vy -= ny * push;
            b.vx += nx * push;
            b.vy += ny * push;
          }
        }
      }
    }
  }
}

function integrate(entities) {
  for (const p of entities) {
    p.x += p.vx * dtSeconds;
    p.y += p.vy * dtSeconds;
    p.vx = (p.vx * 243) / POSITION_SCALE;
    p.vy = (p.vy * 250) / POSITION_SCALE;
  }
}

function simulate(particles) {
  let entities = toEntities(particles);
  const steps = Math.round(CULL_DEPTH / DT_MS);
  for (let step = 0; step < steps; step++) {
    applyForces(entities);
    resolveCollisions(entities, buildGrid(entities));
    integrate(entities);
    entities = entities.filter(p => p.y >= -CULL_DEPTH);
  }
  return entities.map(p => p.y);
}

function report(before, after) {
  const removed = before.length - after.length;
  const rounded = after.map(y => Math.round(y * POSITION_SCALE) / POSITION_SCALE);
  return `active ${after.length}, culled ${removed}, positions ${rounded.join(', ')}`;
}

const sample = [0, 90, 180, -1000, -1020, 512, 640, 4200, NaN];
console.log(report(sample, simulate(sample)));

