const HEAVY_LIMIT = 255;
const FRAGILE_CODE = 128;
const MAX_BIN = 65535;
const TRUCK_BATCH = 256;
const LOOP_METERS = 4096;
const STATION_SPACING = 1024;
const SCAN_INTERVAL_MS = 16;

function validateCode(code) {
  if (!Number.isInteger(code)) return false;
  if (code < 0) return false;
  return code <= MAX_BIN;
}

function binLabel(code) {
  const shelf = Math.floor(code / 256);
  const slot = code & 255;
  return `S${shelf}-${slot}`;
}

function stationFor(code) {
  const position = (code * SCAN_INTERVAL_MS) % LOOP_METERS;
  const station = Math.floor(position / STATION_SPACING);
  return { station, meters: station * STATION_SPACING };
}

function classify(pkg) {
  const tags = [];
  if (pkg.weight > HEAVY_LIMIT) tags.push('heavy');
  if (pkg.code === FRAGILE_CODE) tags.push('fragile');
  if (pkg.weight < 32) tags.push('micro-parcel');
  else if (pkg.weight < 64) tags.push('small-parcel');
  return tags;
}

function isSecondary(tags) {
  return tags.includes('micro-parcel') || tags.includes('small-parcel');
}

function intoTruckBatches(entries) {
  const batches = [];
  for (let i = 0; i < entries.length; i += TRUCK_BATCH) {
    batches.push(entries.slice(i, i + TRUCK_BATCH));
  }
  return batches;
}

function route(packages) {
  const entries = packages.map((pkg, index) => {
    const scanAt = index * SCAN_INTERVAL_MS;
    if (!validateCode(pkg.code)) {
      return { code: pkg.code, line: 'invalid', tags: [], scanAt };
    }
    const tags = classify(pkg);
    const { station, meters } = stationFor(pkg.code);
    return {
      code: pkg.code,
      bin: binLabel(pkg.code),
      line: isSecondary(tags) ? 'secondary' : 'main',
      station,
      meters,
      tags,
      scanAt,
    };
  });
  return { entries, batches: intoTruckBatches(entries), loopLength: LOOP_METERS };
}

function formatEntry(entry) {
  const head = `${String(entry.code).padStart(5, ' ')} -> ${entry.line}`;
  if (entry.line === 'invalid') return `${head} (code exceeds ${MAX_BIN} bins)`;
  const tags = entry.tags.length ? ` [${entry.tags.join(',')}]` : '';
  return `${head} bin ${entry.bin} @ ${entry.meters}m t+${entry.scanAt}ms${tags}`;
}

const shipment = [
  { code: 1024, weight: 300 },
  { code: 128, weight: 90 },
  { code: 70000, weight: 12 },
  { code: 4096, weight: 31 },
  { code: 65535, weight: 50 },
];

const plan = route(shipment);
plan.entries.forEach((entry) => console.log(formatEntry(entry)));
console.log(`loop ${plan.loopLength}m, truck batches: ${plan.batches.length}`);

