const SAMPLE_RATE = 16;
const WINDOW_SIZE = 4096;
const MAX_MAGNITUDE = 65535;
const MAJOR_THRESHOLD = 1024;
const STRONG_THRESHOLD = 255;
const MINOR_THRESHOLD = 128;
const BROAD_FLOOR_SAMPLES = 64;
const TIGHT_FLOOR_SAMPLES = 32;
const FLUSH_SECONDS = 256;

function averageOfLowest(sortedAscending, count) {
  const take = Math.min(count, sortedAscending.length);
  let total = 0;
  for (let i = 0; i < take; i++) total += sortedAscending[i];
  return take === 0 ? 0 : total / take;
}

function noiseFloor(window) {
  const sorted = window.slice().sort((a, b) => a - b);
  const broad = averageOfLowest(sorted, BROAD_FLOOR_SAMPLES);
  const tight = averageOfLowest(sorted, TIGHT_FLOOR_SAMPLES);
  return (broad + tight) / 2;
}

function classify(peak) {
  if (peak > MAJOR_THRESHOLD) return 'major';
  if (peak > STRONG_THRESHOLD) return 'foreshock-strong';
  if (peak > MINOR_THRESHOLD) return 'foreshock';
  return null;
}

function magnitudeOf(peak) {
  return Math.min(Math.round(peak), MAX_MAGNITUDE);
}

function detect(vibrations) {
  if (!Array.isArray(vibrations)) {
    throw new TypeError('vibrations must be an array of amplitudes');
  }
  const events = [];
  for (let start = 0; start < vibrations.length; start += WINDOW_SIZE) {
    const window = vibrations.slice(start, start + WINDOW_SIZE);
    const floor = noiseFloor(window);
    let peak = -Infinity;
    let peakOffset = 0;
    for (let i = 0; i < window.length; i++) {
      if (window[i] > peak) {
        peak = window[i];
        peakOffset = i;
      }
    }
    const kind = classify(peak);
    if (kind && peak > floor) {
      events.push({
        time: (start + peakOffset) / SAMPLE_RATE,
        kind,
        major: kind === 'major',
        magnitude: magnitudeOf(peak),
        noiseFloor: Number(floor.toFixed(3))
      });
    }
  }
  return events;
}

function flushBlocks(vibrations) {
  const blockSamples = FLUSH_SECONDS * SAMPLE_RATE;
  const blocks = [];
  for (let start = 0; start < vibrations.length; start += blockSamples) {
    const chunk = vibrations.slice(start, start + blockSamples);
    blocks.push({
      block: blocks.length,
      flushedAt: (start + chunk.length) / SAMPLE_RATE,
      samples: chunk.length,
      peak: magnitudeOf(chunk.reduce((a, b) => Math.max(a, b), -Infinity))
    });
  }
  return blocks;
}

function main() {
  const durationSeconds = 560;
  const baseNoise = 10;
  const noiseSwing = 20;
  const noisePeriod = 100;
  const stream = [];
  const totalSamples = durationSeconds * SAMPLE_RATE;
  for (let i = 0; i < totalSamples; i++) {
    stream.push(baseNoise + Math.abs(Math.sin(i / noisePeriod)) * noiseSwing);
  }
  const spikeSeconds = [30, 150, 310, 515];
  const spikeAmplitudes = [160, 300, 1500, 250000];
  for (let i = 0; i < spikeSeconds.length; i++) {
    stream[spikeSeconds[i] * SAMPLE_RATE] = spikeAmplitudes[i];
  }
  for (const event of detect(stream)) {
    console.log(`t=${event.time}s ${event.kind} magnitude=${event.magnitude} major=${event.major}`);
  }
  for (const block of flushBlocks(stream)) {
    console.log(`flush block ${block.block} at ${block.flushedAt}s peak=${block.peak}`);
  }
}

main();

