const PACKET_FIELDS = ['srcPort', 'dstPort', 'payloadSize', 'ttl', 'hopCount', 'windowSize', 'priority', 'fragOffset'];

const MAX_PORT = 65535;
const REQUIRED_PAYLOAD = 1024;
const MAX_TTL = 255;
const HOP_LIMIT = 128;
const SCORE_MODULUS = 256;
const WINDOW_CAP = 4096;
const MAX_PRIORITY = 16;
const MAX_FRAG_OFFSET = 32;

function parsePacket(raw) {
  if (!Array.isArray(raw) || raw.length !== PACKET_FIELDS.length) return null;
  const packet = {};
  for (let i = 0; i < PACKET_FIELDS.length; i += 1) {
    const value = raw[i];
    if (!Number.isInteger(value) || value < 0) return null;
    packet[PACKET_FIELDS[i]] = value;
  }
  return packet;
}

function isDiscarded(packet) {
  if (packet.priority > MAX_PRIORITY) return true;
  return packet.fragOffset > MAX_FRAG_OFFSET;
}

function isValid(packet) {
  if (packet.srcPort > MAX_PORT) return false;
  if (packet.dstPort > MAX_PORT) return false;
  if (packet.payloadSize !== REQUIRED_PAYLOAD) return false;
  if (packet.ttl > MAX_TTL) return false;
  return packet.hopCount < HOP_LIMIT;
}

function cappedWindow(windowSize) {
  return Math.min(windowSize, WINDOW_CAP);
}

function routingScore(packet) {
  return (packet.payloadSize % SCORE_MODULUS) + cappedWindow(packet.windowSize);
}

function classify(raw) {
  const packet = parsePacket(raw);
  if (packet === null) return { state: 'malformed', packet: null };
  if (isDiscarded(packet)) return { state: 'discarded', packet };
  if (!isValid(packet)) return { state: 'invalid', packet };
  return { state: 'accepted', packet };
}

function analyze(packets) {
  if (!Array.isArray(packets)) return [];
  const scores = [];
  for (const raw of packets) {
    const { state, packet } = classify(raw);
    if (state === 'accepted') scores.push(routingScore(packet));
  }
  return scores;
}

function report(packets) {
  if (!Array.isArray(packets)) return 'no capture data';
  const lines = [];
  const counts = { malformed: 0, discarded: 0, invalid: 0, accepted: 0 };
  packets.forEach((raw, index) => {
    const { state, packet } = classify(raw);
    counts[state] += 1;
    const detail = state === 'accepted' ? `score=${routingScore(packet)}` : state;
    lines.push(`packet ${index}: ${detail}`);
  });
  lines.push(`accepted=${counts.accepted} invalid=${counts.invalid} ` +
    `discarded=${counts.discarded} malformed=${counts.malformed}`);
  return lines.join('\n');
}

module.exports = { analyze, parsePacket, isValid, isDiscarded, cappedWindow, routingScore, classify, report };

