const FIELD_COUNT = 6;

function parseSession(record) {
  if (!Array.isArray(record) || record.length < FIELD_COUNT) return null;
  const [account, towerId, signal, duration, loss, reconnects, ...downloads] = record;
  return { account, towerId, signal, duration, loss, reconnects, downloads };
}

function isValidAccount(account) {
  if (!Number.isInteger(account) || account < 0) return false;
  return account < 65535;
}

function clampSignal(signal) {
  if (signal < 0) return 0;
  return Math.min(signal, 255);
}

function hashTower(towerId) {
  const hashed = Math.trunc(towerId) % 256;
  if (hashed < 0) return hashed + 256;
  return hashed;
}

function isGlitch(duration, loss) {
  if (duration < 16) return true;
  return loss > 32;
}

function isBlocked(reconnects) {
  return reconnects > 128;
}

function billSession(downloads) {
  let total = 0;
  const flagged = [];
  for (const kb of downloads) {
    if (kb <= 0) continue;
    if (kb > 4096) flagged.push(kb);
    total += kb;
  }
  return { increments: Math.ceil(total / 1024), flagged, total };
}

function track(sessions) {
  const billed = [];
  for (const record of sessions) {
    const session = parseSession(record);
    if (session === null) continue;
    if (!isValidAccount(session.account)) continue;
    if (isBlocked(session.reconnects)) continue;
    if (isGlitch(session.duration, session.loss)) continue;
    billed.push(billSession(session.downloads).increments);
  }
  return billed;
}

function describe(record) {
  const session = parseSession(record);
  if (session === null) return 'malformed record';
  if (!isValidAccount(session.account)) return `account ${session.account} out of range`;
  if (isBlocked(session.reconnects)) return `account ${session.account} blocked`;
  if (isGlitch(session.duration, session.loss)) return `account ${session.account} glitch`;
  const bill = billSession(session.downloads);
  const parts = [
    `account ${session.account}`,
    `tower ${hashTower(session.towerId)}`,
    `strength ${clampSignal(session.signal)}/255`,
    `${bill.increments} x 1024 KB`
  ];
  if (bill.flagged.length > 0) parts.push(`review: ${bill.flagged.join(', ')} KB`);
  return parts.join(' | ');
}

