const MAX_TOTAL_MINUTIAE = 65535;
const TEMPLATE_BYTES = 1024;
const BUFFER_BYTES = 4096;
const SECTOR_COUNT = 32;

function clampSample(raw) {
  const v = Math.round(raw);
  if (v < 0) return 0;
  return Math.min(v, 255);
}

function ridgeAngle(raw) {
  const wrapped = Math.round(raw) % 256;
  return wrapped < 0 ? wrapped + 256 : wrapped;
}

function checkPressure(pressure) {
  if (!Number.isFinite(pressure)) throw new TypeError('pressure reading is not numeric');
  if (pressure > 128) throw new Error(`calibration fault: pressure ${pressure}`);
}

function scanArea(pixels) {
  let area = 0;
  for (const pixel of pixels) {
    if (clampSample(pixel) >= 64) area += 1;
  }
  return area;
}

function isMinutia(area) {
  if (area < 16) return false;
  return area <= 32;
}

function extract(scans) {
  if (!Array.isArray(scans)) throw new TypeError('scans must be an array');
  const counts = [];
  let total = 0;
  for (const scan of scans) {
    let valid = 0;
    for (const feature of scan) {
      checkPressure(feature.pressure);
      if (isMinutia(scanArea(feature.pixels))) valid += 1;
    }
    total += valid;
    if (total > MAX_TOTAL_MINUTIAE) throw new Error('minutiae capacity exceeded');
    counts.push(valid);
  }
  return counts;
}

function sectorHistogram(scan) {
  const sectorWidth = 256 / SECTOR_COUNT;
  const histogram = new Array(SECTOR_COUNT).fill(0);
  for (const feature of scan) {
    if (!isMinutia(scanArea(feature.pixels))) continue;
    histogram[Math.floor(ridgeAngle(feature.rawAngle) / sectorWidth)] += 1;
  }
  return histogram;
}

function packTemplates(counts) {
  const buffer = new Uint8Array(BUFFER_BYTES);
  let offset = 0;
  for (const count of counts) {
    if (offset + TEMPLATE_BYTES > buffer.length) throw new Error('secure matching buffer overflow');
    buffer[offset] = (count >> 8) & 255;
    buffer[offset + 1] = count & 255;
    offset += TEMPLATE_BYTES;
  }
  return { buffer, used: offset };
}

const scans = [
  [
    { pixels: new Array(20).fill(210), pressure: 96, rawAngle: 300 },
    { pixels: new Array(9).fill(180), pressure: 80, rawAngle: 45 },
    { pixels: new Array(40).fill(240), pressure: 70, rawAngle: 500 },
  ],
