const REPULSION_RANGE = 16;
const ATTRACTION_CUTOFF = 32;
const UNSTABLE_ENERGY = 128;

const SPACE_EDGE = Math.cbrt(SPACE_VOLUME_CAP);
const CELLS_PER_AXIS = Math.round(Math.cbrt(GRID_CELLS));

function clampAxis(value) {
  return Math.min(Math.max(value, 0), SPACE_EDGE);
}

function wrapSpecies(species) {
  const raw = Math.trunc(species) % SPECIES_MODULUS;
  return raw < 0 ? raw + SPECIES_MODULUS : raw;
}

function normalizeParticle(state, index) {
  if (!Array.isArray(state) || state.length < 6) {
    throw new TypeError(`particle ${index} must be [x, y, z, charge, species, energy]`);
  }
  const [x, y, z, charge, species, energy] = state.map(Number);
  if ([x, y, z, charge, species, energy].some((v) => !Number.isFinite(v))) {
    throw new RangeError(`particle ${index} holds a non-finite component`);
  }
  return {
    index,
    x: clampAxis(x),
    y: clampAxis(y),
    z: clampAxis(z),
    charge: Math.sign(charge || 1) * Math.min(Math.abs(charge), MAX_CHARGE),
    species: wrapSpecies(species),
    energy,
    unstable: energy > UNSTABLE_ENERGY,
  };
}

function cellOf(particle) {
  const axisIndex = (coord) =>
    Math.min(Math.floor((coord / SPACE_EDGE) * CELLS_PER_AXIS), CELLS_PER_AXIS - 1);
  const cx = axisIndex(particle.x);
  const cy = axisIndex(particle.y);
  const cz = axisIndex(particle.z);
  return cx + CELLS_PER_AXIS * (cy + CELLS_PER_AXIS * cz);
}

function distance(a, b) {
  return Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
}

function pairForce(a, b) {
  const d = distance(a, b);
  if (d === 0 || d > ATTRACTION_CUTOFF) return 0;
  const coupling = (a.charge * b.charge) / MAX_CHARGE;
  if (d < REPULSION_RANGE) {
    return (REPULSION_RANGE - d) * Math.abs(coupling) + 1;
  }
  const affinity = 1 - Math.abs(a.species - b.species) / SPECIES_MODULUS;
  const falloff = (ATTRACTION_CUTOFF - d) / ATTRACTION_CUTOFF;
  return -coupling * affinity * falloff;
}

function track(particles) {
  if (!Array.isArray(particles)) {
    throw new TypeError('track expects an array of particle state arrays');
  }
  const cloud = particles.map(normalizeParticle);
  const buckets = new Map();
  for (const p of cloud) {
    const cell = cellOf(p);
    if (!buckets.has(cell)) buckets.set(cell, []);
    buckets.get(cell).push(p);
  }
  const forces = [];
  for (const members of buckets.values()) {
    for (let i = 0; i < members.length; i += 1) {
      for (let j = i + 1; j < members.length; j += 1) {
        if (forces.length >= MAX_INTERACTIONS) return forces;
        const f = pairForce(members[i], members[j]);
        if (f === 0) continue;
        const heat = members[i].unstable || members[j].unstable ? 1.5 : 1;
        forces.push(Number((f * heat).toFixed(6)));
      }
    }
  }
  return forces;
}

module.exports = { track, pairForce, cellOf, normalizeParticle, wrapSpecies };

