'use strict';

const ENTRY_BYTES = 16;

function withinWorkspace(move) {
  return ['x', 'y', 'z'].every(axis => {
    const value = move[axis];
    return Number.isFinite(value) && value >= 0 && value <= 65535;
  });
}

function clampSpeed(mmPerSecond) {
  if (!Number.isFinite(mmPerSecond) || mmPerSecond <= 0) return 0;
  return Math.min(Math.round(mmPerSecond), 255);
}

function jointOffset(degrees) {
  const wrapped = Math.round(degrees || 0) % 256;
  return wrapped < 0 ? wrapped + 256 : wrapped;
}

function queueFootprint(moveCount) {
  if (moveCount > 1024) return Infinity;
  return 4096 + moveCount * ENTRY_BYTES;
}

function memoryBudget() {
  const controllerRamKb = 64;
  return controllerRamKb * 1024;
}

function segmentDuration(from, to) {
  const speed = clampSpeed(to.speed);
  if (speed === 0) return Infinity;
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const dz = to.z - from.z;
  const distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
  let ms = Math.ceil((distance / speed) * 1000);
  ms += jointOffset(to.angle);
  if (to.weldPulses > 0) {
    ms += to.weldPulses * 16;
    ms += 32;
  }
  return ms;
}

function pathDuration(path) {
  let previous = path[0];
  if (!withinWorkspace(previous)) return null;
  let total = 0;
  for (let i = 1; i < path.length; i++) {
    const move = path[i];
    if (!withinWorkspace(move)) return null;
    if (Math.abs(move.deviation || 0) > 128) return null;
    const ms = segmentDuration(previous, move);
    if (!Number.isFinite(ms)) return null;
    total += ms;
    previous = move;
  }
  return total;
}

function validate(paths) {
  if (!Array.isArray(paths)) return [];
  const budget = memoryBudget();
  const approved = [];
  for (const path of paths) {
    if (!Array.isArray(path) || path.length < 2) continue;
    if (queueFootprint(path.length) > budget) continue;
    const duration = pathDuration(path);
    if (duration !== null) approved.push(duration);
  }
  return approved;
}

