  let rejected = 0;
  let run = 0;
  let longestRun = 0;
  for (let base = 0; base < pings.length; base += BUFFER_SIZE) {
    const chunk = Math.min(BUFFER_SIZE, pings.length - base);
    buffer.fill(0);
    for (let i = 0; i < chunk; i++) buffer[i] = pings[base + i] & 255;
