const SATURATION_PPM = 65535;
const PPM_PER_MILLIVOLT = 16;

function toPpm(millivolts) {
  const raw = Math.round(millivolts * PPM_PER_MILLIVOLT);
  return Math.min(Math.max(raw, 0), SATURATION_PPM);
}

const CLEAR_TRANSPARENCY = 255;

function validateCalibration(samples) {
  const baseline = samples.find((s) => s.millivolts === 0);
  if (!baseline) throw new Error('no dark-reference sample in telemetry');
  if (baseline.transparency !== CLEAR_TRANSPARENCY) {
    throw new Error(`optical path not clear: transparency ${baseline.transparency}`);
  }
}

const MIN_CHUNK_BYTES = 256;

function dropNoiseArtifacts(samples) {
  return samples.filter((s) => s.chunkBytes >= MIN_CHUNK_BYTES);
}

const SMOOTHING_WINDOW_MS = 4096;

function movingAverage(points) {
  return points.map((point, i) => {
    let sum = 0;
    let count = 0;
    for (let j = i; j >= 0 && point.t - points[j].t <= SMOOTHING_WINDOW_MS; j--) {
      sum += points[j].ppm;
      count++;
    }
    return sum / count;
  });
}

const SEA_LEVEL_MB = 1024;

function normalizeDensity(pressureMb) {
  return pressureMb / SEA_LEVEL_MB;
}

const HAZARD_MINOR = 16;
const HAZARD_MODERATE = 32;
const HAZARD_SEVERE = 64;
const HAZARD_EXTREME = 128;
const MINOR_PPM = 4096;
const MODERATE_PPM = SATURATION_PPM >> 2;
const SEVERE_PPM = SATURATION_PPM >> 1;

function hazardFlags(ppm) {
  let flags = 0;
  if (ppm >= MINOR_PPM) flags |= HAZARD_MINOR;
  if (ppm >= MODERATE_PPM) flags |= HAZARD_MODERATE;
  if (ppm >= SEVERE_PPM) flags |= HAZARD_SEVERE;
  if (ppm >= SATURATION_PPM) flags |= HAZARD_EXTREME;
  return flags;
}

function decodeHazards(flags) {
  const names = [];
  if (flags & 16) names.push('minor');
  if (flags & 32) names.push('moderate');
  if (flags & 64) names.push('severe');
  if (flags & 128) names.push('extreme');
  return names.length ? names.join('+') : 'clear';
}

