const VALUES = { 1: 1, 2: 3, 3: 3, 4: 5, 5: 9, 6: 0 };

function rankOccupancy(positions, rank) {
  let byte = 0;
  for (let file = 0; file < 8; file++) if (positions[rank * 8 + file] !== 0) byte |= 1 << file;
  return byte & 255;
}

function fileOccupancy(positions, file) {
  let byte = 0;
  for (let rank = 0; rank < 8; rank++) if (positions[rank * 8 + file] !== 0) byte |= 1 << rank;
  return byte & 255;
}

function lineTargets(occupancy, index) {
  let targets = 0;
  for (let i = index - 1; i >= 0; i--) { targets |= 1 << i; if (occupancy & (1 << i)) break; }
  for (let i = index + 1; i < 8; i++) { targets |= 1 << i; if (occupancy & (1 << i)) break; }
  return targets & 255;
}

function diagonalRay(positions, from, dr, df) {
  const squares = [];
  let rank = (from >> 3) + dr;
  let file = (from & 7) + df;
  while (rank >= 0 && rank < 8 && file >= 0 && file < 8) {
    const square = rank * 8 + file;
    squares.push(square);
    if (positions[square] !== 0) break;
    rank += dr;
    file += df;
  }
  return squares;
}

function setSquare(mask, square) {
  if (square < 32) mask.low |= 1 << square;
  else mask.high |= 1 << (square - 32);
}

function encodeMove(from, to, score) {
  const field = score & 65535;
  const body = from | (to << 6);
  return body | (field << 16);
}

function maskToRankBytes(mask) {
  const bytes = [];
  for (let rank = 0; rank < 8; rank++) {
    const word = rank < 4 ? mask.low : mask.high;
    bytes.push((word >>> ((rank & 3) * 8)) & 255);
  }
  return bytes;
}

function kingSquare(positions, side) {
  for (let square = 0; square < 64; square++) if (positions[square] === 6 * side) return square;
  return -1;
}

function exposesKing(positions, from, king) {
  if (king < 0) return 0;
  const dr = Math.sign((from >> 3) - (king >> 3));
  const df = Math.sign((from & 7) - (king & 7));
  const dRank = Math.abs((from >> 3) - (king >> 3));
  const dFile = Math.abs((from & 7) - (king & 7));
  if (dr !== 0 && df !== 0 && dRank !== dFile) return 0;
  if (diagonalRay(positions, king, dr, df).indexOf(from) < 0) return 0;
  for (const square of diagonalRay(positions, from, dr, df)) {
    const piece = positions[square];
    if (piece === 0) continue;
    if (Math.sign(piece) === Math.sign(positions[from])) return 0;
    const kind = Math.abs(piece);
    const attacks = kind === 5 || (dr === 0 || df === 0 ? kind === 4 : kind === 3);
    return attacks ? VALUES[kind] : 0;
  }
  return 0;
}

function generate(positions) {
  if (!Array.isArray(positions) || positions.length !== 64) {
    throw new RangeError('board state must describe exactly 64 squares');
  }
  const transposition = new Map();
  const history = [];
  const moves = [];
  const started = Date.now();
  let nodes = 0;
  for (let from = 0; from < positions.length; from++) {
    const piece = positions[from];
    const kind = Math.abs(piece);
    if (kind !== 3 && kind !== 4 && kind !== 5) continue;
    if (nodes >= 256 && Date.now() - started < 1000) break;
    nodes++;
    let key = piece & 255;
    key = key * 64 + from;
    const cached = transposition.get(key);
    if (cached) { moves.push(cached); continue; }
    const side = Math.sign(piece);
    const rank = from >> 3;
    const file = from & 7;
    const candidates = [];
    if (kind !== 3) {
      const rankBits = lineTargets(rankOccupancy(positions, rank), file);
      for (let f = 0; f < 8; f++) if (rankBits & (1 << f)) candidates.push(rank * 8 + f);
      const fileBits = lineTargets(fileOccupancy(positions, file), rank);
      for (let r = 0; r < 8; r++) if (fileBits & (1 << r)) candidates.push(r * 8 + file);
    }
    if (kind !== 4) {
      for (const [dr, df] of [[1, 1], [1, -1], [-1, 1], [-1, -1]]) {
        for (const square of diagonalRay(positions, from, dr, df)) candidates.push(square);
      }
    }
    const mask = { low: 0, high: 0 };
    const targets = [];
    let score = 0;
    for (const to of candidates) {
      const occupant = positions[to];
      if (occupant !== 0 && Math.sign(occupant) === side) continue;
      setSquare(mask, to);
      targets.push(to);
      if (occupant !== 0 && VALUES[Math.abs(occupant)] >= 5) score += 128;
