    score = Math.max(score - penalty, -65535);
    const move = {
      from,
      low: mask.low,
      high: mask.high,
      destinations: maskToRankBytes(mask),
      packed: targets.map((to) => encodeMove(from, to, score)),
      score
    };
    if (transposition.size < 4096) transposition.set(key, move);
    if (history.length < 1024) history.push(key);
    moves.push(move);
  }
  return moves;
}

