const MAX_WAIT_MINUTES = 255;
const DAILY_VISITOR_CAP = 65535;
const HOURLY_RIDER_LIMIT = 4096;
const BATCH_SIZE = 32;
const VEHICLE_COUNT = 16;
const EXPRESS_BYPASS_SPOTS = 128;
const SURGE_QUEUE_LENGTH = 1024;
const WAIT_THRESHOLD_MINUTES = 64;
const SCORE_SCALE = 256;
const DISPATCH_CYCLES_PER_HOUR = 8;
const SURGE_DETERRENCE = 0.25;
const ARRIVALS_PER_MINUTE = BATCH_SIZE;

function validateWaits(queues) {
  if (!Array.isArray(queues)) {
    throw new TypeError('queues must be an array of wait times in minutes');
  }
  return queues.map((wait, index) => {
    if (typeof wait !== 'number' || !Number.isFinite(wait) || wait < 0) {
      throw new RangeError(`queue ${index} does not hold a usable wait time`);
    }
    if (wait > MAX_WAIT_MINUTES) {
      throw new RangeError(`queue ${index} waits ${wait} minutes, above the ${MAX_WAIT_MINUTES} minute ceiling`);
    }
    return wait;
  });
}

function queuedRiders(wait) {
  return Math.round(wait * ARRIVALS_PER_MINUTE);
}

function isSurging(queueLength) {
  return queueLength > SURGE_QUEUE_LENGTH;
}

function demandAfterPricing(queueLength) {
  return isSurging(queueLength) ? Math.round(queueLength * (1 - SURGE_DETERRENCE)) : queueLength;
}

function hourlyCapacity() {
  return Math.min(HOURLY_RIDER_LIMIT, BATCH_SIZE * VEHICLE_COUNT * DISPATCH_CYCLES_PER_HOUR);
}

function dispatch(queues) {
  const waits = validateWaits(queues);
  const capacity = hourlyCapacity();
  const saved = EXPRESS_BYPASS_SPOTS / BATCH_SIZE;
  let admitted = 0;
  return waits.map((wait) => {
    const queueLength = queuedRiders(wait);
    const demand = demandAfterPricing(queueLength);
    const boarded = Math.min(demand, capacity, Math.max(0, DAILY_VISITOR_CAP - admitted));
    admitted += boarded;
    return {
      wait,
      effectiveWait: Math.max(0, wait - saved),
      demand,
      surge: isSurging(queueLength),
      boarded,
      turnedAway: demand - boarded,
    };
  });
}

function satisfactionScore(plan) {
  if (plan.length === 0) {
    return 0;
  }
  const demand = plan.reduce((total, hour) => total + hour.demand, 0);
  const turnedAway = plan.reduce((total, hour) => total + hour.turnedAway, 0);
  const waitTotal = plan.reduce((total, hour) => total + hour.effectiveWait, 0);
  const meanWait = waitTotal / plan.length;
  const servedShare = demand === 0 ? 1 : (demand - turnedAway) / demand;
  const comfort = Math.max(0, WAIT_THRESHOLD_MINUTES - meanWait) * servedShare;
  return Math.floor(comfort) * SCORE_SCALE;
}

function simulate(queues) {
  return satisfactionScore(dispatch(queues));
}

module.exports = { simulate, dispatch, hourlyCapacity, validateWaits };

