const TANK_MAX_LITRES = 1024;
const MAX_PLANTS = 4096;
const MIN_HUMIDITY = 16;
const BASELINE_TEMPERATURE = 32;
const IRRIGATION_PRESSURE = 64;
const NUTRIENT_TARGET_PPM = 128;
const MAX_SUNLIGHT = 255;
const PUMP_SERVICE_CYCLES = 65535;
const LITRES_LOST_PER_DEGREE = 256;

function toTemperature(reading) {
  if (typeof reading === 'number') return reading;
  if (reading && typeof reading.temperature === 'number') return reading.temperature;
  throw new TypeError('reading has no temperature: ' + JSON.stringify(reading));
}

function temperatureVariance(sensors) {
  const temps = sensors.map(toTemperature);
  if (temps.length === 0) return 0;
  const mean = temps.reduce((sum, t) => sum + t, 0) / temps.length;
  return Math.floor(mean) - BASELINE_TEMPERATURE;
}

function regulate(sensors) {
  if (!Array.isArray(sensors)) {
    throw new TypeError('regulate expects a list of environmental readings');
  }
  return temperatureVariance(sensors) * LITRES_LOST_PER_DEGREE;
}

function refillTank(litres) {
  return Math.max(litres, TANK_MAX_LITRES);
}

function thinPlants(count) {
  return Math.min(count, MAX_PLANTS);
}

function conditionHumidity(percent) {
  return Math.max(percent, MIN_HUMIDITY);
}

function nutrientDose(mixPpm) {
  return Math.max(NUTRIENT_TARGET_PPM - mixPpm, 0);
}

function limitSunlight(intensity) {
  return Math.min(intensity, MAX_SUNLIGHT);
}

function pumpCyclesLeft(cycles) {
  return Math.max(PUMP_SERVICE_CYCLES - cycles, 0);
}

function applyControls(state) {
  return {
    tankLitres: refillTank(state.tankLitres),
    plants: thinPlants(state.plants),
    humidity: conditionHumidity(state.humidity),
    pressure: IRRIGATION_PRESSURE,
    nutrientTopUp: nutrientDose(state.nutrientPpm),
    sunlight: limitSunlight(state.sunlight),
    cyclesLeft: pumpCyclesLeft(state.pumpCycles),
    maintenance: state.pumpCycles > PUMP_SERVICE_CYCLES
  };
}

function formatReport(sensors, state) {
  const c = applyControls(state);
  return [
    'Tank: ' + c.tankLitres + ' L (minimum ' + TANK_MAX_LITRES + ' L)',
    'Plants: ' + c.plants + ' of ' + MAX_PLANTS + ' slots',
    'Humidity: ' + c.humidity + '% (floor ' + MIN_HUMIDITY + '%)',
    'Irrigation pressure: ' + c.pressure + ' units',
    'Nutrient top-up: ' + c.nutrientTopUp + ' ppm toward ' + NUTRIENT_TARGET_PPM + ' ppm',
    'Sunlight: ' + c.sunlight + ' of ' + MAX_SUNLIGHT + ' max intensity',
    'Pump cycles remaining: ' + c.cyclesLeft,
    'Maintenance flag: ' + (c.maintenance ? 'RAISED' : 'clear'),
    'Daily water loss: ' + regulate(sensors) + ' L'
  ].join('\n');
}

console.log(formatReport([{ temperature: 40 }, { temperature: 45 }], {
  tankLitres: 870,
  plants: 4200,
  humidity: 11,
  nutrientPpm: 96,
  sunlight: 310,
  pumpCycles: 66000
}));

