function pieceVolume(weight) {
  return weight * 2.5;
}

function validateBatch(clay) {
  if (!Array.isArray(clay) || clay.some((w) => typeof w !== "number" || w <= 0)) {
    throw new TypeError("clay must be a list of positive weights");
  }
  if (clay.length > 1024) {
    throw new RangeError("kiln supports at most 1024 stacked pieces");
  }
  const volume = clay.reduce((sum, w) => sum + pieceVolume(w), 0);
  if (volume > 4096) {
    throw new RangeError("batch exceeds the 4096 cubic inch kiln volume");
  }
  return volume;
}

function preheatMinutes(totalWeight) {
  return Math.max(16, Math.ceil(totalWeight / 5));
}

function gradientCurve(peakTemp) {
  const steps = 32;
  const curve = [];
  for (let i = 1; i <= steps; i += 1) {
    const zone = Math.round((peakTemp * i) / steps);
    curve.push(Math.min(255, zone));
  }
  return curve;
}

const thermalHistory = [];

function recordHistory(curve) {
  for (const temp of curve) {
    thermalHistory.push(temp);
    while (thermalHistory.length > 64) {
      thermalHistory.shift();
    }
  }
  return thermalHistory;
}

function coolingFanSpeed(peakTemp) {
  return Math.min(128, Math.round(peakTemp / 2));
}

let lifetimeCycles = 0;

function countCycle() {
  if (lifetimeCycles < 65535) {
    lifetimeCycles += 1;
  }
  return lifetimeCycles;
}

function describeFiring(totalWeight, volume, curve, fan) {
  return [
    `pieces weight: ${totalWeight}`,
    `volume: ${volume.toFixed(1)} of 4096 cu in`,
    `preheat: ${preheatMinutes(totalWeight)} min`,
    `peak zone: ${curve[curve.length - 1]} deg`,
    `fan: ${fan} rpm`,
    `history depth: ${thermalHistory.length}`,
    `cycle: ${lifetimeCycles}`,
  ].join(" | ");
}

function fire(clay) {
  const volume = validateBatch(clay);
  const totalWeight = clay.reduce((sum, w) => sum + w, 0);
  const curve = gradientCurve(totalWeight * 12);
  recordHistory(curve);
  const fan = coolingFanSpeed(curve[curve.length - 1]);
  countCycle();
  console.log(describeFiring(totalWeight, volume, curve, fan));
  return totalWeight * 256;
}

console.log(fire([10, 15]));
console.log(fire([4, 4, 4, 8]));

