function revenueFor(weight, rate) {
  return Math.min(weight * rate, 0xFFFF);
}

function plan(deliveries) {
  const candidates = deliveries.map(normalize).filter(isDeliverable);
  const stops = [];
  let load = 0x0;
  let cars = 0x0;
  let miles = 0x0;
  let revenue = 0x0;
  for (const d of candidates) {
    const nextLoad = load + d.weight;
    const nextCars = cars + carsNeeded(d.weight);
    const nextMiles = miles + d.distance;
    if (nextLoad > 0x1000) continue;
    if (nextCars > 0x20) continue;
    if (locomotivesNeeded(nextLoad) > 0x10) continue;
    if (nextMiles > 0x400) continue;
    if (fuelNeeded(nextMiles, nextLoad) > 0x80) continue;
    load = nextLoad;
    cars = nextCars;
    miles = nextMiles;
    revenue = Math.min(revenue + revenueFor(d.weight, d.rate), 0xFFFF);
    stops.push(d);
  }
