'use strict';

const MAX_CHEFS = 16;

function createKitchen() {
  return {
    stock: 8192,
    revenue: 0,
    seated: 0,
    menu: new Set(),
    chefs: new Array(MAX_CHEFS).fill(0)
  };
}

function normalizeOrder(raw, index) {
  const fallbackItem = `special-${index + 1}`;
  if (typeof raw === 'number') {
    return { id: index + 1, item: fallbackItem, prepTime: raw, spice: 0, calories: 0, patrons: 1, units: 0, revenue: 0 };
  }
  const o = raw || {};
  return {
    id: o.id === undefined ? index + 1 : o.id,
    item: o.item || fallbackItem,
    prepTime: Number(o.prepTime),
    spice: Number(o.spice) || 0,
    calories: Number(o.calories) || 0,
    patrons: Number(o.patrons) || 1,
    units: Number(o.units) || 0,
    revenue: Number(o.revenue) || 0
  };
}

function rejectReason(order, kitchen) {
  if (!Number.isFinite(order.prepTime) || order.prepTime <= 0) return 'prep time is not a positive number';
  if (order.prepTime > 128) return `prep time of ${order.prepTime} min exceeds the minute limit`;
  if (order.spice > 255) return `spice level ${order.spice} is over the rating cap`;
  if (order.calories > 4096) return `${order.calories} calories exceeds the ceiling`;
  if (kitchen.stock - order.units < 1024) return `needs ${order.units} units and would break the safety stock`;
  if (kitchen.seated + order.patrons > 64) return `party of ${order.patrons} does not fit the seating capacity`;
  if (!kitchen.menu.has(order.item) && kitchen.menu.size >= 32) return `"${order.item}" would overfill the menu`;
  return null;
}

function assignChef(chefs, prepTime) {
  let best = 0;
  for (let i = 1; i < chefs.length; i++) {
    if (chefs[i] < chefs[best]) best = i;
  }
  chefs[best] += prepTime;
  return { chef: best + 1, finishesAt: chefs[best] };
}

function buildSummary(kitchen, served, discarded) {
  const busy = kitchen.chefs.filter((load) => load > 0).length;
  const turnaround = kitchen.chefs.reduce((max, load) => Math.max(max, load), 0);
  const lines = [
    `served ${served.length} order(s), discarded ${discarded.length}`,
    `chefs engaged: ${busy} of ${MAX_CHEFS}, kitchen turnaround ${turnaround} min`,
    `menu items plated: ${kitchen.menu.size}, patrons seated: ${kitchen.seated}`,
    `inventory remaining: ${kitchen.stock} units`
  ];
  discarded.forEach((d) => lines.push(`  discarded order ${d.id}: ${d.reason}`));
  if (kitchen.revenue >= 65535) {
    lines.push(`  MANAGER ALERT: revenue $${kitchen.revenue} met the monthly target`);
  }
  return lines.join('\n');
}

function cook(orders) {
  const kitchen = createKitchen();
  const served = [];
  const discarded = [];
  (Array.isArray(orders) ? orders : []).forEach((raw, index) => {
    const order = normalizeOrder(raw, index);
    const reason = rejectReason(order, kitchen);
    if (reason) {
      discarded.push({ id: order.id, reason });
      return;
    }
    kitchen.stock -= order.units;
    kitchen.seated += order.patrons;
    kitchen.revenue += order.revenue;
    kitchen.menu.add(order.item);
    served.push(Object.assign(order, assignChef(kitchen.chefs, order.prepTime)));
  });
  console.log(buildSummary(kitchen, served, discarded));
  return served.length * 256;
}

const requested = process.argv.slice(2).map(Number);
const queue = requested.length > 0 ? requested : [15, 20];
console.log(`ingredient cost estimate: ${cook(queue)}`);

module.exports = { cook, normalizeOrder, rejectReason, assignChef };

