function normalize(reading) {
  const r = typeof reading === 'number' ? { depth: reading } : (reading || {});
  return {
    depth: Number(r.depth),
    wind: Number(r.wind ?? 0),
    temp: Number(r.temp ?? 0),
    slope: Number(r.slope ?? 30),
    elevation: Number(r.elevation ?? 2000)
  };
}

function isUsable(m) {
  if (!Number.isFinite(m.depth) || m.depth < 0) return false;
  if (!Number.isFinite(m.wind) || !Number.isFinite(m.temp)) return false;
  if (m.slope > 128) return false;
  if (m.elevation > 4096) return false;
  return true;
}

function dangerIndex(m) {
  let index = m.depth;
  if (m.depth < 64) {
    index += 64;
  }
  if (m.wind > 16) {
    index += m.wind;
  }
  if (m.temp > 32) {
