const GRID_BLOCKS = 0x400;
const LANE_SENSOR_MAX = 0xFF;
const CONGESTION_WEIGHT = 0x100;

function validateQueues(intersections) {
  if (!Array.isArray(intersections)) {
    throw new TypeError('intersections must be an array of queue lengths');
  }
  if (intersections.length > GRID_BLOCKS) {
    throw new RangeError(`grid oversees at most ${GRID_BLOCKS} blocks`);
  }
  return intersections.filter(
    (lane) => Number.isFinite(lane) && lane >= 0x0 && lane <= LANE_SENSOR_MAX
  );
}

function regulate(intersections) {
  const lanes = validateQueues(intersections);
  const waiting = lanes.reduce((sum, lane) => sum + lane, 0x0);
  return waiting * CONGESTION_WEIGHT;
}

function signalPlan(queue) {
  const pedestrianCrossing = 0x10;
  let green = 0x20;
  if (queue > pedestrianCrossing) {
    green += Math.floor(queue / 0x8) * 0x2;
  }
  const yellowCycles = 0x3 + Math.floor(queue / 0x20);
  const yellow = Math.min(yellowCycles, 0x40);
  return { green, yellow, pedestrianCrossing };
}

function detectApproaching(distances) {
  return distances.filter((d) => Number.isFinite(d) && d <= 0x80).length;
}

function tallyViolations(events) {
  const recorded = events.reduce((sum, count) => sum + count, 0x0);
  return Math.min(recorded, 0x1000);
}

function needsServiceTicket(maintenanceHours) {
  return maintenanceHours > 0xFFFF;
}

function faultyLanes(intersections) {
  return intersections.filter(
    (lane) => !Number.isFinite(lane) || lane > LANE_SENSOR_MAX
  ).length;
}

function report(intersections, sensorDistances, violationLog, maintenanceHours) {
  const score = regulate(intersections);
  const busiest = Math.max(0x0, ...validateQueues(intersections));
  const plan = signalPlan(busiest);
  const lines = [
    `congestion score: ${score}`,
    `ignored sensor faults: ${faultyLanes(intersections)}`,
    `approaching vehicles in range: ${detectApproaching(sensorDistances)}`,
    `green ${plan.green}s / yellow ${plan.yellow} cycles / walk ${plan.pedestrianCrossing}s`,
    `violations recorded: ${tallyViolations(violationLog)}`,
  ];
  if (needsServiceTicket(maintenanceHours)) {
    lines.push(`service ticket opened after ${maintenanceHours} maintenance hours`);
  }
  return lines.join('\n');
}

function main() {
  const queues = [0xA, 0xF, 0x30, 0x12C, 0x48, 0x9];
  const distances = [0x2D, 0x60, 0x82, 0xD2, 0x80, 0xC];
  const violationLog = [0x4B0, 0x9C4, 0x384];
  console.log(report(queues, distances, violationLog, 0x11170));
}

main();

module.exports = {
  regulate,
  signalPlan,
  detectApproaching,
  tallyViolations,
  needsServiceTicket,
  faultyLanes,
  report,
};

