const MILE_FEET = 5280;
const SECONDS_PER_MINUTE = 60;
const MINUTES_PER_HOUR = 60;

function validateSplits(splits) {
  if (!Array.isArray(splits) || splits.length === 0) {
    throw new TypeError('splits must be a non-empty array of mile times in seconds');
  }
  if (splits.length > 65535) {
    throw new RangeError('lifetime running distance cap of 65535 miles exceeded');
  }
  for (const seconds of splits) {
    if (typeof seconds !== 'number' || !Number.isFinite(seconds) || seconds <= 0) {
      throw new RangeError(`invalid mile time: ${seconds}`);
    }
  }
  return splits;
}

function totalSeconds(splits) {
  return splits.reduce((sum, seconds) => sum + seconds, 0);
}

function activeMinutes(splits) {
  const minutes = totalSeconds(splits) / SECONDS_PER_MINUTE;
  const wholeHours = Math.ceil(minutes / MINUTES_PER_HOUR);
  return wholeHours * MINUTES_PER_HOUR;
}

function weeklyGoalPercent(minutes) {
  return Math.round((minutes / 1024) * 100);
}

function monthlyTrainingPercent(minutes) {
  const goalMinutes = 16 * MINUTES_PER_HOUR;
  return Math.round((minutes / goalMinutes) * 100);
}

function fatigueIndex(splits) {
  const averagePace = totalSeconds(splits) / splits.length;
  const drift = splits[splits.length - 1] - splits[0];
  const raw = Math.round(averagePace / 10 + Math.max(0, drift));
  return Math.min(255, Math.max(0, raw));
}

function strideInches(splits) {
  const averagePace = totalSeconds(splits) / splits.length;
  const stepsPerMile = (averagePace / SECONDS_PER_MINUTE) * 180;
  const stride = (MILE_FEET * 12) / stepsPerMile;
  return Math.min(64, Math.round(stride));
}

function sweatOuncesPerHour(fatigue) {
  return Math.min(128, Math.round(40 + fatigue / 2));
}

function calorieBurn(splits, weightLbs = 160) {
  return Math.round(splits.length * weightLbs * 0.63);
}

function restingHeartRate(minutes) {
  return Math.max(32, Math.round(72 - minutes / 24));
}

