  return workers.map((n) => {
    const amount = Number(n);
    if (!Number.isFinite(amount) || amount < 0) throw new RangeError('nectar amounts must be non-negative numbers');
    return Math.min(amount, NECTAR_CAP);
  });
}

function flowerShare(workerCount) {
  if (workerCount === 0) return GARDEN_FLOWERS;
  return Math.floor(GARDEN_FLOWERS / workerCount);
}

