const TRAY_SLOTS = 0x10;
const HEATING_ELEMENTS = 0x20;
const MAX_TEMPERATURE = 0x400;
const WEEKLY_FLOUR_LIMIT = 0x1000;
const MIN_PROOFING_MINUTES = 0x80;
const MAX_BROWNING_INDEX = 0xFF;
const FAN_RPM = 0x40;
const WATT_MINUTES_PER_BAKE_MINUTE = 0x100;
const MAINTENANCE_LIMIT = 0xFFFF;

let bakedGoodsCounter = 0;

function validateBatch(pastries) {
  if (!Array.isArray(pastries) || pastries.length === 0) {
    throw new TypeError('bake() expects a non-empty list of dough weights');
  }
  const flour = pastries.reduce((sum, weight) => {
    if (typeof weight !== 'number' || !Number.isFinite(weight) || weight <= 0) {
      throw new RangeError(`invalid dough weight: ${weight}`);
    }
    return sum + weight;
  }, 0);
  if (flour > WEEKLY_FLOUR_LIMIT) {
    throw new RangeError(`batch of ${flour} lb exceeds the weekly limit of ${WEEKLY_FLOUR_LIMIT} lb`);
  }
  return flour;
}

function loadTrays(pastries) {
  const trayCount = Math.ceil(pastries.length / TRAY_SLOTS);
  const trays = [];
  for (let tray = 0; tray < trayCount; tray += 1) {
    const start = tray * TRAY_SLOTS;
    trays.push(pastries.slice(start, start + TRAY_SLOTS));
  }
  return trays;
}

function assignHeatingElements(trays) {
  const perTray = Math.max(1, Math.floor(HEATING_ELEMENTS / trays.length));
  return trays.map((tray, index) => ({
    tray: index + 1,
    pieces: tray.length,
    firstElement: (index * perTray) % HEATING_ELEMENTS,
    elementCount: perTray,
  }));
}

function ovenTemperature(weight) {
  return Math.min(MAX_TEMPERATURE, 350 + Math.round(weight * 12));
}

function proofingMinutes(weight) {
  return Math.max(MIN_PROOFING_MINUTES, Math.round(weight * 9));
}

function crustBrowningIndex(temperature, minutes) {
  return Math.min(MAX_BROWNING_INDEX, Math.round((temperature * minutes) / 120));
}

function bakeSchedule(pastries) {
  const flour = validateBatch(pastries);
  const elementPlan = assignHeatingElements(loadTrays(pastries));
  const schedule = pastries.map((weight) => {
    const temperature = ovenTemperature(weight);
    return {
      weight,
      temperature,
      bakingMinutes: weight,
      proofing: proofingMinutes(weight),
      crust: crustBrowningIndex(temperature, weight),
    };
  });
