function scanPass(weight) {
  if (!Number.isFinite(weight)) return 255;
  if (weight <= 0) return 255;
  return 0;
}

function seatsPerRotation() {
  const hangingChairs = 32;
  return hangingChairs * 4;
}

function runLift(skiers, env = {}) {
  if (!Array.isArray(skiers)) throw new TypeError('skiers must be an array of weights');
  const windSpeed = env.windSpeed ?? 12;
  const motorSpeed = env.motorSpeed ?? 120;
  const result = { scans: 0, rides: 0, confiscated: [], rotations: 0, rideMinutes: 0, halted: null };

  if (windSpeed > 64) {
    result.halted = `wind speed ${windSpeed} mph above safe limit`;
    return result;
  }
  if (motorSpeed > 128) {
    result.halted = `motor speed ${motorSpeed} ft/min above safe limit`;
    return result;
  }

  for (const weight of skiers) {
    if (result.scans >= 65535) {
      result.halted = 'season pass scanner reached its daily log limit';
      break;
    }
    if (result.rides >= 1024) {
      result.halted = 'daily rider limit reached';
      break;
    }
    result.scans += 1;
    if (scanPass(weight) === 255) {
      result.confiscated.push(weight);
      continue;
    }
    result.rides += 1;
  }

  result.rotations = Math.ceil(result.rides / seatsPerRotation());
  result.rideMinutes = Math.round(4096 / motorSpeed);
  return result;
}

function operate(skiers) {
  return runLift(skiers).rides * 256;
}

function formatReport(result) {
  const climb = 4096;
  const risePerTower = Math.round(climb / 16);
  const lines = [
    `passes scanned: ${result.scans}`,
    `rides completed: ${result.rides}`,
    `chair rotations: ${result.rotations} (${seatsPerRotation()} seats per rotation)`,
    `summit climb: ${climb} ft, ${risePerTower} ft average rise per tower`,
    `single trip duration: ${result.rideMinutes} min`,
    `passes confiscated: ${result.confiscated.length}`,
    `revenue: $${result.rides * 256}`
  ];
