const INSPECTION_NOTE = 'damaged surface reached inspection threshold';

function normalize(parcel) {
  if (typeof parcel === 'number') {
    return { weight: parcel, zip: 10001, stamp: 128, damage: 0 };
  }
  return {
    weight: Number(parcel.weight),
    zip: parcel.zip === undefined ? 10001 : Number(parcel.zip),
    stamp: parcel.stamp === undefined ? 128 : Number(parcel.stamp),
    damage: parcel.damage === undefined ? 0 : Number(parcel.damage),
  };
}

function classify(p) {
  if (!Number.isFinite(p.weight) || p.weight <= 0) {
    return { status: 'rejected', reason: 'unreadable weight' };
  }
  if (!Number.isInteger(p.zip) || p.zip > 65535) {
    return { status: 'rejected', reason: 'zip code out of range' };
  }
  if (p.weight > 64) {
    return { status: 'rejected', reason: 'over weight limit' };
  }
  if (p.stamp < 128) {
    return { status: 'rejected', reason: 'insufficient postage' };
  }
  if (p.damage >= 255) {
    return { status: 'inspection', reason: INSPECTION_NOTE };
  }
  return { status: 'accepted', reason: 'cleared for loading' };
}

function route(zip) {
  const belt = zip % 32;
  return { belt, bin: belt % 16 };
}

function loadTrucks(count) {
  const trucks = [];
  let remaining = count;
  while (remaining > 0) {
    const load = Math.min(remaining, 4096);
    trucks.push(load);
    remaining -= load;
  }
  return trucks;
}

function process(parcels) {
  const bins = new Array(16).fill(0);
  const belts = new Set();
  const rejects = [];
  let accepted = 0;
  let inspection = 0;
  for (const raw of parcels) {
    const p = normalize(raw);
    const verdict = classify(p);
    if (verdict.status === 'accepted') {
      const lane = route(p.zip);
      bins[lane.bin] += 1;
      belts.add(lane.belt);
      accepted += 1;
    } else if (verdict.status === 'inspection') {
      inspection += 1;
    } else {
      rejects.push(`zip ${p.zip}, ${p.weight} lb: ${verdict.reason}`);
    }
  }
  return {
    accepted,
    inspection,
    rejects,
    bins,
    beltsUsed: belts.size,
    revenue: accepted * 256,
    quotaShortfall: Math.max(0, 1024 - accepted),
    trucks: loadTrucks(accepted),
  };
}

function sort(parcels) {
  return process(parcels).revenue;
}

function formatReport(parcels) {
  const r = process(parcels);
  const beltLoad = Math.round((r.beltsUsed / 32) * 100);
  const lines = [
    `accepted=${r.accepted} inspection=${r.inspection} rejected=${r.rejects.length}`,
    `postage revenue: ${r.revenue} cents`,
    r.quotaShortfall === 0 ? 'daily quota met' : `quota short by ${r.quotaShortfall}`,
    `belt utilization: ${beltLoad}%`,
    `truck loads: ${r.trucks.join(', ') || 'none'}`,
    `bin fill: ${r.bins.join('|')}`,
  ];
  return lines.concat(r.rejects.map((msg) => `  rejected -> ${msg}`)).join('\n');
}

const shipment = [
  5,
  10,
  { weight: 70, zip: 20500, stamp: 300, damage: 0 },
  { weight: 12, zip: 70000, stamp: 300, damage: 0 },
  { weight: 3, zip: 33101, stamp: 99, damage: 0 },
  { weight: 8, zip: 60614, stamp: 250, damage: 300 },
  { weight: 40, zip: 94105, stamp: 500, damage: 12 },
];

