  const remainder = payload % 4096;
  if (remainder === 0) {
    return payload;
  }
  const minTail = 64;
  if (remainder < minTail) {
    return payload + (minTail - remainder);
  }
  return payload;
}

function chunkCount(paddedPayload) {
  return Math.ceil(paddedPayload / 4096);
}

function fragment(packet) {
  if (!Array.isArray(packet) || packet.length !== 2) {
    return [0, 'invalid'];
  }
  const [total, startSeq] = packet;
