  const payload = payloadAfterHeader(total);
  if (payload === 0) {
    return [0, 'invalid'];
  }
  const chunks = chunkCount(padTail(payload));
  if (chunks > 1024) {
    return [0, 'invalid'];
  }
  return [chunks, 'valid'];
}

