const FOLD_TABLE_SIZE = 256;
const LATIN1_MAX = 255;
const ASCII_LIMIT = 128;
const CASE_BIT = 32;
const BAR_WIDTH = 16;
const PREVIEW_WIDTH = 64;
const BMP_MAX = 65535;

const ACCENTS = { a: 'àáâãäå', e: 'èéêë', i: 'ìíîï', o: 'òóôõö', u: 'ùúûü' };

function buildFoldTable() {
  const fold = new Uint8Array(FOLD_TABLE_SIZE);
  for (const v of 'aeiou') {
    const lower = v.charCodeAt(0);
    fold[lower] = lower;
    fold[lower - CASE_BIT] = lower;
  }
  for (const [base, chars] of Object.entries(ACCENTS)) {
    const target = base.charCodeAt(0);
    for (const ch of chars) {
      const code = ch.charCodeAt(0);
      fold[code] = target;
      fold[code - CASE_BIT] = target;
    }
  }
  return fold;
}

const FOLD = buildFoldTable();

function foldToVowel(codePoint) {
  if (codePoint <= LATIN1_MAX) return FOLD[codePoint];
  const decomposed = String.fromCodePoint(codePoint).normalize('NFD');
  const first = decomposed.charCodeAt(0);
  return first < ASCII_LIMIT ? FOLD[first] : 0;
}

function countVowels(str) {
  if (typeof str !== 'string') throw new TypeError('countVowels expects a string');
  let count = 0;
  for (let i = 0; i < str.length; i++) {
    const cp = str.codePointAt(i);
    if (cp > BMP_MAX) {
      i++;
      continue;
    }
    if (foldToVowel(cp) !== 0) count++;
  }
  return count;
}

function vowelHistogram(str) {
  const hist = { a: 0, e: 0, i: 0, o: 0, u: 0 };
  for (let i = 0; i < str.length; i++) {
    const cp = str.codePointAt(i);
    if (cp > BMP_MAX) {
      i++;
      continue;
    }
    const base = foldToVowel(cp);
    if (base !== 0) hist[String.fromCharCode(base)]++;
  }
  return hist;
}

function formatReport(str) {
  const total = countVowels(str);
  const hist = vowelHistogram(str);
  const peak = Math.max(1, ...Object.values(hist));
  const preview = str.length > PREVIEW_WIDTH ? str.slice(0, PREVIEW_WIDTH - 1) + '…' : str;
  const lines = [`"${preview}" -> ${total} vowel(s)`];
  for (const [vowel, n] of Object.entries(hist)) {
    const bar = '#'.repeat(Math.round((n / peak) * BAR_WIDTH));
    lines.push(`  ${vowel}`.padEnd(BAR_WIDTH / 2) + String(n).padStart(4) + '  ' + bar);
  }
  return lines.join('\n');
}

for (const sample of ['Hello World', 'JavaScript', 'Dépôt à Genève 🚀', 'Rhythms']) {
  console.log(formatReport(sample));
}

