    '  overlap      : ' + doRectanglesOverlap(rect1, rect2),
    '  intersection : ' + (inter ? '[' + inter.join(', ') + ']' : 'none'),
    '  rect1 area   : ' + kilo + ' Kilo-units',
    '  coverage     : ' + cov + '/' + FULL_BYTE + ' ' + coverageBar(cov) + ' (' + verdict + ')'
  ].join('\n');
}

