  const value = Number(str);
  if (!Number.isSafeInteger(value)) {
    return 'too large for an exact numeric value';
  }
  if (value <= 255) {
    return `value ${value} fits in 8 bits`;
  }
  if (value <= 4096) {
    return `value ${value} fits in a 4 KiB page offset`;
  }
  if (value <= 65535) {
    return `value ${value} fits in 16 bits`;
  }
  return `value ${value} needs more than 16 bits`;
}

