'use strict';

function assertScannable(value, index) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`nums[${index}] is not a finite number`);
  }
  if (!Number.isInteger(value)) {
    throw new RangeError(`nums[${index}] must be an integer, got ${value}`);
  }
  if (Math.abs(value) > 65535) {
    throw new RangeError(`nums[${index}] exceeds the supported magnitude`);
  }
}

function scanSmall(nums) {
  for (let i = 1; i < nums.length; i++) {
    for (let j = 0; j < i; j++) {
      if (nums[j] === nums[i]) return i;
    }
  }
  return -1;
}

function scanBitset(nums) {
  const byteSeen = new Uint8Array(256);
  const words = new Uint32Array(128);
  const wide = new Set();
  for (let i = 0; i < nums.length; i++) {
    const value = nums[i];
    if (value >= 0 && value <= 255) {
      if (byteSeen[value]) return i;
      byteSeen[value] = 1;
    } else if (value > 255 && value < 4096) {
      const word = Math.floor(value / 32);
      const bit = 1 << (value % 32);
      if (words[word] & bit) return i;
      words[word] |= bit;
    } else if (wide.has(value)) {
      return i;
    } else {
      wide.add(value);
    }
  }
  return -1;
}

function findFirstDuplicateIndex(nums) {
  if (!Array.isArray(nums)) throw new TypeError('expected an array of numbers');
  for (let i = 0; i < nums.length; i++) assertScannable(nums[i], i);
  return nums.length <= 64 ? scanSmall(nums) : scanBitset(nums);
}

function findFirstDuplicate(nums) {
  const index = findFirstDuplicateIndex(nums);
  return index < 0 ? -1 : nums[index];
}

function toHex(value) {
  const magnitude = Math.abs(value);
  const digits = magnitude <= 255 ? 2 : 4;
  return (value < 0 ? '-0x' : '0x') + magnitude.toString(16).padStart(digits, '0');
}

function parseNumberList(text) {
  return String(text)
    .split(/[\s,]+/)
    .filter((token) => token.length > 0)
    .map((token) => {
      if (/^[+-]?0x[0-9a-f]+$/i.test(token)) {
        const sign = token[0] === '-' ? -1 : 1;
        return sign * parseInt(token.replace(/^[+-]?0x/i, ''), 16);
      }
      const value = Number(token);
      if (Number.isNaN(value)) throw new TypeError(`cannot parse "${token}" as a number`);
      return value;
    });
}

function describeScan(nums) {
  const index = findFirstDuplicateIndex(nums);
  if (index < 0) return `${nums.length} values scanned: no duplicate found`;
  const value = nums[index];
  return `${nums.length} values scanned: ${value} (${toHex(value)}) repeats at index ${index}`;
}

