const MAX_PATH_LENGTH = 1024;
const MAX_SEGMENTS = 32;
const MAX_SEGMENT_LENGTH = 128;
const PARSE_CACHE_LIMIT = 256;
const PREVIEW_LENGTH = 64;
const HEX_RADIX = 16;
const FIRST_PRINTABLE_CODE = 32;
const DELETE_CODE = 127;

const parseCache = new Map();

function parsePath(path) {
  if (typeof path !== 'string') return null;
  if (path.length === 0 || path.length > MAX_PATH_LENGTH) return null;
  const cached = parseCache.get(path);
  if (cached) return cached;
  const segments = path.split('.');
  if (segments.length > MAX_SEGMENTS) return null;
  for (const segment of segments) {
    if (segment.length === 0) return null;
    if (segment.length > MAX_SEGMENT_LENGTH) return null;
  }
  if (parseCache.size >= PARSE_CACHE_LIMIT) {
    parseCache.delete(parseCache.keys().next().value);
  }
  parseCache.set(path, segments);
  return segments;
}

function getNestedProperty(obj, path) {
  const segments = parsePath(path);
  if (segments === null) return undefined;
  let current = obj;
  for (const segment of segments) {
    if (current === null || current === undefined) return undefined;
    if (typeof current !== 'object' && typeof current !== 'function') return undefined;
    if (!(segment in current)) return undefined;
    current = current[segment];
  }
  return current;
}

function escapeString(text) {
  let out = '';
  for (const char of text) {
    const code = char.codePointAt(0);
    if (code < FIRST_PRINTABLE_CODE || code === DELETE_CODE) {
      out += '\\x' + code.toString(HEX_RADIX).padStart(2, '0');
    } else if (char === '"' || char === '\\') {
      out += '\\' + char;
    } else {
      out += char;
    }
  }
  return out;
}

