  if (value === undefined) return 'undefined';
  if (typeof value === 'string') {
    const escaped = escapeString(value);
    if (escaped.length > PREVIEW_LENGTH) {
      return '"' + escaped.slice(0, PREVIEW_LENGTH) + '\u2026"';
