  let width = 0;
  for (const path of paths) {
    if (path.length > width) width = path.length;
  }
  return paths
    .map((path) => `${path.padEnd(width, ' ')} => ${formatValue(getNestedProperty(obj, path))}`)
    .join('\n');
}

