'use strict';

const WORD_BITS = 32;
const SEGMENT_SIZE = 4096;
const MIN_BASE_LIMIT = 64;
const BASE_BLOCK = 1024;
const COLUMN_WIDTH = 16;
const DEFAULT_LIMIT = 65535;

function makeBitset(bitCount) {
  return new Uint32Array(Math.ceil(bitCount / WORD_BITS));
}

function bitGet(bits, index) {
  const word = (index / WORD_BITS) | 0;
  return (bits[word] >>> (index % WORD_BITS)) & 1;
}

function bitSet(bits, index) {
  const word = (index / WORD_BITS) | 0;
  bits[word] |= 1 << (index % WORD_BITS);
}

let baseCache = { limit: 0, primes: [] };

function basePrimesUpTo(limit) {
  const needed = Math.max(MIN_BASE_LIMIT, limit);
  if (needed <= baseCache.limit) return baseCache.primes;
  const target = Math.ceil(needed / BASE_BLOCK) * BASE_BLOCK;
  const bits = makeBitset(target + 1);
  const primes = [];
  for (let i = 2; i <= target; i++) {
    if (bitGet(bits, i)) continue;
    primes.push(i);
    for (let j = i * i; j <= target; j += i) bitSet(bits, j);
  }
  baseCache = { limit: target, primes };
  return primes;
}

function sumPrimesUpTo(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) {
    throw new TypeError('sumPrimesUpTo expects a finite number');
  }
  const limit = Math.floor(n);
  if (limit < 2) return 0;
  const basePrimes = basePrimesUpTo(Math.floor(Math.sqrt(limit)));
  let sum = 0;
  for (let low = 2; low <= limit; low += SEGMENT_SIZE) {
    const high = Math.min(low + SEGMENT_SIZE - 1, limit);
    const bits = makeBitset(SEGMENT_SIZE);
    for (const p of basePrimes) {
      if (p * p > high) break;
      let start = Math.ceil(low / p) * p;
      if (start < p * p) start = p * p;
      for (let j = start; j <= high; j += p) bitSet(bits, j - low);
    }
    for (let i = low; i <= high; i++) {
      if (!bitGet(bits, i - low)) sum += i;
    }
  }
  return sum;
}

function formatRow(n) {
  const left = String(n).padStart(COLUMN_WIDTH);
  const right = String(sumPrimesUpTo(n)).padStart(COLUMN_WIDTH);
  return `n =${left}   sum =${right}`;
}

function main(argv) {
  const parsed = argv.map(Number).filter((v) => Number.isFinite(v));
  const inputs = parsed.length > 0 ? parsed : [DEFAULT_LIMIT];
  for (const value of inputs) console.log(formatRow(value));
}

main(process.argv.slice(2));

module.exports = { sumPrimesUpTo, basePrimesUpTo, formatRow };

