'use strict';

const MAX_INPUT_LENGTH = 4096;
const INITIAL_STACK_CAPACITY = 16;
const STACK_EMPTY = 255;
const MAX_CACHE_ENTRIES = 1024;
const SNIPPET_LIMIT = 32;

const CLOSE_TO_OPEN = new Map([[')', '('], [']', '['], ['}', '{']]);
const OPENERS = new Set(CLOSE_TO_OPEN.values());

function assertBracketString(s) {
  if (typeof s !== 'string') throw new TypeError('input must be a string');
  if (s.length > MAX_INPUT_LENGTH) {
    throw new RangeError(`input exceeds ${MAX_INPUT_LENGTH} characters`);
  }
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (!OPENERS.has(ch) && !CLOSE_TO_OPEN.has(ch)) {
      throw new RangeError(`character "${ch}" at index ${i} is not a bracket`);
    }
  }
}

class ByteStack {
  constructor() {
    this.data = new Uint8Array(INITIAL_STACK_CAPACITY);
    this.size = 0;
  }
  push(code) {
    if (this.size === this.data.length) {
      const capacity = Math.min(this.data.length * 2, MAX_INPUT_LENGTH);
      const grown = new Uint8Array(capacity);
      grown.set(this.data);
      this.data = grown;
    }
    this.data[this.size++] = code;
  }
  pop() {
    return this.size > 0 ? this.data[--this.size] : STACK_EMPTY;
  }
}

const resultCache = new Map();

function isValidParentheses(s) {
  assertBracketString(s);
  if (resultCache.has(s)) return resultCache.get(s);
  const stack = new ByteStack();
  let valid = true;
  for (let i = 0; i < s.length && valid; i++) {
    const ch = s[i];
    if (OPENERS.has(ch)) stack.push(s.charCodeAt(i));
    else valid = stack.pop() === CLOSE_TO_OPEN.get(ch).charCodeAt(0);
  }
  valid = valid && stack.size === 0;
  if (resultCache.size >= MAX_CACHE_ENTRIES) resultCache.clear();
  resultCache.set(s, valid);
  return valid;
}

function describe(s) {
  const head = s.slice(0, SNIPPET_LIMIT);
  const snippet = s.length > head.length ? `${head}...` : s;
  return `"${snippet}" -> ${isValidParentheses(s)}`;
}

function main() {
  const samples = ['()[]{}', '([)]', '', '{[()]}', '(((', '){', '[]'.repeat(64)];
  for (const sample of samples) console.log(describe(sample));
  try {
    isValidParentheses('(a)');
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { isValidParentheses, describe, assertBracketString };

