  const mid = (lo + hi) >>> 1;
  if (a[mid] < a[lo]) [a[mid], a[lo]] = [a[lo], a[mid]];
  if (a[hi] < a[lo]) [a[hi], a[lo]] = [a[lo], a[hi]];
  if (a[mid] < a[hi]) [a[mid], a[hi]] = [a[hi], a[mid]];
  const pivot = a[hi];
  let store = lo;
  for (let i = lo; i < hi; i++) {
    if (a[i] < pivot) {
