}

function hashOf(str, from, to) {
  let hash = 0;
  for (let i = from; i < to; i++) {
    hash = (hash * HASH_BASE + str.charCodeAt(i)) % HASH_MODULUS;
  }
  return hash;
}

function basePower(exponent) {
  let power = 1;
  for (let i = 0; i < exponent; i++) {
    power = (power * HASH_BASE) % HASH_MODULUS;
  }
  return power;
}

