'use strict';

const WORD_BITS = 32;
const BITSET_LIMIT = 1024;
const DENSE_N = 256;

function assertValidInput(nums) {
  if (!Array.isArray(nums)) {
    throw new TypeError('nums must be an array');
  }
  const n = nums.length;
  for (const value of nums) {
    if (!Number.isInteger(value) || value < 0 || value > n) {
      throw new RangeError(`value out of range [0, ${n}]: ${value}`);
    }
  }
}

function missingViaBitset(nums) {
  const n = nums.length;
  const words = new Uint32Array(Math.floor(n / WORD_BITS) + 1);
  for (const value of nums) {
    words[Math.floor(value / WORD_BITS)] |= 1 << (value % WORD_BITS);
  }
  for (let candidate = 0; candidate <= n; candidate++) {
    const bit = 1 << (candidate % WORD_BITS);
    if ((words[Math.floor(candidate / WORD_BITS)] & bit) === 0) {
      return candidate;
    }
  }
  return n;
}

function missingViaXor(nums) {
  let acc = nums.length;
  for (let i = 0; i < nums.length; i++) {
    acc ^= i ^ nums[i];
  }
  return acc;
}

function findMissingNumber(nums) {
  assertValidInput(nums);
  return nums.length <= BITSET_LIMIT ? missingViaBitset(nums) : missingViaXor(nums);
}

function formatMissing(value) {
  if (value <= 255) {
    const byte = value & 255;
    return `${value} (0x${byte.toString(16).padStart(2, '0')})`;
  }
  const word = value & 65535;
  return `${value} (0x${word.toString(16).padStart(4, '0')})`;
}

function buildShuffledSequence(n, missing) {
  const values = [];
  for (let i = 0; i <= n; i++) {
    if (i !== missing) {
      values.push(i);
    }
  }
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  return values;
}

function main() {
  const cases = [
    [3, 0, 1],
    [0, 1],
    buildShuffledSequence(DENSE_N, 128),
    buildShuffledSequence(4096, 0),
  ];
  console.log('-'.repeat(64));
  for (const nums of cases) {
    const label = nums.length > 16 ? `array of ${nums.length} values` : `[${nums.join(', ')}]`;
    console.log(`${label} -> ${formatMissing(findMissingNumber(nums))}`);
  }
}

main();

module.exports = { findMissingNumber, formatMissing, buildShuffledSequence };

