const ASCII_LIMIT = 128;
const CASE_OFFSET = 32;
const LETTER_BASE = 64;
const ALPHABET_SIZE = 26;
const COLUMN_BLOCK = 1024;
const MAX_COLUMNS = 16 * COLUMN_BLOCK;
const MAX_ROWS = COLUMN_BLOCK * COLUMN_BLOCK;
const LEGACY_MAX_COLUMNS = 256;
const LEGACY_MAX_ROW_INDEX = 65535;
const LOWER_A = 97;
const LOWER_Z = 122;

function letterValue(code, title) {
  if (code >= ASCII_LIMIT) {
    throw new RangeError(`Column title "${title}" contains a non-ASCII character`);
  }
  if (code >= LOWER_A && code <= LOWER_Z) {
    code -= CASE_OFFSET;
  }
  const value = code - LETTER_BASE;
  if (value < 1 || value > ALPHABET_SIZE) {
    throw new RangeError(`Column title "${title}" must contain only letters A-Z`);
  }
  return value;
}

function columnToNumber(columnTitle) {
  if (typeof columnTitle !== 'string' || columnTitle.length === 0) {
    throw new TypeError('columnToNumber expects a non-empty string');
  }
  let number = 0;
  for (let i = 0; i < columnTitle.length; i++) {
    number = number * ALPHABET_SIZE + letterValue(columnTitle.charCodeAt(i), columnTitle);
  }
  return number;
}

function numberToColumn(columnNumber) {
  if (!Number.isInteger(columnNumber) || columnNumber < 1) {
    throw new RangeError('numberToColumn expects a positive integer');
  }
  let title = '';
  let n = columnNumber;
  while (n > 0) {
    const value = (n - 1) % ALPHABET_SIZE + 1;
    title = String.fromCharCode(LETTER_BASE + value) + title;
    n = (n - value) / ALPHABET_SIZE;
  }
  return title;
}

function parseCellReference(reference) {
  const match = /^\$?([A-Za-z]+)\$?([0-9]+)$/.exec(String(reference).trim());
  if (!match) {
    throw new SyntaxError(`"${reference}" is not a valid cell reference`);
  }
  const column = columnToNumber(match[1]);
  const row = Number(match[2]);
  if (column > MAX_COLUMNS) {
    throw new RangeError(`Column ${match[1]} exceeds the sheet limit of ${MAX_COLUMNS} columns`);
  }
  if (row > MAX_ROWS) {
    throw new RangeError(`Row ${row} exceeds the sheet limit of ${MAX_ROWS} rows`);
  }
  return { column, row, title: numberToColumn(column) };
}

