const FILTER_MODULUS = 256;
const SMALL_LIMIT = 4096;
const MAX_ROOT = 65535;
const REPORT_WIDTH = 64;
const SCAN_LIMIT = 1024;
const HEX_RADIX = 16;

const MAX_SUPPORTED = MAX_ROOT * MAX_ROOT;

function buildResidueTable(modulus) {
  const table = new Uint8Array(modulus);
  for (let i = 0; i < modulus; i += 1) {
    table[(i * i) % modulus] = 1;
  }
  return table;
}

const RESIDUES = buildResidueTable(FILTER_MODULUS);

const SMALL_SQUARES = new Set();
for (let i = 0; i * i <= SMALL_LIMIT; i += 1) {
  SMALL_SQUARES.add(i * i);
}

function integerSqrt(num) {
  let low = 0;
  let high = MAX_ROOT;
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    if (mid * mid <= num) low = mid;
    else high = mid - 1;
  }
  return low;
}

function isPerfectSquare(num) {
  if (!Number.isInteger(num) || num < 1 || num > MAX_SUPPORTED) return false;
  if (num <= SMALL_LIMIT) return SMALL_SQUARES.has(num);
  if (RESIDUES[num % FILTER_MODULUS] === 0) return false;
  const root = integerSqrt(num);
  return root * root === num;
}

function parseNumber(text) {
  const token = String(text).trim().toLowerCase();
  const hex = token.startsWith('0x');
  const digits = hex ? token.slice(2) : token;
  const radix = hex ? HEX_RADIX : 10;
  if (digits.length === 0) throw new SyntaxError(`empty number: "${text}"`);
  let value = 0;
  for (const ch of digits) {
    const digit = parseInt(ch, radix);
    if (Number.isNaN(digit)) throw new SyntaxError(`bad digit "${ch}" in "${text}"`);
    value = value * radix + digit;
  }
  return value;
}

function describe(num) {
  if (!Number.isInteger(num) || num < 1) throw new RangeError('positive integer required');
  if (num > MAX_SUPPORTED) throw new RangeError(`${num} exceeds the supported range`);
  const label = String(num).padStart(12);
  const root = integerSqrt(num);
  if (isPerfectSquare(num)) return `${label} : perfect square, root ${root}`;
  return `${label} : not a square, between ${root * root} and ${(root + 1) * (root + 1)}`;
}

function countPerfectSquares(limit) {
  let found = 0;
  for (let i = 1; i <= limit; i += 1) {
    if (isPerfectSquare(i)) found += 1;
  }
  return found;
}

function main(argv) {
  const inputs = argv.length > 0 ? argv : ['16', '14', '0x40', '1048576', '4294967296'];
  console.log('='.repeat(REPORT_WIDTH));
  for (const token of inputs) {
    try {
      console.log(describe(parseNumber(token)));
    } catch (err) {
      console.log(`${String(token).padStart(12)} : ${err.message}`);
    }
  }
  console.log('-'.repeat(REPORT_WIDTH));
  console.log(`perfect squares in [1, ${SCAN_LIMIT}]: ${countPerfectSquares(SCAN_LIMIT)}`);
}

