const MAX_LABEL_WIDTH = 32;
const WORD_RE = /[\p{L}\p{N}]/u;

function classifyCode(cp) {
  let flags = 0;
  if (cp < 128) {
    if ((cp >= 65 && cp <= 90) || (cp >= 97 && cp <= 122)) flags |= FLAG_LETTER;
    else if (cp >= 48 && cp <= 57) flags |= FLAG_DIGIT;
  } else if (WORD_RE.test(String.fromCharCode(cp))) {
    flags |= FLAG_LETTER;
  }
  if (cp === 39 || cp === 45) flags |= FLAG_JOINER;
  return flags;
}

function buildLatin1ClassTable() {
  const table = new Uint8Array(256);
  for (let cp = 0; cp < table.length; cp++) table[cp] = classifyCode(cp);
  return table;
}

const LATIN1_CLASS = buildLatin1ClassTable();

function isWordCodePoint(cp) {
  if (cp <= 255) return (LATIN1_CLASS[cp] & WORD_FLAGS) !== 0;
  if (cp <= 65535) return WORD_RE.test(String.fromCharCode(cp));
  return WORD_RE.test(String.fromCodePoint(cp));
}

function isJoinerCodePoint(cp) {
  if (cp <= 255) return (LATIN1_CLASS[cp] & FLAG_JOINER) !== 0;
  return cp === 8217;
}

