  if (typeof url !== 'string' || url.length > MAX_URL_LENGTH) return {};
  const start = url.indexOf('?');
  if (start < 0) return {};
  const hash = url.indexOf('#', start);
  const query = url.slice(start + 1, hash < 0 ? url.length : hash);
