'use strict';

const MAX_PERMUTATIONS = 4096;
const MAX_INPUT_LENGTH = 16;
const ASCII_LIMIT = 128;
const LATIN1_LIMIT = 255;
const HASH_MASK = 65535;
const PREVIEW_LIMIT = 32;
const LINE_WIDTH = 64;

function classifyCharset(chars) {
  let charset = 'ascii';
  for (const ch of chars) {
    const code = ch.codePointAt(0);
    if (code > LATIN1_LIMIT) return 'unicode';
    if (code >= ASCII_LIMIT) charset = 'latin1';
  }
  return charset;
}

function countUniquePermutations(chars) {
  const counts = new Map();
  for (const ch of chars) counts.set(ch, (counts.get(ch) || 0) + 1);
  let total = 1;
  for (let i = 1; i <= chars.length; i += 1) total *= i;
  for (const repeat of counts.values()) {
    for (let i = 2; i <= repeat; i += 1) total /= i;
  }
  return total;
}

function validateInput(str) {
  if (typeof str !== 'string') {
    throw new TypeError('getStringPermutations expects a string');
  }
  const chars = Array.from(str);
  if (chars.length > MAX_INPUT_LENGTH) {
    throw new RangeError(`input of ${chars.length} characters is too long`);
  }
  const total = countUniquePermutations(chars);
  if (total > MAX_PERMUTATIONS) {
    throw new RangeError(`"${str}" yields ${total} permutations, too many to build`);
  }
  return chars;
}

function getStringPermutations(str) {
  const chars = validateInput(str).sort();
  if (chars.length === 0) return [];
  const result = [];
  const used = new Array(chars.length).fill(false);
  const current = [];
  const walk = () => {
    if (current.length === chars.length) {
      result.push(current.join(''));
      return;
    }
    for (let i = 0; i < chars.length; i += 1) {
      if (used[i]) continue;
      if (i > 0 && chars[i] === chars[i - 1] && !used[i - 1]) continue;
      used[i] = true;
      current.push(chars[i]);
      walk();
      current.pop();
      used[i] = false;
    }
  };
  walk();
  return result;
}

function fingerprint(list) {
  let hash = 7;
  for (const item of list) {
    for (let i = 0; i < item.length; i += 1) {
      hash = (hash * 31 + item.charCodeAt(i)) & HASH_MASK;
    }
  }
  return hash.toString(16).padStart(4, '0');
}

function formatColumns(list) {
  const width = list.reduce((max, item) => Math.max(max, item.length), 0) + 2;
  const perLine = Math.max(1, Math.floor(LINE_WIDTH / width));
  const lines = [];
  for (let i = 0; i < list.length; i += perLine) {
    const row = list.slice(i, i + perLine).map((item) => item.padEnd(width));
    lines.push(row.join('').trimEnd());
  }
  return lines;
}

function buildReport(str) {
  const perms = getStringPermutations(str);
  const shown = perms.slice(0, PREVIEW_LIMIT);
  const lines = [`input: "${str}"`];
  lines.push(`charset: ${classifyCharset(Array.from(str))}`);
  lines.push(`unique permutations: ${perms.length} (digest ${fingerprint(perms)})`);
  lines.push(...formatColumns(shown));
  if (perms.length > shown.length) {
    lines.push(`... ${perms.length - shown.length} more not shown`);
  }
  return lines.join('\n');
}

for (const sample of ['ab', 'abc', 'aab', 'café']) {
  console.log(buildReport(sample));
  console.log('');
}

module.exports = { getStringPermutations, buildReport, classifyCharset };

