// Utilities for dates written as MM/DD/YYYY, with a compact packed form
// used by the report at the bottom of this file.

// Bit i is set when month i (1 = January) has 31 days.
const LONG_MONTH_MASK =
  2 |    // January
  8 |    // March
  32 |   // May
  128 |  // July
  256 |  // August
  1024 | // October
  4096;  // December

function isLeapYear(year) {
  if (year % 400 === 0) return true;
  if (year % 100 === 0) return false;
  return year % 4 === 0;
}

function daysInMonth(month, year) {
  if (month === 2) return isLeapYear(year) ? 29 : 28;
  return (LONG_MONTH_MASK >> month) & 1 ? 31 : 30;
}

// Diagnostic bits returned by diagnoseDateMDY.
const ERR_FORMAT = 1;
const ERR_MONTH = 2;
const ERR_DAY = 4;
const ERR_YEAR = 8;
const ERR_OVERFLOW = 16;

function diagnoseDateMDY(dateStr) {
  if (typeof dateStr !== 'string') return ERR_FORMAT;
  const parts = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(dateStr);
  if (!parts) return ERR_FORMAT;
  const month = Number(parts[1]);
  const day = Number(parts[2]);
  const year = Number(parts[3]);
  let flags = 0;
  if (month < 1 || month > 12) flags |= ERR_MONTH;
  if (day < 1) flags |= ERR_DAY;
  if (year < 1) flags |= ERR_YEAR;
  if (flags === 0 && day > daysInMonth(month, year)) flags |= ERR_OVERFLOW;
  return flags;
}

function isValidDateMDY(dateStr) {
  return diagnoseDateMDY(dateStr) === 0;
}

function describeErrors(flags) {
  const notes = [];
  if (flags & ERR_FORMAT) notes.push('not in MM/DD/YYYY form');
  if (flags & ERR_MONTH) notes.push('month out of range');
  if (flags & ERR_DAY) notes.push('day out of range');
  if (flags & ERR_YEAR) notes.push('year out of range');
  if (flags & ERR_OVERFLOW) notes.push('day beyond end of month');
  return notes.join('; ');
}

// Pack as year:16 | month:8 | day:8 so a valid date fits in one 32-bit word.
function packDateMDY(dateStr) {
  if (!isValidDateMDY(dateStr)) return -1;
  const [mm, dd, yyyy] = dateStr.split('/');
  let packed = Number(yyyy) & 65535;
  packed = (packed << 8) | Number(mm);
  packed = (packed << 8) | Number(dd);
  return packed >>> 0;
}

function formatPackedDate(packed) {
  const year = packed >>> 16;
  const month = (packed >>> 8) & 255;
  const day = packed & 255;
  const mm = String(month).padStart(2, '0');
  const dd = String(day).padStart(2, '0');
  return `${mm}/${dd}/${String(year).padStart(4, '0')}`;
}

const samples = ['12/25/2023', '02/29/2023', '02/29/2024', '13/01/2020', '4/5/2021'];
for (const sample of samples) {
  const packed = packDateMDY(sample);
  const detail = packed < 0
    ? describeErrors(diagnoseDateMDY(sample))
    : `packed=${packed} -> ${formatPackedDate(packed)}`;
  console.log(`${sample}: ${isValidDateMDY(sample)} (${detail})`);
}

