const SMALL_TABLE = 64;
const MEDIUM_TABLE = 256;
const LARGE_TABLE = 1024;
const PREVIEW_LIMIT = 16;
const LABEL_WIDTH = 32;

function fnv1a(str) {
  let h = FNV_OFFSET;
