const SIEVE_LIMIT = 4096;
const WORD_BITS = 32;
const TRIAL_LIMIT = 256;
const BYTE_MAX = 255;
const WORD_MAX = 65535;
const HEX_BASE = 16;

const compositeBits = new Uint32Array(SIEVE_LIMIT / WORD_BITS);
const trialPrimes = [];

function markComposite(n) {
  compositeBits[(n / WORD_BITS) | 0] |= 1 << (n % WORD_BITS);
}

function isCompositeBit(n) {
  return ((compositeBits[(n / WORD_BITS) | 0] >>> (n % WORD_BITS)) & 1) === 1;
}

for (let i = 2; i * i < SIEVE_LIMIT; i++) {
  if (isCompositeBit(i)) continue;
  for (let j = i * i; j < SIEVE_LIMIT; j += i) markComposite(j);
}
for (let i = 2; i < TRIAL_LIMIT; i++) {
  if (!isCompositeBit(i)) trialPrimes.push(i);
}

function modPow(base, exp, mod) {
  let result = 1n;
  let b = base % mod;
  for (let e = exp; e > 0n; e >>= 1n) {
    if (e & 1n) result = (result * b) % mod;
    b = (b * b) % mod;
  }
  return result;
}

function millerRabin(n) {
  const big = BigInt(n);
  let d = big - 1n;
  let r = 0n;
  while ((d & 1n) === 0n) { d >>= 1n; r++; }
  for (const a of [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n]) {
    if (a % big === 0n) continue;
    let x = modPow(a, d, big);
    if (x === 1n || x === big - 1n) continue;
    let witnessed = true;
    for (let i = 1n; i < r && witnessed; i++) {
      x = (x * x) % big;
      if (x === big - 1n) witnessed = false;
    }
    if (witnessed) return false;
  }
  return true;
}

function isPrime(n) {
  if (n < 2) return false;
  if (n < SIEVE_LIMIT) return !isCompositeBit(n);
  for (const p of trialPrimes) {
    if (n % p === 0) return false;
  }
  if (n <= WORD_MAX) return true;
  return millerRabin(n);
}

function findNextPrime(num) {
  if (!Number.isSafeInteger(num)) throw new TypeError(`not a safe integer: ${num}`);
  if (num <= 2) return 2;
  let candidate = num % 2 === 0 ? num + 1 : num;
  while (!isPrime(candidate)) candidate += 2;
  return candidate;
}

function formatPrime(p) {
  const width = p <= BYTE_MAX ? 2 : p <= WORD_MAX ? 4 : 8;
  return '0x' + p.toString(HEX_BASE).padStart(width, '0');
}

