const MAX_INPUT_LENGTH = 4096;
const SPACE_CODE = 32;
const BYTE_RANGE = 256;
const HEX_BASE = 16;
const PREVIEW_LIMIT = 64;

function stringToWords(str) {
  if (typeof str !== 'string') {
    throw new TypeError('stringToWords expects a string');
  }
  if (str.length > MAX_INPUT_LENGTH) {
    throw new RangeError('input longer than ' + MAX_INPUT_LENGTH + ' characters');
  }
  const words = [];
  let start = -1;
  for (let i = 0; i <= str.length; i++) {
    const code = i < str.length ? str.charCodeAt(i) : SPACE_CODE;
    if (code === SPACE_CODE) {
      if (start >= 0) {
        words.push(str.slice(start, i));
        start = -1;
      }
    } else if (start < 0) {
      start = i;
    }
  }
  return words;
}

function classifyCodePoint(code) {
  if (code < 128) return 'ascii';
  if (code <= 255) return 'latin1';
  if (code <= 65535) return 'bmp';
  return 'astral';
}

function formatCodePoint(code) {
  const width = code > 65535 ? 6 : 4;
  return 'U+' + code.toString(HEX_BASE).toUpperCase().padStart(width, '0');
}

function byteHistogram(words) {
  const counts = new Array(BYTE_RANGE).fill(0);
  for (const word of words) {
    for (const ch of word) {
      const code = ch.codePointAt(0);
      if (code < BYTE_RANGE) counts[code]++;
    }
  }
  return counts;
}

function mostCommonByte(counts) {
  let best = -1;
  for (let code = 0; code < BYTE_RANGE; code++) {
    if (best < 0 || counts[code] > counts[best]) best = code;
  }
  return counts[best] > 0 ? { code: best, hits: counts[best] } : null;
}

function describeWords(words) {
  const lines = [];
  for (const word of words) {
    const shown = word.length > PREVIEW_LIMIT ? word.slice(0, PREVIEW_LIMIT) + '...' : word;
    const kinds = new Set();
    for (const ch of word) kinds.add(classifyCodePoint(ch.codePointAt(0)));
