'use strict';

const BYTE_MASK = 255;
const WORD_MASK = 65535;
const KIB = 1024;
const LABEL_WIDTH = 32;
const ASCII_LIMIT = 128;
const UNICODE_DASHES = new Set(['\u2010', '\u2012', '\u2013', '\u2014', '\u2212']);

function basicCalculator(num1, num2, operator) {
  switch (operator) {
    case '+': return num1 + num2;
    case '-': return num1 - num2;
    case '*': return num1 * num2;
    case '/': return num2 === 0 ? null : num1 / num2;
    default: return null;
  }
}

function normalize(expr) {
  return Array.from(String(expr)).map((ch) => {
    if (ch.codePointAt(0) < ASCII_LIMIT) return ch;
    return UNICODE_DASHES.has(ch) ? '-' : '?';
  }).join('');
}

function parseOperand(token) {
  const text = token.trim();
  if (/^[+-]?0x[0-9a-f]+$/i.test(text)) {
    const sign = text[0] === '-' ? -1 : 1;
    return sign * parseInt(text.replace(/^[+-]?0x/i, ''), 16);
  }
  const match = /^([+-]?\d+(?:\.\d+)?)(B|KiB|MiB)?$/.exec(text);
  if (!match) return NaN;
  const units = { B: 1, KiB: KIB, MiB: KIB * KIB };
  return Number(match[1]) * (match[2] ? units[match[2]] : 1);
}

function evaluate(expr) {
  const tokens = normalize(expr).split(/\s+/).filter(Boolean);
  if (tokens.length !== 3) return null;
  const left = parseOperand(tokens[0]);
  const right = parseOperand(tokens[2]);
  if (Number.isNaN(left) || Number.isNaN(right)) return null;
  return basicCalculator(left, right, tokens[1]);
}

function formatWord(value) {
  const word = Math.round(Math.abs(value)) & WORD_MASK;
  const high = Math.floor(word / 256);
  const low = word & BYTE_MASK;
  const hex = (byte) => byte.toString(16).padStart(2, '0');
  return '0x' + hex(high) + hex(low);
}

function formatSize(bytes) {
  const abs = Math.abs(bytes);
  if (abs >= KIB * KIB) return (bytes / (KIB * KIB)).toFixed(2) + ' MiB';
  if (abs >= KIB) return (bytes / KIB).toFixed(2) + ' KiB';
  return bytes + ' B';
}

function describeBytes(bytes) {
  const pages = basicCalculator(bytes, 4096, '/');
  const lines = basicCalculator(bytes, 64, '/');
  return `${Math.ceil(pages)} page(s), ${Math.ceil(lines)} cache line(s)`;
}

function report(expr) {
  const label = expr.padEnd(LABEL_WIDTH);
  const result = evaluate(expr);
  if (result === null || Number.isNaN(result)) return label + 'invalid or undefined';
  let line = `${label}${result}  ${formatSize(result)}  ${formatWord(result)}`;
  if (Math.abs(result) > WORD_MASK) line += '  (word view truncated)';
  return line;
}

function main() {
  const expressions = ['10 + 5', '10 / 0', '0x1000 / 4096', '2KiB + 512B', '1MiB \u2212 256KiB', '5 % 3'];
  for (const expr of expressions) console.log(report(expr));
  console.log(describeBytes(evaluate('2KiB + 512B')));
}

main();

module.exports = { basicCalculator, parseOperand, evaluate, formatWord, formatSize, describeBytes, report };

