  const clipped = shown.length > DISPLAY_WIDTH ? `...${shown.slice(-DISPLAY_WIDTH)}` : shown;
  const verdict = problem === null ? 'valid' : `invalid: ${problem}`;
  return `${clipped.padEnd(DISPLAY_WIDTH)} | ${verdict}`;
}

function main() {
